window.PM_DATA={"secciones":[{"nombre":"기초","grupos":[{"nombre":"운동의 기초","icono":"🧭","temas":[1,2,3,4]},{"nombre":"평가","icono":"📋","temas":[5,6,7,8,9]}]},{"nombre":"부위별 특수검사","grupos":[{"nombre":"어깨관절","icono":"💪","temas":[10,11,12]},{"nombre":"팔꿉·손목관절·손","icono":"✋","temas":[13,14]},{"nombre":"척추·골반","icono":"🦴","temas":[15,16,17]},{"nombre":"고관절·무릎관절","icono":"🦵","temas":[18,19,20]},{"nombre":"발목관절·발","icono":"🦶","temas":[21]},{"nombre":"신경학적 검사","icono":"🧠","temas":[22]}]},{"nombre":"질환·외상과 재활","grupos":[{"nombre":"어깨관절","icono":"💪","temas":[23,24,25]},{"nombre":"스포츠·힘줄·근육","icono":"🏃","temas":[26,27,28,29,30]},{"nombre":"정형외과·외상","icono":"🦴","temas":[31,32,33]},{"nombre":"척추","icono":"🧍","temas":[34,35,36]},{"nombre":"신경계","icono":"🧠","temas":[37,38,39,40,41]}]},{"nombre":"치료와 중재","grupos":[{"nombre":"수기와 물리치료 기기","icono":"🤲","temas":[42,43,44,45,46,47]},{"nombre":"운동치료와 전문 분야","icono":"🩺","temas":[48,49,50,51,52,53]},{"nombre":"임상 증례","icono":"🧩","temas":[54]}]}],"temas":{"1":{"id":1,"title":"운동면과 운동축","lead":"신체의 운동은 3개의 기본면과 그에 수직인 운동축으로 기술합니다. 면과 축의 대응은 평가·기록·동작 분석의 토대입니다.","sheet":{"kind":"basics","items":[{"h":"기준 자세","t":"면과 축은 해부학적 자세를 기준으로 정의합니다. ROM 측정의 0°는 기본자세(아래팔은 중간위)이므로 둘의 차이에 주의합니다."},{"h":"시상면","t":"신체를 좌우로 나누는 면입니다. 굴곡·신전, 발목의 배측굴곡·저측굴곡이 일어나며 운동축은 전두-수평축입니다."},{"h":"전두면","t":"신체를 앞뒤로 나누는 면입니다. 외전·내전, 체간의 측굴이 일어나며 운동축은 시상-수평축입니다."},{"h":"수평면","t":"신체를 위아래로 나누는 면입니다. 내회전·외회전, 체간 회전, 어깨의 수평굴곡·수평신전이 일어나며 운동축은 수직축입니다."},{"h":"면과 축의 관계","t":"운동축은 반드시 그 운동면에 수직으로 지납니다. 면과 축을 짝지어 외우면 처음 보는 운동도 정리할 수 있습니다."},{"h":"복합 운동","t":"실제 동작은 여러 면에 걸쳐 일어납니다. 보행이나 투구 등은 면별로 나누어 관찰하고 그 조합으로 분석합니다."}]},"keypoints":["시상면 = 굴곡·신전, 축은 전두-수평축","전두면 = 외전·내전, 축은 시상-수평축","수평면 = 회전, 축은 수직축","운동축은 항상 그 운동면에 수직으로 지남","동작 분석은 면별로 나누어 관찰함"],"case":{"text":"20세 육상 선수. 바로 누운 자세에서 하지를 곧게 펴 앞쪽으로 들어 올리는 운동(고관절)을 기록하려 한다. 어떤 면과 축으로 기재하는가?","answer":"고관절의 전방 거상은 굴곡으로, 시상면의 운동이며 축은 전두-수평축입니다. 전두면의 외전과 혼동하지 않도록, 신체를 좌우로 나누는 면의 운동인지로 판단합니다."},"questions":[{"level":"기초","q":"외전·내전이 일어나는 운동면은?","options":["시상면","전두면","수평면","사선면"],"answer":1,"exp":"전두면은 신체를 앞뒤로 나누는 면으로 외전·내전이 일어납니다. 운동축은 시상-수평축입니다."},{"level":"기초","q":"수평면에서 일어나는 회전 운동의 운동축은?","options":["전두-수평축","시상-수평축","사축","수직축"],"answer":3,"exp":"수평면의 운동(회전)은 그 면에 수직인 수직축을 중심으로 일어납니다."},{"level":"중급","q":"시상면에서 일어나는 운동은?","options":["체간의 측굴","발목의 배측굴곡","고관절의 외회전","어깨관절의 외전"],"answer":1,"exp":"배측굴곡·저측굴곡은 굴곡·신전과 같은 시상면의 운동입니다. 측굴과 외전은 전두면, 외회전은 수평면의 운동입니다."},{"level":"중급","q":"어깨관절의 수평굴곡이 일어나는 운동면은?","options":["시상면","전두면","수평면","어느 면에도 속하지 않음"],"answer":2,"exp":"수평굴곡·수평신전은 어깨 90° 외전위에서 상지를 수평면 위로 움직이는 운동이며, 축은 수직축입니다."},{"level":"임상","q":"위팔을 내린 자세, 팔꿈치 90° 굴곡위에서 어깨관절 외회전을 측정한다. 운동면과 축의 조합으로 옳은 것은?","options":["시상면·전두-수평축","전두면·시상-수평축","수평면·수직축","수평면·전두-수평축"],"answer":2,"exp":"팔을 내린 자세에서 어깨의 내회전·외회전은 수평면의 운동으로, 위팔의 장축(수직축)을 중심으로 일어납니다."},{"level":"임상","q":"보행 관찰에서 입각기에 골반이 유각측으로 내려가는 소견을 보였다. 주로 관찰하는 면은?","options":["전두면","시상면","수평면","면을 특정할 수 없음"],"answer":0,"exp":"골반의 좌우 기울기는 전두면의 운동으로 앞이나 뒤에서 관찰합니다. 중간볼기근(중둔근)의 기능 저하를 생각할 소견입니다."}],"seccion":"기초","grupo":"운동의 기초","icono":"🧭","mapa":"img/mapas/t01.jpg","fichas":[],"secuencias":[]},"2":{"id":2,"title":"생체역학","lead":"생체역학은 힘과 운동의 관계로 신체의 움직임을 이해하는 학문입니다. 지레·모멘트·무게중심을 알면 운동치료의 부하 설계가 명확해집니다.","sheet":{"kind":"basics","items":[{"h":"힘의 모멘트","t":"관절을 회전시키는 작용은 힘의 모멘트(토크)입니다. 힘의 크기와 회전축에서 힘의 작용선까지의 수직거리(모멘트 팔)의 곱으로 정해집니다."},{"h":"지레의 3종류","t":"1종 지레는 받침점, 2종은 작용점, 3종은 힘점이 가운데에 있습니다. 인체의 근육 대부분은 3종 지레로, 힘보다 속도와 가동범위에 유리합니다."},{"h":"무게중심","t":"선 자세에서 신체 무게중심은 골반 안, 제2천추의 약간 앞쪽에 있다고 봅니다. 중심선이 기저면 안에 있을수록 자세가 안정됩니다."},{"h":"운동 사슬","t":"열린사슬운동(OKC)은 원위부가 자유로운 운동, 닫힌사슬운동(CKC)은 원위부가 바닥 등에 고정된 운동입니다. 목적에 따라 구분해 씁니다."},{"h":"근수축 형태","t":"구심성 수축은 근육이 짧아지면서, 원심성 수축은 늘어나면서 장력을 냅니다. 등척성 수축은 관절 운동을 동반하지 않습니다."},{"h":"임상 적용","t":"추를 원위부에 달수록 모멘트 팔이 길어져 부하가 커집니다. 운동치료의 부하는 무게뿐 아니라 위치로도 조절할 수 있습니다."}]},"keypoints":["모멘트는 힘 × 모멘트 팔로 결정됨","인체 근육 대부분은 3종 지레(속도에 유리)","중심선이 기저면 안에 있으면 자세가 안정","하강 동작 대부분은 원심성 수축으로 조절","부하는 무게뿐 아니라 위치로도 조절 가능"],"case":{"text":"65세 여성, 무릎 골관절염. 바로 누운 자세에서 발목 부위에 모래주머니를 감고 SLR 운동을 하면 피로가 심하고 보상 동작이 나타난다.","answer":"모래주머니를 종아리 근위부로 옮기면 모멘트 팔이 짧아져, 같은 무게라도 고관절 굴곡 모멘트가 줄어듭니다. 통증과 보상을 확인하며 단계적으로 부하를 올리고, 횟수만 늘리는 대응은 피합니다."},"questions":[{"level":"기초","q":"받침점이 힘점과 작용점 사이에 있는 지레는?","options":["1종 지레","2종 지레","3종 지레","바퀴와 축"],"answer":0,"exp":"1종 지레는 받침점이 가운데에 있으며, 머리의 앞뒤 균형이 대표적인 예입니다."},{"level":"기초","q":"위팔두갈래근에 의한 팔꿈치관절 굴곡이 대표적인 예인 지레는?","options":["1종 지레","2종 지레","3종 지레","도르래"],"answer":2,"exp":"팔꿈치관절(받침점)과 손의 무게(작용점) 사이에 근육의 부착부(힘점)가 있으므로 3종 지레입니다."},{"level":"중급","q":"관절 모멘트의 크기를 결정하는 조합으로 옳은 것은?","options":["힘의 크기와 속도","근육 길이와 근단면적","힘의 크기와 모멘트 팔","질량과 온도"],"answer":2,"exp":"모멘트는 힘의 크기와 회전축에서 작용선까지의 수직거리(모멘트 팔)의 곱입니다."},{"level":"중급","q":"스쿼트 하강기에 넙다리네갈래근이 하는 주된 수축 형태는?","options":["구심성 수축","등척성 수축","등속성 수축","원심성 수축"],"answer":3,"exp":"하강기에는 무릎이 굴곡되고, 넙다리네갈래근은 늘어나면서 체중을 지지하므로 원심성 수축입니다."},{"level":"임상","q":"노인이 앞쪽의 물건을 잡으려다 휘청거렸다. 무게중심 관점에서 가장 적절한 설명은?","options":["중심선이 기저면 끝에 가까워짐","기저면이 너무 넓어짐","무게중심이 너무 낮아짐","구심성 수축이 증가함"],"answer":0,"exp":"앞으로 뻗는 동작에서 중심선이 기저면의 앞쪽 끝에 가까워져 안정성이 떨어집니다."},{"level":"임상","q":"걸터앉은 자세에서 추를 이용한 무릎 신전 운동을 한다. 무게를 바꾸지 않고 부하를 낮추는 방법은?","options":["추를 발목으로 옮긴다","추를 종아리 근위부로 옮긴다","운동 속도를 높인다","최종 범위 유지를 늘린다"],"answer":1,"exp":"추를 무릎에 가깝게 하면 모멘트 팔이 짧아져, 같은 무게라도 모멘트가 작아집니다."}],"seccion":"기초","grupo":"운동의 기초","icono":"🧭","mapa":"img/mapas/t02.jpg","fichas":[],"secuencias":[]},"3":{"id":3,"title":"관절가동범위(각도 측정)","lead":"관절가동범위 측정은 각도계로 관절이 움직이는 범위를 각도로 기록하는 평가입니다. 장애 파악, 목표 설정, 효과 판정의 기준이 됩니다.","sheet":{"kind":"basics","items":[{"h":"기본 원칙","t":"기본자세를 0°로 하고 5° 단위로 기록합니다. 원칙적으로 수동운동으로 측정하며, 능동운동으로 측정한 경우에는 그 사실을 명기합니다."},{"h":"고정축과 이동축","t":"관절마다 정해진 고정축과 이동축에 각도계의 두 팔을 맞추고, 각도계의 중심을 관절의 운동축에 맞춥니다."},{"h":"참고 가동범위","t":"학회에서 제시한 참고 가동범위를 기준으로 삼습니다. 나이와 개인차가 있으므로 반드시 반대쪽과 비교합니다."},{"h":"보상 운동","t":"체간의 젖힘이나 골반의 기울기 등 보상이 들어가면 값이 크게 나옵니다. 근위부를 확실히 고정하고 보상을 배제해 측정합니다."},{"h":"끝느낌","t":"최종 범위의 저항감(뼈성·연부조직성·결합조직성 등)과 통증 유무를 확인하여 가동범위를 제한하는 요인을 추정합니다."},{"h":"기록과 재평가","t":"측정 자세, 수동인지 능동인지, 통증이 나타나는 각도를 기록합니다. 재평가는 같은 자세·같은 방법으로 하면 비교하기 쉽습니다."}]},"keypoints":["0°는 기본자세, 기록은 5° 단위","원칙은 수동운동, 능동운동이면 명기","근위부를 고정해 보상을 배제함","참고 가동범위는 기준일 뿐, 반드시 반대쪽과 비교","끝느낌과 통증으로 제한 요인을 추정함"],"case":{"text":"40세 남성, 어깨관절 주위염. 어깨관절 굴곡 측정 중 체간이 뒤로 젖혀져 측정값이 건측과 거의 같아 보인다.","answer":"체간 신전의 보상으로 값이 과대하게 나왔을 가능성이 있습니다. 체간을 고정하고 다시 측정하며, 통증이 나타나는 각도와 끝느낌도 기록합니다. 보상이 섞인 값으로 「호전되었다」고 판단하지 않는 것이 중요합니다."},"questions":[{"level":"기초","q":"어깨관절 굴곡의 참고 가동범위로 옳은 것은?","options":["90°","120°","150°","180°"],"answer":3,"exp":"어깨관절 굴곡과 외전의 참고 가동범위는 모두 180°입니다."},{"level":"기초","q":"발목관절 배측굴곡의 참고 가동범위로 옳은 것은?","options":["10°","20°","30°","45°"],"answer":1,"exp":"발목관절 배측굴곡의 참고 가동범위는 20°입니다. 측정은 반드시 중간위(0°)에서 시작합니다."},{"level":"중급","q":"관절가동범위 측정의 원칙으로 옳은 것은?","options":["능동운동으로 측정한다","1° 단위로 기록한다","기본자세를 0°로 한다","반대쪽과의 비교는 불필요"],"answer":2,"exp":"기본자세를 0°로 하고, 원칙적으로 수동운동으로 5° 단위로 기록합니다. 반대쪽과 비교합니다."},{"level":"중급","q":"최종 범위에서 딱딱하고 갑자기 멈추는 뼈성 끝느낌이 의미하는 것은?","options":["근육 연축","뼈와 뼈의 접촉","관절낭의 신장","연부조직의 접촉"],"answer":1,"exp":"뼈성 끝느낌은 뼈와 뼈가 부딪혀 멈추는 느낌으로, 정상에서는 팔꿈치관절 신전이 대표적인 예입니다."},{"level":"임상","q":"고관절 외전 측정 중 골반이 기울어 값이 크게 나왔다. 먼저 해야 할 대응은?","options":["그대로 기록한다","골반을 고정하고 재측정한다","능동운동으로 바꿔 측정한다","측정을 중지한다"],"answer":1,"exp":"골반의 보상이 들어가면 외전 각도가 과대하게 나옵니다. 골반을 고정하고 다시 측정합니다."},{"level":"임상","q":"무릎 수술 후, 수동 굴곡의 최종 범위에서 통증이 나타났다. 기록으로 가장 적절한 것은?","options":["각도만 기록한다","건측의 값을 기록한다","통증이 사라질 때까지 기록하지 않는다","통증이 나타난 각도도 기록한다"],"answer":3,"exp":"가동범위 값과 함께 통증이 나타난 각도와 성질을 기록하면, 제한 요인의 추정과 재평가에 도움이 됩니다."}],"seccion":"기초","grupo":"운동의 기초","icono":"🧭","mapa":"img/mapas/t03.jpg","fichas":[],"secuencias":[]},"4":{"id":4,"title":"도수근력검사(0~5)","lead":"도수근력검사(MMT)는 중력과 도수 저항을 이용해 근력을 0~5의 6단계로 판정하는 평가입니다. 근력 저하의 정도와 분포를 파악할 수 있습니다.","sheet":{"kind":"basics","items":[{"h":"6단계 기준","t":"0은 수축 없음, 1은 수축만, 2는 중력 제거 시 전 범위, 3은 중력에 대항해 전 범위, 4는 중등도 저항, 5는 최대 저항에 대항하는 정상 근력입니다."},{"h":"검사 순서","t":"먼저 항중력 자세에서 등급 3이 가능한지 확인합니다. 가능하면 저항을 주어 4·5를 판정하고, 불가능하면 중력 제거 자세에서 2 이하를 판정합니다."},{"h":"저항 주는 법","t":"저항은 운동 방향과 반대로, 분절의 원위부에 줍니다. 갑자기 주지 말고 서서히 강하게 하면서 버틸 수 있는지 확인합니다."},{"h":"고정과 보상","t":"근위부를 고정하고 다른 근육에 의한 보상 운동이 나타나지 않는지 관찰합니다. 보상으로 움직인 경우 그 등급으로 판정하지 않습니다."},{"h":"등급 3의 의미","t":"등급 3은 자기 분절의 무게에 대항해 움직일 수 있는 경계로, 「중력의 벽」이라 불립니다. 동작 가능 여부를 생각하는 기준의 하나입니다."},{"h":"한계","t":"MMT는 검사자의 주관이 포함되며, 등급 4 이상의 차이는 검출하기 어렵습니다. 통증이나 근긴장 이상이 있으면 소견과 함께 기록합니다."}]},"keypoints":["먼저 항중력으로 등급 3을 확인함","등급 3이 「중력의 벽」","저항은 운동과 반대 방향으로 원위부에 줌","근위부를 고정하고 보상 운동을 놓치지 않음","중추신경계 질환에서는 MMT만으로 판정하지 않음"],"case":{"text":"70세 남성, 입원으로 인한 폐용. 걸터앉은 자세에서 무릎 신전을 전 범위로 할 수 있지만, 종아리 원위부에 가벼운 저항을 주면 버티지 못한다.","answer":"중력에 대항해 전 범위를 움직일 수 있으나 저항에는 대항하지 못하므로 등급 3으로 판정합니다. 저항을 갑자기 강하게 주거나, 체간을 뒤로 젖히는 등의 보상을 놓치지 않도록 주의합니다."},"questions":[{"level":"기초","q":"「수축은 보이거나 만져지지만 관절 운동은 없는」 등급은?","options":["등급 0","등급 1","등급 2","등급 3"],"answer":1,"exp":"등급 1은 근수축을 시진·촉진으로 확인할 수 있지만 관절 운동이 일어나지 않는 상태입니다."},{"level":"기초","q":"중력에 대항해 전 범위를 움직일 수 있으나 저항에는 대항하지 못하는 등급은?","options":["등급 4","등급 2","등급 3","등급 5"],"answer":2,"exp":"등급 3은 항중력으로 전 범위를 움직일 수 있는 등급으로, 「중력의 벽」이라 불립니다."},{"level":"중급","q":"MMT에서 일반적으로 가장 먼저 확인하는 등급은?","options":["등급 1","등급 5","등급 0","등급 3"],"answer":3,"exp":"먼저 항중력 자세에서 등급 3이 가능한지 확인하고, 그 결과로 저항을 줄지 중력 제거 자세로 옮길지 결정합니다."},{"level":"중급","q":"MMT에서 저항을 주는 위치로 적절한 것은?","options":["관절 바로 위","분절의 근위부","분절의 원위부","고정하고 있는 부위"],"answer":2,"exp":"저항은 운동 방향과 반대로, 모멘트 팔이 길어지는 분절의 원위부에 줍니다."},{"level":"임상","q":"옆으로 누운 자세에서는 고관절 외전으로 하지를 들지 못하지만, 바로 누운 자세에서는 전 범위 외전이 가능하다. 등급은?","options":["등급 1","등급 2","등급 3","등급 4"],"answer":1,"exp":"항중력 자세(옆으로 누운 자세)에서는 불가능하고, 중력을 제거한 바로 누운 자세에서 전 범위를 움직일 수 있으므로 등급 2입니다."},{"level":"임상","q":"경직이 심한 편마비 환자의 상지 근력을 평가하려 한다. 가장 적절한 접근은?","options":["MMT만으로는 판정이 어렵다","MMT 등급 5를 목표로 한다","저항을 강하게 주어 판정한다","비마비측 평가는 불필요하다"],"answer":0,"exp":"중추신경계 질환에서는 근긴장과 공동운동의 영향으로 MMT의 전제가 성립하기 어려우므로, 운동마비 평가를 함께 사용합니다."}],"seccion":"기초","grupo":"운동의 기초","icono":"🧭","mapa":"img/mapas/t04.jpg","fichas":[],"secuencias":[]},"5":{"id":5,"title":"문진","lead":"문진은 증상의 경과·성질·생활 배경을 듣고 가설을 세우는 평가의 출발점입니다. 이후 검사의 선택과 안전 확인을 좌우합니다.","sheet":{"kind":"basics","items":[{"h":"목적","t":"주호소와 경과로 병태의 가설을 세우고 검사의 우선순위를 정합니다. 동시에 의사에게 연락해야 할 위험 신호가 없는지 확인합니다."},{"h":"주호소와 현병력","t":"주호소는 본인의 말로 기록합니다. 발병 시기와 계기(외상인지 서서히인지), 이후 경과(호전·악화·변화 없음)를 묻습니다."},{"h":"통증 평가","t":"부위, 성질, 강도(NRS 등), 악화·완화 요인, 하루 중 변동, 야간통 유무를 확인합니다."},{"h":"과거력과 복약","t":"과거력, 수술력, 합병증, 복약을 확인합니다. 항응고제나 스테로이드 사용은 중재 시 주의사항이 됩니다."},{"h":"생활 배경","t":"직업, 가정에서의 역할, 주거 환경, 활동량을 묻습니다. 본인과 가족의 요구와 희망을 목표 설정에 반영합니다."},{"h":"질문 방법","t":"개방형 질문으로 시작하고 폐쇄형 질문으로 확인합니다. 전문용어를 피하고 요약해서 되물으면 정보의 어긋남을 막을 수 있습니다."}]},"keypoints":["주호소는 본인의 말 그대로 기록함","발병 계기와 경과를 반드시 물음","야간통·체중 감소 등 위험 신호를 확인함","복약(항응고제 등)은 중재 시 주의사항","개방형 질문으로 시작해 폐쇄형 질문으로 확인"],"case":{"text":"55세 남성, 2개월 전부터 요통. 「요즘은 밤에도 아파서 잠을 못 잔다. 아무것도 안 했는데 체중이 5kg 줄었다」고 말한다.","answer":"안정 시 줄지 않는 야간통과 원인 불명의 체중 감소는 레드 플래그입니다. 운동치료를 시작하기 전에 의사에게 보고·상담합니다. 문진에서 얻은 위험 신호를 이후 검사 결과로 무시하지 않는 것이 중요합니다."},"questions":[{"level":"기초","q":"문진에서 가장 먼저 청취하고 본인의 말 그대로 기록하는 것은?","options":["과거력","주호소","가족력","복약"],"answer":1,"exp":"주호소는 환자가 가장 힘들어하는 점으로, 해석을 더하지 않고 본인의 말로 기록합니다."},{"level":"기초","q":"통증의 강도를 0~10의 숫자로 답하게 하는 평가는?","options":["MMT","ROM","NRS","ADL"],"answer":2,"exp":"NRS(숫자통증척도)는 통증의 강도를 0~10으로 나타내게 하는 방법입니다."},{"level":"중급","q":"개방형 질문으로 적절한 것은?","options":["「아픈 곳이 오른쪽인가요?」","「밤에 아프신가요?」","「약은 드시고 있나요?」","「어떨 때 아프신가요?」"],"answer":3,"exp":"개방형 질문은 「예·아니요」로 답할 수 없는 질문으로, 환자에게서 많은 정보를 끌어낼 수 있습니다."},{"level":"중급","q":"중재 시 주의사항으로서 문진에서 특히 확인해야 할 정보는?","options":["항응고제 복용","주로 쓰는 손","통근 수단","취미 유무"],"answer":0,"exp":"항응고제 복용은 출혈이나 멍의 위험과 관련되어 도수적 중재 등의 주의사항이 됩니다."},{"level":"임상","q":"요통 환자가 「밤에도 아파서 못 자고 체중이 5kg 줄었다」고 말한다. 가장 적절한 대응은?","options":["운동치료를 바로 시작한다","온열치료로 경과를 본다","의사에게 보고·상담한다","다음 방문까지 지켜본다"],"answer":2,"exp":"안정 시 줄지 않는 야간통과 원인 불명의 체중 감소는 레드 플래그이므로, 치료 전에 의사와 상담합니다."},{"level":"임상","q":"골다공증이 있는 70세 여성. 넘어진 뒤부터 고관절이 아프고 걷지 못한다. 먼저 고려해야 할 것은?","options":["근력 저하로 인한 통증","골절 가능성","골관절염의 악화","심리적 요인"],"answer":1,"exp":"골다공증이 있는 사람이 넘어진 뒤의 통증과 보행 곤란은 골절을 의심하고, 의사의 평가를 우선합니다."}],"seccion":"기초","grupo":"평가","icono":"📋","mapa":"img/mapas/t05.jpg","fichas":[],"secuencias":[]},"6":{"id":6,"title":"레드 플래그","lead":"레드 플래그는 중대한 질환이 숨어 있을 가능성을 알리는 경고 신호입니다. 발견하면 물리치료를 진행하기 전에 의사와 상담합니다.","sheet":{"kind":"basics","items":[{"h":"정의","t":"악성종양, 감염, 골절, 마미증후군 등 긴급성이 높은 병태를 의심하게 하는 징후입니다. 단독보다 여러 개가 겹칠 때 비중이 커집니다."},{"h":"악성종양","t":"암의 과거력, 원인 불명의 체중 감소, 안정해도 좋아지지 않는 야간통 등을 확인합니다. 나이와 전신 상태도 함께 고려합니다."},{"h":"감염","t":"발열을 동반한 허리·등 통증, 면역억제 상태, 최근의 감염증이나 침습적 처치의 과거력에 주의합니다."},{"h":"골절","t":"강한 외상 후나, 골다공증이 있는 사람이 가볍게 넘어진 후의 통증은 골절을 의심합니다. 스테로이드 장기 사용도 확인합니다."},{"h":"마미증후군","t":"방광직장장애, 안장 부위의 감각 소실, 진행하는 하지 근력 저하는 긴급성이 높으므로 즉시 의사에게 연락합니다."},{"h":"대응","t":"소견과 경과를 기록하고 의사에게 보고·상담합니다. 환자에게 지나친 불안을 주지 않도록 진료의 필요성을 차분히 설명합니다."}]},"keypoints":["안정해도 좋아지지 않는 야간통은 주의","원인 불명의 체중 감소는 종양을 의심할 단서","방광직장장애·안장 마비는 응급","외상이나 골다공증이 있으면 골절을 의심","레드 플래그가 있으면 치료 전 의사와 상담"],"case":{"text":"45세 여성, 요통과 오른쪽 하지 통증. 오늘 아침부터 소변을 보기 어렵고 항문 주위가 저리다고 호소한다.","answer":"방광직장장애와 안장 부위의 감각 장애는 마미증후군을 의심하는 신호입니다. 평가나 운동을 계속하지 말고 즉시 의사에게 연락합니다. 「지켜보는」 대응은 피합니다."},"questions":[{"level":"기초","q":"허리·등 통증의 레드 플래그에 해당하는 것은?","options":["움직이면 아픈 요통","원인 불명의 체중 감소","오래 앉으면 심해지는 통증","운동 다음 날의 근육통"],"answer":1,"exp":"원인 불명의 체중 감소는 악성종양 등을 의심하는 레드 플래그의 하나입니다."},{"level":"기초","q":"레드 플래그를 발견했을 때의 대응으로 옳은 것은?","options":["운동 강도를 낮춰 계속한다","물리적 인자 치료로 바꾼다","다음 방문까지 지켜본다","치료 전에 의사와 상담한다"],"answer":3,"exp":"레드 플래그가 있으면 물리치료를 진행하기 전에 의사와 상담합니다."},{"level":"중급","q":"마미증후군을 의심하는 소견의 조합은?","options":["방광직장장애와 안장 부위 감각 소실","목 통증과 어깨 결림","무릎 부종과 계단에서의 통증","어깨 야간통과 거상 제한"],"answer":0,"exp":"방광직장장애와 안장 부위(회음부·항문 주위)의 감각 소실은 마미 압박을 의심하는 응급 신호입니다."},{"level":"중급","q":"골절을 가장 의심해야 할 상황은?","options":["사무 작업 후 허리 뻐근함","운동 다음 날의 근육통","골다공증 환자의 낙상 후 등 통증","추운 날의 무릎 뻣뻣함"],"answer":2,"exp":"골다공증이 있는 사람은 가벼운 외력에도 골절될 수 있으므로, 낙상 후의 통증은 골절을 의심합니다."},{"level":"임상","q":"요통 환자가 「오늘 아침부터 소변이 잘 안 나오고 항문 주위가 저리다」고 호소했다. 대응은?","options":["평가를 끝까지 계속한다","체간 운동치료를 시작한다","즉시 의사에게 연락한다","다음 주까지 경과를 본다"],"answer":2,"exp":"방광직장장애와 안장 부위의 감각 장애는 마미증후군을 의심하는 소견이므로 즉시 의사에게 연락합니다."},{"level":"임상","q":"암 과거력이 있는 68세 남성. 1개월 전부터 안정해도 줄지 않는 야간 등 통증이 있다. 판단은?","options":["자세로 인한 통증","의사와 상담해야 할 신호","근력 강화로 좋아질 통증","온열로 경과를 볼 통증"],"answer":1,"exp":"암 과거력과 안정 시 줄지 않는 야간통의 조합은 전이 등을 배제할 수 없으므로 의사와의 상담이 필요합니다."}],"seccion":"기초","grupo":"평가","icono":"📋","mapa":"img/mapas/t06.jpg","fichas":[],"secuencias":[]},"7":{"id":7,"title":"자세 평가","lead":"자세 평가는 선 자세나 앉은 자세에서 신체 정렬을 관찰해 문제의 단서를 얻는 평가입니다. 증상과의 관계는 다른 검사로 확인하는 것이 전제입니다.","sheet":{"kind":"basics","items":[{"h":"목적","t":"정렬의 치우침을 파악하고, 근육의 단축이나 근력 저하, 통증과의 관계에 대해 가설을 세웁니다."},{"h":"옆면 기준","t":"이상적인 선 자세에서는 중심선이 귓불·견봉·대전자·무릎관절 앞부분(슬개골 후면)·외측 복사뼈의 앞쪽을 지난다고 봅니다."},{"h":"뒤에서 관찰","t":"머리의 기울기, 어깨와 골반의 높이, 척추의 측방 편위, 하지의 좌우 차이를 관찰합니다. 필요하면 앞으로 숙이게 해 확인합니다."},{"h":"불량 자세의 예","t":"굽은 등(원배), 머리 전방 자세, 골반 전방경사와 요추 전만이 심한 자세, 편평등 등이 있습니다. 관련 근육의 단축이나 약화와 함께 평가합니다."},{"h":"해석 시 주의","t":"자세에 치우침이 있어도 증상이 없는 사람이 많으므로, 소견만으로 통증의 원인이라 단정하지 않습니다. 가동범위나 근력 검사로 확인합니다."},{"h":"기록","t":"관찰한 방향과 자세, 랜드마크의 위치를 기록합니다. 사진을 쓸 때는 같은 조건에서 촬영해 비교합니다."}]},"keypoints":["옆·뒤·앞의 3방향에서 관찰함","중심선은 귓불·견봉·대전자를 지남","뒤에서는 어깨와 골반 높이의 좌우 차이를 봄","전굴 시 늑골 융기는 구조적 측만을 의심","자세만으로 통증의 원인이라 단정하지 않음"],"case":{"text":"30세 여성, 사무직. 목 통증이 있으며, 옆에서 보면 귓불이 견봉보다 확연히 앞쪽에 있다.","answer":"머리 전방 자세의 소견입니다. 다만 자세만으로 원인을 단정하지 말고, 목의 가동범위, 증상을 재현하는 동작, 저림이나 근력 저하 등의 신경 증상을 확인합니다. 신경 증상이 있으면 의사와 연계합니다."},"questions":[{"level":"기초","q":"이상적인 선 자세에서 옆에서 본 중심선이 지나는 위치는?","options":["코끝","견갑골 하각","귓불","종골 후단"],"answer":2,"exp":"옆에서 본 중심선은 귓불·견봉·대전자·무릎관절 앞부분·외측 복사뼈의 앞쪽을 지나는 것이 이상적입니다."},{"level":"기초","q":"뒤에서 관찰할 때 주로 확인하는 것은?","options":["머리 전방 자세","어깨와 골반 높이의 좌우 차이","요추 전만의 정도","무릎 과신전"],"answer":1,"exp":"뒤에서는 어깨와 골반의 높이, 척추의 측방 편위 등 좌우 차이를 관찰합니다."},{"level":"중급","q":"이상적인 선 자세에서 옆에서 본 중심선에 대해 옳은 것은?","options":["외측 복사뼈 뒤쪽을 지난다","무릎관절 뒤쪽을 지난다","견갑골 내측연을 지난다","대전자를 지난다"],"answer":3,"exp":"중심선은 대전자를 지나고, 무릎관절 앞부분과 외측 복사뼈의 앞쪽을 지난다고 봅니다."},{"level":"중급","q":"자세 평가의 해석으로 적절한 것은?","options":["치우침이 있으면 통증의 원인으로 본다","다른 검사로 증상과의 관계를 확인한다","한 방향에서 관찰하면 충분하다","사진은 매번 조건을 바꿔 찍는다"],"answer":1,"exp":"자세의 치우침은 증상이 없는 사람에게도 보이므로, 가동범위나 근력 등의 검사로 관계를 확인합니다."},{"level":"임상","q":"목 통증 환자에서 귓불이 견봉보다 확연히 앞쪽에 있다. 다음에 할 일로 가장 적절한 것은?","options":["목 가동범위와 신경 증상 확인","자세 지도만 한다","바로 견인치료를 한다","경과 관찰로 한다"],"answer":0,"exp":"머리 전방 자세는 단서일 뿐입니다. 가동범위와 신경 증상을 확인하여 증상과의 관계를 평가합니다."},{"level":"임상","q":"뒤에서 보면 어깨와 골반 높이에 좌우 차이가 있고, 전굴 시 한쪽 늑골 융기가 보였다. 의심되는 것은?","options":["머리 전방 자세","굽은 등(원배)","구조적 척추측만증","편평등"],"answer":2,"exp":"전굴 시 늑골 융기는 척추뼈 회전을 동반한 구조적 척추측만증을 시사하므로, 의사의 평가로 연결합니다."}],"seccion":"기초","grupo":"평가","icono":"📋","mapa":"img/mapas/t07.jpg","fichas":[],"secuencias":[]},"8":{"id":8,"title":"보행 분석","lead":"보행 분석은 보행 주기의 각 시기에서 관절 운동과 근활동을 관찰해 문제를 찾아내는 평가입니다. 낙상 예방과 동작 개선의 방침으로 이어집니다.","sheet":{"kind":"basics","items":[{"h":"보행 주기","t":"한쪽의 초기 접지부터 같은 쪽의 다음 초기 접지까지를 1주기로 합니다. 입각기와 유각기로 나뉘며, 양하지 지지기를 2번 포함합니다."},{"h":"시기 구분","t":"입각기는 초기 접지·하중 반응기·입각 중기·입각 말기·전유각기, 유각기는 유각 초기·유각 중기·유각 말기로 나눕니다."},{"h":"관찰 방법","t":"앞·뒤·옆에서 관찰하고 한 번에 한 관절이나 한 시기에 집중합니다. 보행 속도, 보폭, 리듬, 보조기구 사용도 기록합니다."},{"h":"대표적 이상","t":"트렌델렌버그 보행(중간볼기근), 계상보행(하수족의 보상), 휘돌림 보행, 보행 동결, 종종걸음 보행 등이 있습니다."},{"h":"근활동 요점","t":"하중 반응기에는 넙다리네갈래근이 무릎 굴곡을, 앞정강근이 발의 하강을 원심성으로 조절합니다. 입각 말기에는 종아리세갈래근이 작용합니다."},{"h":"수치 평가","t":"10m 보행검사나 TUG로 속도와 이동 능력을 수치화합니다. 관찰 결과와 함께 낙상 위험도 판단합니다."}]},"keypoints":["1주기는 초기 접지부터 같은 쪽 다음 초기 접지까지","입각기는 약 60%, 유각기는 약 40%","관찰은 3방향에서, 한 번에 한 곳에 집중","트렌델렌버그 보행은 중간볼기근을 의심","계상보행은 하수족(앞정강근 약화)의 보상"],"case":{"text":"60세 남성, 비골신경마비. 유각기에 고관절과 무릎관절을 크게 굴곡해 발을 높이 들어 올리며 걷는다. 걸려 넘어질 뻔하는 일이 늘었다.","answer":"하수족을 보상하는 계상보행입니다. 발목 배측굴곡 근력, 감각, 낙상 위험을 평가합니다. 보조기 검토는 의사·의지보조기기사와 연계해 진행하며, 혼자 판단해 결정하지 않습니다."},"questions":[{"level":"기초","q":"1보행 주기 중 입각기가 차지하는 대략적인 비율은?","options":["약 40%","약 50%","약 60%","약 80%"],"answer":2,"exp":"정상 보행에서는 입각기가 약 60%, 유각기가 약 40%를 차지합니다."},{"level":"기초","q":"한 다리로 체중을 지지하며 신체 무게중심이 가장 높아지는 시기는?","options":["초기 접지","입각 중기","전유각기","유각 중기"],"answer":1,"exp":"입각 중기는 지지하는 다리 바로 위를 몸이 지나가는 시기로, 무게중심이 가장 높아집니다."},{"level":"중급","q":"하중 반응기에 무릎관절 굴곡을 원심성으로 조절하는 주된 근육은?","options":["넙다리네갈래근","햄스트링","엉덩허리근","종아리세갈래근"],"answer":0,"exp":"하중 반응기에는 무릎이 가볍게 굴곡되어 충격을 흡수하며, 넙다리네갈래근이 원심성으로 조절합니다."},{"level":"중급","q":"트렌델렌버그 보행에서 약화가 의심되는 근육은?","options":["큰볼기근","넙다리네갈래근","앞정강근","중간볼기근"],"answer":3,"exp":"중간볼기근의 근력 저하에서는 입각기에 유각측 골반이 내려가는 트렌델렌버그 징후가 나타납니다."},{"level":"임상","q":"유각기에 고관절·무릎관절을 과도하게 굴곡하고 발을 높이 들어 걷는다. 생각할 수 있는 원인은?","options":["넙다리네갈래근 근력 저하","앞정강근 근력 저하","중간볼기근 근력 저하","큰볼기근 근력 저하"],"answer":1,"exp":"앞정강근 약화로 인한 하수족으로, 발끝이 바닥에 걸리지 않도록 다리를 높이 드는 계상보행이 됩니다."},{"level":"임상","q":"파킨슨병 환자가 걷기 시작할 때나 방향을 바꿀 때 발이 바닥에 붙은 듯 나가지 않는다. 이 현상은?","options":["휘돌림 보행","계상보행","보행 동결","동요성 보행"],"answer":2,"exp":"보행 동결은 파킨슨병의 특징으로, 걷기 시작할 때나 방향 전환, 좁은 장소에서 일어나기 쉬운 현상입니다."}],"seccion":"기초","grupo":"평가","icono":"📋","mapa":"img/mapas/t08.jpg","fichas":[],"secuencias":[]},"9":{"id":9,"title":"신경학적 검사","lead":"신경학적 검사는 감각·근력·반사를 척수분절별로 조사해 장애의 부위와 레벨을 추정하는 평가입니다. 진행하는 신경 증상의 조기 발견에도 꼭 필요합니다.","sheet":{"kind":"basics","items":[{"h":"목적","t":"감각·근력·반사 소견을 조합하여 말초신경, 신경근, 척수, 뇌 중 어디에 장애가 있는지 추정합니다."},{"h":"감각 검사","t":"촉각, 통각, 온도감각, 위치감각, 진동감각을 조사하고, 피부분절(더마톰)을 따라 좌우·상하로 비교합니다."},{"h":"분절 대표 근육","t":"C5는 어깨 외전, C6는 손목 배측굴곡, C7은 팔꿈치 신전, L4는 발목 배측굴곡, L5는 엄지발가락 신전, S1은 발목 저측굴곡이 대표적입니다."},{"h":"심부건반사","t":"이두근 건반사(C5), 상완요골근 반사(C6), 삼두근 건반사(C7), 슬개건 반사(L4), 아킬레스건 반사(S1)가 기본입니다."},{"h":"상위와 하위","t":"상위운동신경원 장애에서는 건반사 항진과 병적 반사, 하위운동신경원 장애에서는 건반사 저하·소실과 근위축이 나타납니다."},{"h":"주의사항","t":"갑자기 진행하는 근력 저하, 넓어지는 감각 장애, 방광직장장애는 신속히 의사에게 연락합니다. 소견은 시간 경과에 따라 기록합니다."}]},"keypoints":["감각·근력·반사는 반드시 좌우를 비교함","슬개건 반사는 L4, 아킬레스건 반사는 S1","L5는 엄지발가락 신전 근력과 감각으로 판단","반사 항진·병적 반사는 상위운동신경원","진행하는 근력 저하는 즉시 의사에게 연락"],"case":{"text":"50세 남성, 요통과 오른쪽 종아리 바깥쪽에서 발등까지의 저림. 오른쪽 엄지발가락 신전 근력이 저하되었고, 슬개건 반사와 아킬레스건 반사에 좌우 차이는 없다.","answer":"L5 신경근 장애가 의심됩니다. L5에는 대표적인 건반사가 없으므로 감각과 엄지발가락 신전 근력으로 판단합니다. 근력 저하가 진행하거나 방광직장장애가 나타나면 즉시 의사에게 연락합니다."},"questions":[{"level":"기초","q":"상위운동신경원 장애를 시사하는 병적 반사는?","options":["슬개건 반사","복벽 반사","바빈스키 반사","각막 반사"],"answer":2,"exp":"바빈스키 반사는 발바닥을 긁으면 엄지발가락이 배측굴곡하는 병적 반사로, 상위운동신경원 장애를 시사합니다."},{"level":"기초","q":"피부분절을 따라 좌우를 비교하는 검사는?","options":["건반사","감각 검사","MMT","ROM 측정"],"answer":1,"exp":"피부분절은 각 척수분절이 지배하는 피부 영역으로, 감각 검사로 좌우·상하를 비교합니다."},{"level":"중급","q":"아킬레스건 반사가 주로 반영하는 척수분절은?","options":["L3","L4","L5","S1"],"answer":3,"exp":"아킬레스건 반사는 주로 S1, 슬개건 반사는 주로 L4를 반영합니다."},{"level":"중급","q":"하위운동신경원 장애의 소견으로 옳은 것은?","options":["건반사 항진","병적 반사 양성","근위축","경직"],"answer":2,"exp":"하위운동신경원 장애에서는 건반사 저하·소실, 근위축, 근긴장 저하가 나타납니다."},{"level":"임상","q":"종아리 바깥쪽에서 발등까지 저림과 엄지발가락 신전 근력 저하가 있고, 건반사에 좌우 차이는 없다. 장애 레벨은?","options":["L3","L4","L5","S1"],"answer":2,"exp":"종아리 바깥쪽~발등의 감각과 엄지발가락 신전은 L5의 소견입니다. L5에는 대표적인 건반사가 없습니다."},{"level":"임상","q":"목 통증과 양손 저림에 더해 하지 건반사 항진과 바빈스키 반사 양성이 보였다. 의심되는 것은?","options":["경수 장애(척수병증)","단일 신경근 장애","손목굴증후군","근막성 통증"],"answer":0,"exp":"하지의 반사 항진과 병적 반사는 상위운동신경원 장애로, 경수 압박 등을 의심하여 의사에게 의뢰합니다."}],"seccion":"기초","grupo":"평가","icono":"📋","mapa":"img/mapas/t09.jpg","fichas":[],"secuencias":[]},"10":{"id":10,"title":"회전근개","lead":"회전근개는 어깨관절을 안정시키는 4개 근육의 힘줄입니다. 어떤 근육이 손상되었는지 검사로 구별하는 것이 평가와 운동치료의 출발점입니다.","sheet":{"kind":"tests","tests":[{"name":"조브 검사","alias":"빈 깡통 검사","steps":"견갑골면에서 어깨를 90° 외전하고 엄지가 아래를 향한 내회전 자세로 유지시킨 뒤, 검사자가 위에서 아래로 저항을 가함.","positive":"통증, 또는 저항을 이기지 못하는 근력 저하","tissue":"가시위근(극상근)","point":"통증과 근력 저하를 나누어 기록함. 충돌증후군에서도 통증이 나타날 수 있음에 주의."},{"name":"외회전 저항 검사","alias":"","steps":"팔꿈치 90° 굴곡, 팔을 몸통 옆에 내린 자세에서 외회전하려는 아래팔에 검사자가 안쪽으로 저항을 가함.","positive":"외회전 시 통증, 또는 건측보다 뚜렷한 근력 저하","tissue":"가시아래근(극하근)·작은원근(소원근)","point":"수동으로 외회전 위치에 두어도 유지하지 못하면(외회전 지연 징후) 큰 파열을 의심함."},{"name":"리프트오프 검사","alias":"거버 리프트오프 검사","steps":"손등을 허리에 댄 자세에서 손을 등에서 뒤쪽으로 떼도록 지시함.","positive":"손을 등에서 떼지 못함, 또는 통증이 나타남","tissue":"어깨밑근(견갑하근)","point":"내회전 가동범위가 부족해 손이 등 뒤로 가지 않으면 벨리 프레스 검사로 대신함."},{"name":"팔 떨어뜨리기 검사","alias":"","steps":"검사자가 어깨를 수동으로 약 90° 외전 위치까지 올린 뒤, 환자에게 천천히 팔을 내리게 함.","positive":"도중에 유지하지 못하고 팔이 떨어짐, 또는 심한 통증","tissue":"회전근개(주로 극상근)의 파열","point":"큰 파열을 시사하는 소견. 단독으로 단정하지 말고 다른 검사와 영상 소견을 함께 봄."}]},"keypoints":["통증과 근력 저하를 나누어 기록하고 반드시 건측과 비교","조브 검사는 견갑골면·엄지 아래 자세로 극상근을 평가","외회전 저항은 극하근·소원근, 리프트오프는 견갑하근","검사 하나로 단정하지 말고 여러 소견을 조합함","외상 후 갑자기 팔을 못 올리면 의사에게 의뢰"],"case":{"text":"58세 남성. 넘어지며 오른손을 짚은 뒤부터 오른쪽 어깨를 올리지 못함. 수동 가동범위는 거의 유지되나 능동 거상은 어려움. 조브 검사에서 근력 저하, 팔 떨어뜨리기 검사 양성.","answer":"수동 가동범위는 유지되고 능동 운동만 어려우므로 구축보다 회전근개 파열을 의심함. 검사만으로 단정하지 말고 의사 진찰·영상검사로 의뢰함. 통증을 유발하는 강한 저항 운동의 반복은 피함."},"questions":[{"level":"기초","q":"조브 검사(견갑골면 90°, 엄지를 아래로)로 주로 평가하는 근육은?","options":["가시위근(극상근)","가시아래근(극하근)","어깨밑근(견갑하근)","작은원근(소원근)"],"answer":0,"exp":"견갑골면에서 90° 외전하고 엄지를 아래로 향한 자세로 저항을 가해 극상근을 평가함."},{"level":"기초","q":"손등을 허리에 대고 떼는 거버 리프트오프 검사로 평가하는 근육은?","options":["큰원근(대원근)","가시위근(극상근)","어깨밑근(견갑하근)","어깨세모근(삼각근)"],"answer":2,"exp":"손을 등에서 떼는 동작은 어깨 내회전이며, 주된 내회전근인 견갑하근을 평가함."},{"level":"중급","q":"팔꿈치 90° 굴곡, 팔을 내린 자세에서 저항에 대항해 외회전하는 검사로 평가하는 것은?","options":["극상근만","극하근·소원근","견갑하근","위팔두갈래근 장두"],"answer":1,"exp":"저항에 대항한 외회전은 외회전근인 극하근과 소원근의 통증·근력 저하를 평가함."},{"level":"중급","q":"팔 떨어뜨리기 검사 양성이 시사하는 것으로 가장 적절한 것은?","options":["어깨관절 전방 불안정성","위팔두갈래근 장두건염","견봉쇄골관절 장애","회전근개 파열"],"answer":3,"exp":"올린 팔을 천천히 내리지 못하고 떨어지는 것은 회전근개(주로 극상근) 파열을 시사함."},{"level":"임상","q":"62세 여성. 손을 등 뒤로 돌릴 수는 있으나 등에서 뒤로 떼지 못함. 외회전 저항은 정상. 가장 의심되는 손상 부위는?","options":["가시위근(극상근)","어깨밑근(견갑하근)","가시아래근(극하근)","작은원근(소원근)"],"answer":1,"exp":"리프트오프 검사 양성이고 외회전은 정상이므로 내회전근인 견갑하근 장애를 가장 의심함."},{"level":"임상","q":"65세 남성, 어깨 거상 곤란. 수동 가동범위는 유지되고 조브 검사에서 뚜렷한 근력 저하. 가장 적절한 대응은?","options":["최대 저항 근력강화 시작","의사에게 정보 제공·평가 의뢰","강한 스트레칭 반복","경과를 지켜보라고 안내"],"answer":1,"exp":"회전근개 파열이 의심되며 진단과 방침 결정에는 의사의 평가·영상검사가 필요함. 강한 부하는 피함."}],"seccion":"부위별 특수검사","grupo":"어깨관절","icono":"💪","mapa":"img/mapas/t10.jpg","fichas":[{"nombre":"조브 검사","img":"img/fichas/jobe.jpg"}],"secuencias":[{"nombre":"조브 검사","rotulo":"평가","texto":"가시위근","frames":["img/mov/teste-jobe-1.jpg","img/mov/teste-jobe-2.jpg","img/mov/teste-jobe-3.jpg"]}]},"11":{"id":11,"title":"충돌증후군·불안정성","lead":"거상 시 통증은 견봉하 충돌을, 외회전 시 불안감은 전방 불안정성을 나타냅니다. 통증과 불안감을 구별하여 평가하는 것이 중요합니다.","sheet":{"kind":"tests","tests":[{"name":"니어 검사","alias":"니어 충돌 징후","steps":"견갑골을 위에서 눌러 고정하고, 어깨 내회전 상태 그대로 팔을 수동으로 앞쪽 최대 거상함.","positive":"거상 시 어깨 앞위쪽 통증","tissue":"견봉하 회전근개·점액낭","point":"대결절이 견봉 아래로 밀려 들어가 통증이 생김. 양성이라도 파열 유무는 판별 불가."},{"name":"호킨스-케네디 검사","alias":"호킨스 검사","steps":"어깨·팔꿈치를 90° 굴곡하고, 검사자가 아래팔을 아래로 눌러 어깨를 수동 내회전시킴.","positive":"내회전 시 어깨 앞위쪽~바깥쪽 통증","tissue":"극상근건·견봉하 점액낭","point":"니어 검사와 함께 판단함. 통증 부위와 재현성을 확인함."},{"name":"불안 검사","alias":"전방 불안감 검사","steps":"바로 누운 자세에서 어깨 90° 외전·팔꿈치 90° 굴곡 후, 검사자가 천천히 어깨를 외회전함.","positive":"탈구될 것 같은 불안감, 방어적 근수축","tissue":"어깨관절 전방 관절낭·관절순","point":"양성은 통증이 아닌 불안감으로 판단함. 탈구 병력이 있으면 천천히 부드럽게 시행."},{"name":"재배치 검사","alias":"","steps":"불안 검사 자세에서 상완골두를 앞에서 뒤로 누르면서 외회전함.","positive":"불안감이 줄고 더 외회전할 수 있음","tissue":"어깨관절 전방 불안정성","point":"불안 검사에 이어 시행하며, 불안감의 변화로 전방 불안정성을 뒷받침함."}]},"keypoints":["니어와 호킨스는 견봉하 충돌에 의한 통증을 봄","불안정성 검사는 통증보다 불안감의 출현을 중시함","양성이라도 회전근개 파열 유무와 정도는 판별 불가","탈구 병력이 있으면 외회전을 천천히 가함","문진·다른 검사·영상 소견과 통합하여 판단함"],"case":{"text":"19세 남성, 럭비 선수. 태클로 팔이 외전·외회전 자세로 강제된 뒤로 같은 자세에서 \"빠질 것 같다\"고 호소함. 불안 검사에서 불안감이 있고 재배치 검사에서 감소함.","answer":"어깨관절 전방 불안정성을 의심하는 소견으로, 충돌증후군의 통증과 구별함. 외전·외회전을 강제하는 동작은 피하고, 의사의 평가를 전제로 회전근개·견갑골 주위근 안정화부터 진행함."},"questions":[{"level":"기초","q":"견봉하 충돌증후군에서 끼이기 쉬운 구조는?","options":["위팔세갈래근건","큰원근(대원근)","극상근건","넓은등근(광배근)"],"answer":2,"exp":"거상 시 견봉 아래에서 극상근건과 견봉하 점액낭이 끼여 통증이 생김."},{"level":"기초","q":"호킨스-케네디 검사에서 어깨에 가하는 운동은?","options":["90° 굴곡 자세에서 내회전","팔을 내린 자세에서 외회전","수평 외전","신전"],"answer":0,"exp":"어깨·팔꿈치 90° 굴곡 자세에서 어깨를 수동 내회전해 대결절을 오훼견봉궁 아래로 밀어 넣음."},{"level":"중급","q":"불안 검사의 양성 소견은?","options":["거상 시 어깨 앞위쪽 통증","탈구될 것 같은 불안감","팔꿈치 굴곡 시 통증","팔이 떨어짐"],"answer":1,"exp":"외전·외회전 자세에서 탈구될 것 같은 불안감이나 방어적 근수축이 나타나면 양성이며 전방 불안정성을 뜻함."},{"level":"중급","q":"재배치 검사에서 불안감이 감소한 경우 시사하는 것은?","options":["회전근개 파열","견봉쇄골관절 장애","동결견","어깨관절 전방 불안정성"],"answer":3,"exp":"골두를 뒤로 누르면 불안감이 줄어드는 것은 전방 불안정성을 뒷받침하는 소견임."},{"level":"임상","q":"45세 남성, 머리 위 작업 시 어깨 앞위쪽 통증. 니어와 호킨스에서 통증이 있고 근력은 유지됨. 가장 생각할 수 있는 것은?","options":["전방 불안정성","견봉하 충돌증후군","경추 신경근병증","견봉쇄골관절 탈구"],"answer":1,"exp":"거상·내회전 시 어깨 앞위쪽 통증과 유지된 근력으로 보아 견봉하 충돌증후군이 가장 유력함."},{"level":"임상","q":"20세 여성, 어깨 전방 탈구 2회 경험. 불안 검사를 시행할 때 가장 적절한 것은?","options":["빠르게 최대 외회전까지 강제","불안감이 나타난 시점에 중단","통증이 날 때까지 외회전 지속","반동을 주어 시행"],"answer":1,"exp":"목적은 불안감 확인이므로 나타난 시점에 중단함. 강제하면 재탈구 위험이 있음."}],"seccion":"부위별 특수검사","grupo":"어깨관절","icono":"💪","mapa":"img/mapas/t11.jpg","fichas":[{"nombre":"니어 검사","img":"img/fichas/neer.jpg"},{"nombre":"호킨스-케네디 검사","img":"img/fichas/hawkins.jpg"}],"secuencias":[]},"12":{"id":12,"title":"위팔두갈래근·관절순","lead":"위팔두갈래근 장두건은 결절간구를 지나 상부 관절순에 붙습니다. 투구나 견인으로 다치기 쉬우며, 힘줄과 관절순을 구별하여 평가합니다.","sheet":{"kind":"tests","tests":[{"name":"스피드 검사","alias":"","steps":"팔꿈치 신전·아래팔 회외 자세로 어깨를 앞으로 거상시키고, 검사자가 아래팔에 아래 방향 저항을 가함.","positive":"결절간구 부위의 통증","tissue":"위팔두갈래근 장두건","point":"상부 관절순 손상에서도 통증이 날 수 있음. 압통 부위와 함께 판단함."},{"name":"여가슨 검사","alias":"","steps":"팔꿈치 90° 굴곡·아래팔 회내 자세에서 검사자의 저항에 대항해 아래팔을 회외시킴.","positive":"결절간구 부위의 통증, 또는 힘줄이 빠지는 느낌","tissue":"위팔두갈래근 장두건·횡상완인대","point":"힘줄 아탈구에서는 딸깍거림을 동반할 수 있음. 통증 부위를 반드시 확인함."},{"name":"오브라이언 검사","alias":"능동 압박 검사","steps":"어깨 90° 굴곡·약간 수평 내전·엄지 아래로 하여 아래로 저항하고, 이어서 손바닥을 위로 하여 반복함.","positive":"엄지 아래에서 깊은 통증·딸깍거림, 손바닥 위에서 감소","tissue":"상부 관절순·견봉쇄골관절","point":"어깨 위쪽 통증은 견봉쇄골관절, 어깨 깊은 곳 통증은 관절순을 시사함. 부위를 구별함."},{"name":"크랭크 검사","alias":"","steps":"어깨를 크게 거상한 자세에서 상완골 장축 방향으로 압력을 가하며 내회전·외회전함.","positive":"통증이나 딸깍거림(걸리는 느낌)의 재현","tissue":"관절순","point":"관절순 손상은 검사 단독으로 확정하기 어려우므로 영상 소견과 함께 판단함."}]},"keypoints":["장두건은 결절간구를 지나 관절상결절과 상부 관절순에 부착","스피드와 여가슨은 결절간구 부위의 통증을 확인함","오브라이언은 통증 부위로 관절순과 견봉쇄골관절을 구별","딸깍거림이나 걸리는 느낌의 유무도 기록함","관절순 손상은 검사만으로 확정하지 않고 영상과 통합"],"case":{"text":"22세 남성, 야구 투수. 투구 시 어깨 깊은 곳의 통증과 걸리는 느낌. 오브라이언 검사에서 엄지 아래일 때 깊은 통증이 있고 손바닥 위에서 감소함. 스피드 검사에서도 통증이 있음.","answer":"상부 관절순(SLAP) 손상을 의심함. 어깨 위쪽 통증이면 견봉쇄골관절 유래를 생각함. 투구 지속 여부는 독단하지 말고 의사에게 의뢰하며, 통증을 유발하는 투구 동작은 삼가도록 안내함."},"questions":[{"level":"기초","q":"위팔두갈래근 장두건이 지나가는 고랑은?","options":["관절와","결절간구","요골신경구","견봉"],"answer":1,"exp":"장두건은 상완골 대결절과 소결절 사이의 결절간구를 지나 관절 안으로 들어감."},{"level":"기초","q":"위팔두갈래근 장두건이 관절상결절과 함께 부착하는 구조는?","options":["상부 관절순","하관절상완인대","견봉쇄골인대","오훼쇄골인대"],"answer":0,"exp":"장두건은 관절상결절과 상부 관절순에 붙으므로 힘줄 장애와 관절순 손상이 동반되기 쉬움."},{"level":"중급","q":"여가슨 검사에서 저항을 가하는 운동은?","options":["어깨 외전","손목 신전","아래팔 회외","팔꿈치 신전"],"answer":2,"exp":"팔꿈치 90° 굴곡 자세에서 아래팔 회외에 저항을 가하고, 결절간구 부위 통증으로 장두건 장애를 봄."},{"level":"중급","q":"오브라이언 검사에서 어깨 위쪽 통증이 나타난 경우 의심하는 것은?","options":["상부 관절순 손상","견봉쇄골관절 장애","회전근개 파열","전방 불안정성"],"answer":1,"exp":"어깨 위쪽 통증은 견봉쇄골관절, 어깨 깊은 곳 통증은 상부 관절순 손상을 시사함."},{"level":"임상","q":"25세 남성, 배구 선수. 스파이크 시 어깨 깊은 곳 통증과 딸깍거림. 오브라이언 검사에서 깊은 통증. 가장 의심되는 것은?","options":["견봉쇄골관절 장애","동결견","경추증","SLAP 손상"],"answer":3,"exp":"머리 위 동작 시 깊은 통증·딸깍거림과 오브라이언 양성(깊은 통증)으로 SLAP 손상을 의심함."},{"level":"임상","q":"40세 남성. 무거운 물건을 들 때 위팔 앞쪽에서 끊어지는 소리가 나고 알통이 아래로 이동함. 가장 적절한 대응은?","options":["최대 저항 근력강화 시행","여가슨 검사 반복","의사 진찰로 의뢰","온열 후 경과 관찰"],"answer":2,"exp":"장두건 파열이 의심되는 소견으로 먼저 의사 진찰이 필요함. 부하를 주는 평가·운동은 피함."}],"seccion":"부위별 특수검사","grupo":"어깨관절","icono":"💪","mapa":"img/mapas/t12.jpg","fichas":[],"secuencias":[]},"13":{"id":13,"title":"팔꿈치관절","lead":"팔꿈치 통증은 바깥쪽 신전근군, 안쪽 굴곡근군과 인대, 그리고 척골신경으로 나누어 생각합니다. 아픈 부위와 검사를 연결하여 평가합니다.","sheet":{"kind":"tests","tests":[{"name":"톰센 검사","alias":"","steps":"팔꿈치 신전·손목 약간 신전 자세로 주먹을 쥐게 하고, 검사자가 손등을 굴곡 방향으로 눌러 저항을 가함.","positive":"상완골 외측상과 주위의 통증","tissue":"단요측수근신근의 기시부","point":"상완골 외측상과염의 평가. 중지 신전 검사나 의자 검사와 조합함."},{"name":"중지 신전 검사","alias":"","steps":"팔꿈치 신전 자세로 가운뎃손가락을 신전시키고, 검사자가 가운뎃손가락 기절골을 손바닥 쪽으로 눌러 저항을 가함.","positive":"상완골 외측상과 주위의 통증","tissue":"단요측수근신근·총지신근의 기시부","point":"톰센 검사와 마찬가지로 외측상과염에서 양성이 됨. 통증이 재현되는 부위를 확인함."},{"name":"외반 스트레스 검사","alias":"","steps":"팔꿈치를 약간 굴곡하고 위팔을 고정한 뒤 아래팔에 외반 방향 스트레스를 가함.","positive":"팔꿈치 안쪽 통증, 또는 건측보다 큰 동요성","tissue":"내측 측부인대","point":"투구 장애 팔꿈치 평가에 사용함. 반드시 건측과 비교하고 통증과 동요성을 나누어 기록함."},{"name":"티넬 징후(주관)","alias":"","steps":"내측상과와 주두 사이의 주관을 손끝이나 반사망치로 가볍게 두드림.","positive":"새끼손가락·넷째손가락 척측으로 퍼지는 저림","tissue":"척골신경(주관)","point":"주관증후군의 평가. 팔꿈치 굴곡 검사나 프로망 징후와 함께 판단함."}]},"keypoints":["외측상과 통증은 손목·손가락 신전근 기시부를 의심","외반 스트레스는 약간 굴곡 자세에서 시행, 건측과 비교","척골신경 증상은 새끼·넷째손가락 척측 저림으로 확인","통증과 동요성(불안정성)을 나누어 기록함","저림 지속이나 손 내재근 위축은 의사 의뢰 신호"],"case":{"text":"45세 여성, 사무직. 수건을 짜거나 가방을 들어 올리면 팔꿈치 바깥쪽이 아픔. 외측상과에 압통이 있고 톰센 검사와 중지 신전 검사에서 통증이 재현됨.","answer":"상완골 외측상과염을 의심하는 소견. 통증을 유발하는 쥐기 동작의 반복을 줄이고 부하를 조절함. 저림, 부종, 야간의 심한 통증을 동반하면 다른 질환도 고려해 의사에게 의뢰함."},"questions":[{"level":"기초","q":"상완골 외측상과에서 기시하는 근육군은?","options":["손목 굴곡근군","손목 신전근군","위팔두갈래근","원회내근"],"answer":1,"exp":"외측상과에는 손목·손가락 신전근군이, 내측상과에는 굴곡근군과 원회내근이 기시함."},{"level":"기초","q":"주관(팔꿉굴)을 지나가는 신경은?","options":["정중신경","요골신경","척골신경","근피신경"],"answer":2,"exp":"척골신경은 내측상과 뒤쪽의 주관을 지나므로 팔꿈치 안쪽을 두드리면 새끼손가락 쪽이 저림."},{"level":"중급","q":"톰센 검사에서 저항을 가하는 운동은?","options":["손목 신전","손목 굴곡","아래팔 회내","팔꿈치 굴곡"],"answer":0,"exp":"손목 신전에 저항을 가해 신전근군 기시부인 외측상과 주위 통증의 재현을 봄."},{"level":"중급","q":"외반 스트레스 검사로 주로 평가하는 조직은?","options":["외측 측부인대","윤상인대","요골두","내측 측부인대"],"answer":3,"exp":"아래팔에 외반 스트레스를 가하면 팔꿈치 안쪽이 늘어나 내측 측부인대의 통증·동요성을 봄."},{"level":"임상","q":"14세 남자, 야구 투수. 투구 시 팔꿈치 안쪽 통증. 외반 스트레스에서 안쪽 통증이 나타남. 가장 의심되는 것은?","options":["상완골 외측상과염","내측형 야구 팔꿈치","요골두 아탈구","요골두 골절"],"answer":1,"exp":"투구 동작 반복과 외반 스트레스 시 안쪽 통증으로 내측형 야구 팔꿈치(안쪽 인대·골단 장애)를 의심함."},{"level":"임상","q":"50세 남성. 팔꿈치 안쪽을 두드리면 새끼손가락이 저리고 손가락의 섬세한 동작도 어려움. 가장 적절한 대응은?","options":["팔꿈치를 오래 굴곡 유지","저림은 경과 관찰","의사에게 정보 제공","팔꿈치 안쪽을 강하게 주무름"],"answer":2,"exp":"교치성 저하를 동반한 척골신경 장애는 의사의 평가가 필요함. 팔꿈치 지속 굴곡이나 압박은 증상을 악화시킴."}],"seccion":"부위별 특수검사","grupo":"팔꿉·손목관절·손","icono":"✋","mapa":"img/mapas/t13.jpg","fichas":[],"secuencias":[]},"14":{"id":14,"title":"손목관절·손","lead":"손의 저림이나 통증은 어떤 신경·힘줄이 관여하는지 분포로 추정합니다. 수근관증후군과 건초염은 임상에서도 국시에서도 자주 나옵니다.","sheet":{"kind":"tests","tests":[{"name":"팔렌 검사","alias":"팔렌 징후","steps":"양손 손등을 맞대고 손목을 최대 굴곡 자세로 일정 시간 유지하며 저림의 출현을 관찰함.","positive":"엄지~넷째손가락 요측의 저림 출현·악화","tissue":"정중신경(수근관)","point":"수근관증후군의 평가. 저림 범위가 정중신경 영역과 일치하는지 확인함."},{"name":"티넬 징후(손목관절)","alias":"티넬 사인","steps":"손목 손바닥 쪽의 수근관 부위를 손끝이나 반사망치로 가볍게 두드림.","positive":"정중신경 영역의 손끝으로 퍼지는 저림","tissue":"정중신경(수근관)","point":"신경 압박 부위나 재생 추정에도 사용함. 너무 세게 두드리지 않음."},{"name":"핀켈스타인 검사","alias":"","steps":"엄지를 다른 손가락으로 감싸 쥐게 하고(또는 검사자가 엄지를 잡고) 손목을 수동으로 척측 편위시킴.","positive":"요골 경상돌기 부위의 심한 통증","tissue":"장무지외전근·단무지신근건","point":"드퀘르뱅병의 평가. 감싸 쥐는 방법은 아이히호프 검사라고도 함. 건측과 비교함."},{"name":"프로망 징후","alias":"","steps":"양손 엄지와 검지로 종이를 집게 하고, 검사자가 종이를 빼내듯 잡아당김.","positive":"엄지 IP관절이 굴곡되며 종이를 붙잡으려 함","tissue":"척골신경(무지내전근)","point":"무지내전근 근력 저하를 정중신경 지배의 장무지굴근으로 대상하는 현상을 봄."}]},"keypoints":["저림 분포로 정중·척골·요골신경을 구별함","팔렌과 티넬은 수근관에서의 정중신경을 봄","핀켈스타인은 엄지 건초염 평가에 사용함","양측에서 시행하고 건측과 비교하여 판단함","무지구근 위축이나 지속되는 저림은 의사에게 의뢰"],"case":{"text":"52세 여성. 새벽에 엄지~가운뎃손가락이 저리고 손을 털면 편해짐. 팔렌 검사에서 같은 부위에 저림이 나타나고 수근관 부위 티넬 징후도 양성.","answer":"수근관증후군을 의심함. 저림이 새끼손가락까지 미치거나 목 움직임으로 변하면 다른 부위도 고려함. 무지구 위축이나 근력 저하가 있으면 의사에게 의뢰하고, 손목의 강한 압박은 피함."},"questions":[{"level":"기초","q":"수근관을 지나가는 신경은?","options":["척골신경","정중신경","요골신경","근피신경"],"answer":1,"exp":"수근관은 굴곡근건과 정중신경이 지나는 터널이며, 여기서의 압박이 수근관증후군임."},{"level":"기초","q":"핀켈스타인 검사에서 통증이 나타나는 부위는?","options":["요골 경상돌기 부위","척골 경상돌기 부위","두상골 부위","제5중수골두"],"answer":0,"exp":"엄지의 힘줄(장무지외전근·단무지신근)이 지나는 요골 경상돌기 부위에 통증이 나타남."},{"level":"중급","q":"프로망 징후로 평가하는 신경은?","options":["정중신경","요골신경","액와신경","척골신경"],"answer":3,"exp":"척골신경 지배인 무지내전근이 약하면 장무지굴근으로 대상하여 엄지 IP관절이 굴곡됨."},{"level":"중급","q":"팔렌 검사의 양성 소견은?","options":["새끼손가락 저림","손등 전체 통증","엄지~넷째손가락 요측 저림","손목의 불안정감"],"answer":2,"exp":"손목 굴곡 유지로 수근관 내압이 높아져 정중신경 영역(엄지~넷째손가락 요측)에 저림이 나타남."},{"level":"임상","q":"30세 여성. 출산 후 육아로 엄지를 쓰면 손목 엄지 쪽이 아픔. 엄지를 감싸 쥐고 척측 편위하면 통증. 가장 의심되는 것은?","options":["수근관증후군","삼각섬유연골복합체 손상","드퀘르뱅병","방아쇠 손가락"],"answer":2,"exp":"엄지 과사용과 감싸 쥔 척측 편위 시 요골 경상돌기 부위 통증으로 드퀘르뱅병을 의심함."},{"level":"임상","q":"60세 남성. 새끼손가락과 넷째손가락 척측이 저리고 종이를 집으면 엄지 IP관절이 굴곡됨. 장애가 의심되는 신경은?","options":["정중신경","요골신경","후골간신경","척골신경"],"answer":3,"exp":"새끼·넷째손가락 척측 저림과 프로망 징후 양성은 척골신경 장애를 나타내는 소견임."}],"seccion":"부위별 특수검사","grupo":"팔꿉·손목관절·손","icono":"✋","mapa":"img/mapas/t14.jpg","fichas":[{"nombre":"팔렌 검사","img":"img/fichas/phalen.jpg"},{"nombre":"핀켈스타인 검사","img":"img/fichas/finkelstein.jpg"},{"nombre":"티넬 징후(손목관절)","img":"img/fichas/tinel-punho.jpg"}],"secuencias":[]},"15":{"id":15,"title":"경추","lead":"목에서 팔로 가는 통증·저림은 신경근 압박으로 생길 수 있습니다. 유발 검사와 완화 검사를 모두 시행해 신경근 증상인지 확인합니다.","sheet":{"kind":"tests","tests":[{"name":"스펄링 검사","alias":"추간공 압박 검사","steps":"앉은 자세에서 목을 환측으로 측굴(약간 신전·회전)시키고, 검사자가 정수리에서 아래로 압박을 가함.","positive":"환측 팔로 뻗치는 통증·저림의 재현","tissue":"경추 신경근(추간공 부위)","point":"목 통증만 재현되면 양성으로 보지 않음. 심한 통증이나 어지럼이 생기면 즉시 중단함."},{"name":"잭슨 검사","alias":"잭슨 압박 검사","steps":"앉은 자세에서 목을 약간 신전 자세로 하고, 검사자가 정수리에서 아래로 압박을 가함.","positive":"팔로 뻗치는 통증·저림의 재현","tissue":"경추 신경근","point":"신전 시 추간공이 좁아지는 것을 이용함. 스펄링 검사와 조합함."},{"name":"경추 견인 검사","alias":"신연 검사","steps":"앉은 자세에서 검사자가 아래턱과 뒤통수를 받치고 머리를 위쪽으로 천천히 견인함.","positive":"팔의 방사통·저림이 완화됨","tissue":"경추 신경근(추간공에서의 압박)","point":"완화되면 양성. 견인으로 증상이 악화되면 다른 요인도 생각하고 중단함."},{"name":"어깨 외전 검사","alias":"바코디 징후","steps":"앉은 자세에서 환측 손을 머리 위에 올리는 자세를 취하게 하고 팔 증상의 변화를 봄.","positive":"팔의 방사통·저림이 완화됨","tissue":"경추 신경근","point":"신경근 긴장이 풀려 증상이 누그러짐. 환자가 자연스럽게 이 자세를 취하고 있기도 함."}]},"keypoints":["팔로 뻗치는 통증·저림이 재현되면 신경근 증상으로 판단","압박 검사는 부드럽게 시행, 강한 증상이 나오면 중단","견인이나 어깨 외전으로 증상이 완화되는지도 확인","피부분절·근력·건반사와 함께 장애 높이를 추정","양손 저림이나 보행 장애는 척수병증 의심, 의사에게"],"case":{"text":"48세 남성, 사무직. 목 통증과 오른쪽 엄지~아래팔 바깥쪽 저림. 스펄링 검사에서 오른팔에 저림이 재현되고 머리 견인으로 완화됨.","answer":"경추 신경근병증을 의심하며, 저림 분포로 보아 C6 영역을 생각할 수 있음. 건반사·근력도 확인함. 양손 교치성 저하나 보행 장애가 있으면 척수병증을 의심해 의사에게 의뢰함. 강한 압박의 반복은 피함."},"questions":[{"level":"기초","q":"스펄링 검사에서 머리를 압박할 때 목의 자세는?","options":["환측으로 측굴","건측으로 측굴","최대 굴곡","중립 자세에서 견인"],"answer":0,"exp":"환측으로 측굴(약간 신전)시켜 추간공을 좁히고 머리를 압박하여 신경근 증상을 유발함."},{"level":"기초","q":"목의 신전·환측 측굴 시 좁아져 신경근이 압박되기 쉬운 부위는?","options":["추체 앞모서리","추간공","극돌기 사이","횡돌기 끝"],"answer":1,"exp":"신경근은 추간공을 지나 나오므로 신전·측굴로 추간공이 좁아지면 압박되기 쉬움."},{"level":"중급","q":"경추 견인 검사의 양성 소견은?","options":["팔 증상의 악화","어지럼 출현","팔 증상의 완화","목 가동범위 증가"],"answer":2,"exp":"견인으로 추간공이 넓어져 신경근 압박이 줄고 팔의 통증·저림이 가벼워지면 양성임."},{"level":"중급","q":"스펄링 검사를 양성으로 판단하는 소견은?","options":["목에만 국한된 통증","어깨 결림","목의 근긴장","환측 팔로 뻗치는 통증"],"answer":3,"exp":"양성은 팔로 뻗치는 통증·저림의 재현임. 목 국소 통증만으로는 양성으로 보지 않음."},{"level":"임상","q":"50세 여성, 목 통증과 왼쪽 가운뎃손가락 저림. 왼쪽 위팔세갈래근 건반사가 저하됨. 가장 의심되는 신경근은?","options":["C5","C6","C7","C8"],"answer":2,"exp":"가운뎃손가락 감각 장애와 위팔세갈래근 건반사 저하는 C7 신경근 장애를 나타냄."},{"level":"임상","q":"65세 남성. 양손 저림과 단추 채우기 곤란이 있고 걸으면 비틀거림. 가장 적절한 대응은?","options":["의사에게 정보 제공","목을 강하게 견인","스펄링 검사 반복","목 도수 교정 시행"],"answer":0,"exp":"양측 손가락 교치성 저하와 보행 장애는 경추 척수병증을 의심하는 신호임. 유발 검사를 삼가고 의사에게 의뢰함."}],"seccion":"부위별 특수검사","grupo":"척추·골반","icono":"🦴","mapa":"img/mapas/t15.jpg","fichas":[],"secuencias":[]},"16":{"id":16,"title":"요추","lead":"요통에 다리 통증이나 저림이 동반되면 신경근의 관여를 평가합니다. 검사에서 재현된 증상과 신경학적 소견으로 장애 높이를 추정합니다.","sheet":{"kind":"tests","tests":[{"name":"SLR 검사","alias":"하지직거상 검사(라세그 징후)","steps":"바로 누운 자세에서 무릎을 편 채로 검사자가 다리를 천천히 수동으로 들어 올림.","positive":"엉덩이~종아리로 뻗치는 통증·저림의 재현","tissue":"L5·S1 신경근, 좌골신경","point":"허벅지 뒤쪽 당김은 햄스트링 신장과 구별함. 각도와 증상을 기록함."},{"name":"대퇴신경 신장 검사","alias":"FNS 검사","steps":"엎드린 자세에서 무릎을 수동으로 굴곡하고, 필요하면 고관절을 신전시킴.","positive":"허벅지 앞쪽으로 뻗치는 통증","tissue":"상위 요추 신경근(L2~L4), 대퇴신경","point":"대퇴사두근의 신장통이나 고관절 유래 통증과 구별함."},{"name":"켐프 검사","alias":"","steps":"선 자세 또는 앉은 자세에서 검사자가 몸통을 뒤로 신전시키며 환측으로 측굴·회전시킴.","positive":"허리 통증, 또는 환측 다리로 뻗치는 통증","tissue":"후관절·신경근(추간공 부위)","point":"국소 요통은 후관절, 다리로 뻗치는 통증은 신경근의 관여를 생각함."},{"name":"브라가드 검사","alias":"","steps":"SLR에서 증상이 나타난 각도에서 다리를 조금 내리고 발목을 수동으로 배측굴곡시킴.","positive":"다리의 방사통이 다시 나타나거나 악화됨","tissue":"좌골신경·요천부 신경근","point":"햄스트링 신장통과 신경 유래 증상을 구별하는 데 도움이 됨."}]},"keypoints":["요통만 있는지, 다리 증상을 동반하는지 먼저 구별","SLR은 하위, 대퇴신경 신장은 상위 요추 신경근을 봄","근육 신장감과 신경성 방사통을 나누어 기록함","피부분절·근력·건반사로 장애 높이를 추정함","배뇨·배변 장애나 회음부 저림은 응급으로 의사에게"],"case":{"text":"35세 남성. 무거운 물건을 든 뒤부터 요통과 오른쪽 종아리 바깥쪽~발등 저림. SLR 검사에서 오른 다리에 방사통, 브라가드 검사에서 악화. 엄지발가락 신전 근력이 저하됨.","answer":"L5 신경근 증상을 의심함(요추 추간판 탈출증 등). 통증을 악화시키는 전굴 부하는 삼감. 배뇨·배변 이상, 회음부 저림, 급속한 근력 저하가 있으면 응급으로 의사에게 의뢰함."},"questions":[{"level":"기초","q":"SLR 검사에서 주로 신장되는 신경은?","options":["대퇴신경","좌골신경","폐쇄신경","음부신경"],"answer":1,"exp":"무릎 신전 자세에서 고관절을 굴곡하면 다리 뒤쪽을 지나는 좌골신경과 L5·S1 신경근이 신장됨."},{"level":"기초","q":"대퇴신경 신장 검사로 평가하는 주된 신경근 높이는?","options":["L2~L4","L5~S1","S2~S4","C5~C6"],"answer":0,"exp":"대퇴신경은 L2~L4 신경근으로 이루어지며, 상위 요추 신경근 증상 평가에 사용함."},{"level":"중급","q":"브라가드 검사에서 가하는 조작은?","options":["발목 저측굴곡","고관절 외회전","무릎관절 굴곡","발목 배측굴곡"],"answer":3,"exp":"SLR에서 증상이 나타난 각도에서 조금 내리고 발목을 배측굴곡시켜 신경을 더 신장시킴."},{"level":"중급","q":"켐프 검사에서 다리 증상 없이 국소 요통만 나타난 경우 주로 의심하는 것은?","options":["신경근 압박","대퇴신경 장애","후관절 유래 통증","이상근 장애"],"answer":2,"exp":"신전·회전으로 후관절에 부하가 걸림. 국소 통증만 있으면 후관절 유래를 생각함."},{"level":"임상","q":"40세 여성, 요통과 왼발 바깥쪽~발바닥 저림. 왼쪽 아킬레스건 반사가 저하됨. 가장 의심되는 신경근은?","options":["L3","L4","L5","S1"],"answer":3,"exp":"발 바깥쪽·발바닥 감각 장애와 아킬레스건 반사 저하는 S1 신경근 장애를 나타냄."},{"level":"임상","q":"50세 남성. 요통에 더해 회음부 저림과 배뇨 곤란이 갑자기 나타남. 가장 적절한 대응은?","options":["즉시 의사에게 의뢰","SLR을 반복 평가","허리 운동치료 시작","온열치료로 경과 관찰"],"answer":0,"exp":"회음부 저림과 방광·직장 장애는 마미증후군을 의심하는 레드 플래그로 응급 대응이 필요함."}],"seccion":"부위별 특수검사","grupo":"척추·골반","icono":"🦴","mapa":"img/mapas/t16.jpg","fichas":[],"secuencias":[]},"17":{"id":17,"title":"천장관절","lead":"천장관절 유래 통증은 요통으로 오인되기 쉬운 부위입니다. 통증 부위 지목과 여러 유발 검사를 조합하여 추정합니다.","sheet":{"kind":"tests","tests":[{"name":"패트릭 검사","alias":"FABER 검사","steps":"바로 누운 자세에서 환측 발을 반대쪽 무릎 위에 놓고, 반대쪽 골반을 고정한 채 무릎을 바닥 쪽으로 누름.","positive":"엉덩이·천장관절 부위 통증(서혜부 통증이면 고관절)","tissue":"천장관절·고관절","point":"통증 부위로 구별함. 서혜부는 고관절, 엉덩이·천장관절 부위는 천장관절을 생각함."},{"name":"겐슬렌 검사","alias":"","steps":"바로 누운 자세에서 한쪽 다리를 침대 끝 밖으로 내려 고관절을 신전하고, 반대쪽은 굴곡하여 끌어안게 함.","positive":"신전한 쪽 천장관절 부위의 통증","tissue":"천장관절","point":"요추 과신전을 피하고, 떨어지지 않도록 몸통을 받쳐서 시행함."},{"name":"대퇴 밀기 검사","alias":"사이 스러스트 검사","steps":"바로 누운 자세에서 고관절 90° 굴곡 자세로 하고, 대퇴 장축을 따라 바닥 방향으로 압력을 가함.","positive":"같은 쪽 엉덩이·천장관절 부위의 통증","tissue":"천장관절","point":"아픈 곳을 본인이 가리키게 하고, 평소 통증과 같은지 확인함."},{"name":"골반 압박 검사","alias":"","steps":"옆으로 누운 자세에서 위쪽 장골능에 위에서 바닥 방향으로 압박을 가함.","positive":"천장관절 부위의 통증","tissue":"천장관절","point":"단독으로 판단하지 않음. 여러 유발 검사를 조합해 천장관절 유래 통증을 추정함."}]},"keypoints":["아픈 곳을 본인이 손가락 하나로 가리키게 함","후상장골극 부근의 통증은 천장관절 유래를 생각함","단독이 아닌 여러 유발 검사로 판단함","서혜부 통증은 고관절, 다리 방사통은 신경근도 고려","발열이나 안정 시 심한 통증이 있으면 의사에게 의뢰"],"case":{"text":"32세 여성, 출산 후 3개월. 한쪽 엉덩이 통증으로 돌아눕기나 한 발 서기에서 악화됨. 아픈 곳을 손가락 하나로 후상장골극 부근에 가리킴. 대퇴 밀기와 겐슬렌에서 통증이 재현됨.","answer":"천장관절 유래 통증을 의심함. 다리 방사통이나 신경 증상이 있으면 요추 유래도 고려함. 발열이나 안정 시 심한 통증이 있으면 의사에게 의뢰함. 골반대 안정화와 부하 조절부터 진행함."},"questions":[{"level":"기초","q":"한 손가락 검사에서 천장관절 유래 통증이 가리켜지기 쉬운 부위는?","options":["전상장골극 부근","후상장골극 부근","치골결합","좌골결절"],"answer":1,"exp":"천장관절 유래 통증에서는 후상장골극 부근을 손가락 하나로 가리키는 경우가 많음."},{"level":"기초","q":"천장관절을 구성하는 뼈의 조합은?","options":["천골과 장골","천골과 좌골","장골과 치골","제5요추와 천골"],"answer":0,"exp":"천장관절은 천골과 좌우 장골 사이의 관절로, 골반륜의 뒤쪽을 구성함."},{"level":"중급","q":"패트릭 검사에서 서혜부에 통증이 나타난 경우 의심하는 관절은?","options":["천장관절","고관절","무릎관절","후관절"],"answer":1,"exp":"굴곡·외전·외회전으로 서혜부가 아프면 고관절, 엉덩이 뒤쪽이면 천장관절을 생각함."},{"level":"중급","q":"대퇴 밀기 검사에서 압력을 가하는 방향은?","options":["대퇴를 바깥쪽으로","골반을 앞쪽으로","대퇴 장축을 따라 바닥 쪽","무릎을 안쪽으로"],"answer":2,"exp":"고관절 90° 굴곡 자세에서 대퇴 장축을 따라 압력을 가해 천장관절에 전단 스트레스를 줌."},{"level":"임상","q":"28세 여성, 출산 후 한쪽 엉덩이 통증. 겐슬렌, 대퇴 밀기, 골반 압박에서 통증이 재현됨. 가장 의심되는 부위는?","options":["고관절","L5 신경근","이상근","천장관절"],"answer":3,"exp":"여러 천장관절 유발 검사에서 같은 통증이 재현되므로 천장관절 유래를 가장 의심함."},{"level":"임상","q":"45세 남성, 한쪽 엉덩이 통증. 패트릭 검사에서만 엉덩이에 통증이 나타남. 다음 판단으로 가장 적절한 것은?","options":["천장관절 장애로 확정","다른 유발 검사도 조합","요추·고관절 평가 생략","강한 도수 교정 시행"],"answer":1,"exp":"양성 하나로는 판단할 수 없음. 여러 유발 검사와 요추·고관절 평가를 조합함."}],"seccion":"부위별 특수검사","grupo":"척추·골반","icono":"🦴","mapa":"img/mapas/t17.jpg","fichas":[],"secuencias":[]},"18":{"id":18,"title":"고관절","lead":"고관절 유래 통증은 서혜부에 나타나기 쉽고, 구축이나 근력 저하는 걸음걸이에 드러납니다. 검사로 관절 내·근육·보행에 미치는 영향을 확인합니다.","sheet":{"kind":"tests","tests":[{"name":"토마스 검사","alias":"","steps":"바로 누운 자세에서 한쪽 무릎을 가슴으로 끌어안아 요추 전만을 없앤 상태로, 반대쪽 대퇴가 뜨는지 봄.","positive":"반대쪽 대퇴가 바닥에서 뜸(고관절 굴곡 구축)","tissue":"장요근(고관절 굴곡근군)의 단축","point":"무릎이 신전되면 대퇴직근 단축도 의심함. 전만을 없앤 뒤 판정함."},{"name":"패트릭 검사","alias":"FABER 검사","steps":"바로 누운 자세에서 고관절을 굴곡·외전·외회전시키고(발을 반대쪽 무릎 위로) 무릎을 바닥 쪽으로 누름.","positive":"서혜부 통증, 또는 무릎이 내려가는 범위의 제한","tissue":"고관절·천장관절","point":"서혜부 통증은 고관절, 엉덩이 뒤쪽 통증은 천장관절을 생각함. 건측과 비교함."},{"name":"전방 충돌 검사","alias":"FADIR 검사","steps":"바로 누운 자세에서 고관절을 90° 굴곡시키고 수동으로 내전·내회전을 가함.","positive":"서혜부 통증의 재현","tissue":"고관절 전방(관절순·비구 가장자리)","point":"대퇴비구 충돌증후군이나 관절순 손상에서 양성이 되기 쉬움. 영상 소견과 통합함."},{"name":"트렌델렌버그 징후","alias":"","steps":"환측으로 한 발 서기를 시키고, 반대쪽(든 쪽) 골반의 높이를 뒤에서 관찰함.","positive":"든 쪽 골반이 하강함","tissue":"디딤다리 쪽 중둔근(고관절 외전근)","point":"몸통을 디딤다리 쪽으로 기울여 대상하면 듀센 징후. 넘어지지 않도록 받쳐 줌."}]},"keypoints":["고관절 유래 통증은 서혜부에 나타나기 쉬움","토마스 검사는 요추 전만을 없애고 굴곡 구축을 봄","트렌델렌버그는 디딤다리 쪽 중둔근 근력을 봄","요추나 천장관절 유래 통증과도 구별함","외상 후 체중부하 곤란이나 안정 시 통증 악화는 의사에게"],"case":{"text":"68세 여성, 고관절 골관절염. 보행 시 오른쪽 서혜부 통증. 오른쪽 한 발 서기에서 왼쪽 골반이 하강하고, 왼쪽 무릎을 가슴으로 끌어안으면 오른쪽 대퇴가 바닥에서 뜸.","answer":"오른쪽 중둔근 근력 저하와 오른쪽 고관절 굴곡 구축을 생각할 수 있음. 보행 시 대상 동작도 관찰하고, 통증에 유의하며 외전근 강화와 가동범위 운동을 진행함. 안정 시 통증의 급격한 악화는 의사에게 의뢰함."},"questions":[{"level":"기초","q":"토마스 검사로 단축을 평가하는 주된 근육은?","options":["대둔근","장요근","중둔근","햄스트링"],"answer":1,"exp":"반대쪽 대퇴가 뜨는 것은 고관절 굴곡 구축을 나타내며, 주된 고관절 굴곡근인 장요근의 단축을 봄."},{"level":"기초","q":"한 발 서기에서 반대쪽 골반이 내려가는 트렌델렌버그 징후에서 근력 저하가 의심되는 근육은?","options":["들린 다리 쪽 중둔근","디딤다리 쪽 대퇴사두근","디딤다리 쪽 중둔근","들린 다리 쪽 장요근"],"answer":2,"exp":"디딤다리 쪽 중둔근이 약하면 골반을 수평으로 유지하지 못해 반대쪽(든 쪽) 골반이 하강함."},{"level":"중급","q":"토마스 검사에서 무릎이 신전되는 경우 단축이 의심되는 근육은?","options":["대퇴직근","봉공근","대내전근","대퇴이두근"],"answer":0,"exp":"대퇴직근은 고관절과 무릎관절을 지나는 이관절근으로, 단축이 있으면 무릎이 신전됨."},{"level":"중급","q":"전방 충돌 검사(FADIR)에서 가하는 운동의 조합은?","options":["굴곡·외전·외회전","신전·외전·내회전","신전·내전·외회전","굴곡·내전·내회전"],"answer":3,"exp":"고관절 90° 굴곡 자세에서 내전·내회전을 가해 고관절 전방 통증의 재현을 봄."},{"level":"임상","q":"70세 남성. 오른 다리로 설 때마다 몸통을 오른쪽으로 크게 기울이며 걸음. 이 보행의 명칭은?","options":["계상 보행","휘돌림 보행","동결 보행","듀센 보행"],"answer":3,"exp":"중둔근 근력 저하를 몸통을 디딤다리 쪽으로 기울여 대상하는 보행을 듀센 보행이라 함."},{"level":"임상","q":"30세 남성, 축구 선수. 깊이 쪼그리면 서혜부가 아프고 고관절 굴곡·내전·내회전에서 통증이 재현됨. 가장 의심되는 것은?","options":["무릎 골관절염","대퇴비구 충돌증후군","L5 신경근병증","이상근 증후군"],"answer":1,"exp":"깊은 굴곡 시 서혜부 통증과 전방 충돌 검사 양성으로 대퇴비구 충돌증후군을 의심함."}],"seccion":"부위별 특수검사","grupo":"고관절·무릎관절","icono":"🦵","mapa":"img/mapas/t18.jpg","fichas":[],"secuencias":[]},"19":{"id":19,"title":"무릎관절: 인대","lead":"무릎 인대 검사는 전방·후방십자인대와 내측·외측 측부인대의 손상을 감별하는 평가입니다. 손상 기전과 건측 비교가 판단의 기본입니다.","sheet":{"kind":"tests","tests":[{"name":"라크만 검사","alias":"","steps":"바로 누운 자세에서 무릎 20~30° 굴곡. 한 손으로 대퇴 원위부, 다른 손으로 경골 근위부를 잡고 경골을 전방으로 당김.","positive":"건측보다 전방 이동이 크거나 끝점이 불분명함.","tissue":"전방십자인대(ACL)","point":"ACL 손상에 민감도가 높음. 무릎 90° 굴곡이 필요 없어 급성기에도 시행하기 쉬움."},{"name":"전방 당김 검사(전방 서랍 검사)","alias":"","steps":"바로 누운 자세에서 고관절 45°·무릎 90° 굴곡. 발을 고정하고 양손으로 경골 근위부를 잡아 전방으로 당김.","positive":"건측에 비해 경골의 전방 이동이 큼.","tissue":"전방십자인대(ACL)","point":"근육의 방어성 수축은 위음성의 원인. PCL 손상에 의한 경골 후방 처짐에도 주의."},{"name":"후방 당김 검사","alias":"","steps":"바로 누운 자세에서 고관절 45°·무릎 90° 굴곡. 발을 고정하고 경골 근위부를 후방으로 밂.","positive":"건측보다 경골의 후방 이동이 크고 끝점이 불분명함.","tissue":"후방십자인대(PCL)","point":"시작 전 경골의 후방 처짐(sag sign)을 확인하여 시작 위치를 잘못 잡지 않도록 함."},{"name":"외반/내반 스트레스 검사","alias":"","steps":"바로 누운 자세, 무릎 0°와 30° 굴곡 위치에서 대퇴 원위부를 고정하고 하퇴에 외반 또는 내반 힘을 가함.","positive":"관절 틈새의 통증 또는 건측보다 큰 벌어짐.","tissue":"외반=MCL, 내반=LCL","point":"30°에서만 양성이면 측부인대 단독, 0°에서도 양성이면 십자인대 등 동반 손상을 의심."}]},"keypoints":["ACL 평가는 라크만 검사를 우선하고 반드시 건측과 비교함.","무릎 꺾임·'뚝' 소리·급격한 부종 등 손상 기전을 문진으로 확인함.","후방 당김 검사 전에 후방 처짐 징후로 경골 위치를 확인함.","측부인대는 무릎 0°와 30° 모두에서 스트레스를 가함.","방어성 수축은 위음성의 원인이므로 힘을 뺀 자세에서 시행함."],"case":{"text":"20세 여성. 농구 착지 시 무릎이 안쪽으로 꺾이며 손상. '뚝' 하는 소리와 직후 부종이 있다. 라크만 검사에서 건측보다 전방 이동이 크고 끝점이 불분명하다.","answer":"ACL 손상을 의심하는 소견입니다. 반월상연골이나 측부인대의 동반 손상도 평가하고 의사에게 영상 진단을 의뢰합니다. 부종과 통증이 심한 시기에 강한 스트레스를 반복해서 가하지 않습니다."},"questions":[{"level":"기초","q":"그림에서 무릎 20~30° 굴곡 자세로 경골을 전방으로 당기는 검사는?","options":["전방 당김 검사","라크만 검사","후방 당김 검사","외반 스트레스 검사"],"answer":1,"exp":"라크만 검사는 무릎 20~30° 굴곡에서 경골을 전방으로 당겨 ACL을 평가합니다. 전방 당김 검사는 무릎 90°에서 시행합니다."},{"level":"기초","q":"그림에서 내반 스트레스 검사가 평가하는 인대는?","options":["내측 측부인대(MCL)","전방십자인대(ACL)","외측 측부인대(LCL)","후방십자인대(PCL)"],"answer":2,"exp":"내반 스트레스는 무릎 바깥쪽을 벌리는 힘으로 외측 측부인대(LCL)를 평가합니다. 외반 스트레스는 MCL을 평가합니다."},{"level":"중급","q":"후방 당김 검사 양성이 시사하는 손상은?","options":["PCL 손상","ACL 손상","LCL 손상","슬개골 탈구"],"answer":0,"exp":"후방 당김 검사는 무릎 90° 굴곡에서 경골을 후방으로 밀어 후방십자인대(PCL)를 평가합니다."},{"level":"중급","q":"외반 스트레스 검사가 무릎 0°에서도 양성일 때 먼저 고려할 것은?","options":["MCL의 경미한 단독 손상","외측 반월상연골만의 손상","슬개골 불안정성","십자인대 등 동반 손상"],"answer":3,"exp":"신전 위치에서는 십자인대와 관절낭도 안정성에 관여합니다. 0°에서도 벌어지면 MCL 단독이 아닌 동반 손상을 의심합니다."},{"level":"임상","q":"25세 남성. 축구 중 굽힌 무릎의 경골 앞면을 세게 부딪혔다. 무릎 90°에서 경골이 뒤로 처져 보인다. 의심되는 손상은?","options":["ACL 손상","PCL 손상","MCL 손상","내측 반월상연골 손상"],"answer":1,"exp":"경골 앞면에 대한 외력과 후방 처짐 징후는 PCL 손상의 전형입니다. 후방 당김 검사로 확인하고 의사에게 진단을 의뢰합니다."},{"level":"임상","q":"30세 여성. 스키 중 무릎 외반 강제로 손상. 외반 스트레스 시 30°에서 통증·벌어짐, 0°는 안정. 가장 적절한 것은?","options":["ACL 단독 손상","LCL 손상","MCL 단독 손상","PCL 손상"],"answer":2,"exp":"외반 강제로 30°에서만 양성이면 MCL 단독 손상을 생각할 수 있습니다. 0°에서도 양성이면 동반 손상을 의심합니다."}],"seccion":"부위별 특수검사","grupo":"고관절·무릎관절","icono":"🦵","mapa":"img/mapas/t19.jpg","fichas":[{"nombre":"라크만 검사","img":"img/fichas/lachman.jpg"}],"secuencias":[]},"20":{"id":20,"title":"무릎관절: 반월상연골·슬개골","lead":"반월상연골과 슬개골 검사는 비틀림이나 착지로 생기는 무릎 통증·걸림·불안정감의 원인을 찾는 평가입니다. 여러 소견을 종합해 판단합니다.","sheet":{"kind":"tests","tests":[{"name":"맥머레이 검사","alias":"","steps":"바로 누운 자세에서 무릎을 최대 굴곡하고, 하퇴를 외회전 또는 내회전하면서 무릎을 신전함.","positive":"관절 틈새의 딸깍 소리(클릭)나 통증.","tissue":"반월상연골(내측·외측)","point":"외회전은 내측, 내회전은 외측 반월상연골을 평가한다고 함. 단독으로 확진하지 않음."},{"name":"애플리 검사","alias":"애플리 압박 검사","steps":"엎드린 자세에서 무릎 90° 굴곡. 발꿈치에서 아래로 압박을 가하면서 하퇴를 내회전·외회전함.","positive":"압박과 회전 시 관절 틈새에 통증이 나타남.","tissue":"반월상연골","point":"견인하면서 회전할 때 통증이 나면 인대 등 반월상연골 이외의 조직을 고려함."},{"name":"테살리 검사","alias":"","steps":"검사자가 양손을 지지하고, 한 발 서기로 무릎 20° 굴곡을 유지한 채 체간과 무릎을 내·외회전시킴. 건측부터 시행.","positive":"관절 틈새의 통증, 잠김감이나 걸림감.","tissue":"반월상연골","point":"체중부하 자세의 검사. 넘어짐에 주의하고 양손 지지를 확보하여 시행함."},{"name":"슬개골 불안 검사","alias":"","steps":"바로 누운 자세에서 무릎 약간 굴곡. 넙다리네갈래근을 이완시키고 슬개골을 바깥쪽으로 천천히 밂.","positive":"불안감을 보이며 넙다리네갈래근을 수축시켜 막으려 함.","tissue":"슬개골 안정 구조(내측 슬개대퇴인대 등)","point":"슬개골 탈구·아탈구 병력 확인에 유용. 부드럽게 시행하고 탈구를 유발하지 않음."}]},"keypoints":["관절 틈새의 통증은 반월상연골 손상을 시사하는 중요한 소견.","반월상연골 검사는 단독으로 판단하지 않고 여러 소견을 종합함.","무릎이 끝까지 펴지지 않는 잠김은 의사 상담이 필요한 신호.","슬개골 검사는 불안감 유무를 관찰하며 부드럽게 시행함.","체중부하 검사는 넘어짐 예방을 위해 지지를 확보하고 시행함."],"case":{"text":"35세 남성. 무릎을 굽힌 상태로 비틀어 손상, 몇 시간 후 부종. 계단에서 무릎 안쪽 걸림감이 있다. 내측 관절 틈새에 압통, 맥머레이 검사에서 통증과 클릭이 있다.","answer":"내측 반월상연골 손상을 의심합니다. 인대 손상 동반 여부도 평가하고 의사에게 영상 진단을 의뢰합니다. 잠김이 있을 때 무리하게 신전시키지 않습니다."},"questions":[{"level":"기초","q":"그림에서 엎드린 자세·무릎 90°에서 압박과 회전을 가하는 검사는?","options":["맥머레이 검사","테살리 검사","애플리 검사","슬개골 불안 검사"],"answer":2,"exp":"애플리 검사는 엎드린 자세·무릎 90° 굴곡에서 발꿈치로 압박하면서 회전하여 반월상연골을 평가합니다."},{"level":"기초","q":"그림의 요약에서 반월상연골 손상을 시사한다고 한 소견은?","options":["관절 틈새의 통증","슬개골 위쪽의 통증","경골 거친면의 통증","대퇴 뒷면의 통증"],"answer":0,"exp":"관절 틈새(대퇴골과 경골 사이의 틈)의 통증은 반월상연골 손상을 시사합니다."},{"level":"중급","q":"맥머레이 검사에서 하퇴를 외회전하면서 신전할 때 주로 평가하는 것은?","options":["외측 반월상연골","내측 반월상연골","전방십자인대","슬개건"],"answer":1,"exp":"외회전은 내측 반월상연골, 내회전은 외측 반월상연골을 평가한다고 알려져 있습니다."},{"level":"중급","q":"슬개골 불안 검사의 양성 소견은?","options":["슬개골의 딸깍 소리","내측 관절 틈새의 통증","무릎 신전 제한","불안감과 사두근 방어 수축"],"answer":3,"exp":"슬개골을 바깥쪽으로 밀 때 불안감을 보이고 사두근을 수축시켜 막으려 하면 양성이며, 슬개골 불안정성을 시사합니다."},{"level":"임상","q":"18세 여성. 점프 착지 시 슬개골이 빠지는 느낌이 있었고 저절로 돌아왔다. 가장 적절한 평가는?","options":["슬개골 불안 검사","후방 당김 검사","톰슨 검사","내반 스트레스 검사"],"answer":0,"exp":"슬개골 탈구·아탈구를 의심하는 경과입니다. 슬개골 불안 검사로 불안정성을 확인합니다."},{"level":"임상","q":"40세 남성. 무릎 안쪽 걸림감이 계속되고 오늘 아침부터 무릎이 완전히 펴지지 않는다. 가장 적절한 대응은?","options":["강하게 타동 신전시켜 풂","의사에게 상담·평가 의뢰","테살리 검사를 반복","바로 근력 강화 시작"],"answer":1,"exp":"신전되지 않는 잠김은 반월상연골 끼임의 가능성이 있어 의사의 평가가 필요합니다. 무리한 신전이나 반복 검사는 피합니다."}],"seccion":"부위별 특수검사","grupo":"고관절·무릎관절","icono":"🦵","mapa":"img/mapas/t20.jpg","fichas":[{"nombre":"맥머레이 검사","img":"img/fichas/mcmurray.jpg"}],"secuencias":[]},"21":{"id":21,"title":"발목관절·발","lead":"발목관절·발 검사는 염좌에 의한 인대 손상이나 아킬레스건 파열을 감별하는 평가입니다. 항상 골절 가능성을 염두에 두고 시행합니다.","sheet":{"kind":"tests","tests":[{"name":"톰슨 검사","alias":"시몬즈 검사","steps":"엎드린 자세에서 발을 침대 끝 밖으로 냄. 종아리세갈래근(하퇴삼두근) 근복을 쥐듯이 압박함.","positive":"발목 저측굴곡이 일어나지 않거나 건측보다 확연히 작음.","tissue":"아킬레스건","point":"파열되어도 발가락 굽힘근 등으로 능동 저측굴곡이 가능할 수 있어 이 검사가 유용함."},{"name":"전방 당김 검사(발목관절)","alias":"","steps":"앉은 자세 또는 바로 누운 자세에서 발목 약간 저측굴곡. 경골 원위부를 고정하고 발꿈치를 잡아 거골을 전방으로 당김.","positive":"건측보다 큰 전방 이동, 끝점이 불분명함.","tissue":"전거비인대","point":"내반 염좌에서 가장 손상되기 쉬운 인대의 평가. 급성기에는 통증을 고려해 시행함."},{"name":"거골 경사 검사","alias":"내반 스트레스 검사","steps":"하퇴 원위부를 고정하고 종골을 잡아 발목을 내반 방향으로 기울임.","positive":"건측보다 큰 거골의 기울기, 통증.","tissue":"종비인대(전거비인대)","point":"전방 당김 검사와 함께 시행하여 외측 인대 손상의 정도를 판단함."},{"name":"압박 검사(스퀴즈 검사)","alias":"","steps":"바로 누운 자세에서 하퇴 중앙부의 경골과 비골을 양손으로 감싸 압박함.","positive":"발목 근위부(경골과 비골 사이)에 통증이 나타남.","tissue":"원위 경비인대","point":"높은 발목 염좌를 의심할 때 사용함. 골절 배제도 중요함."}]},"keypoints":["내반 염좌에서는 전거비인대가 가장 손상되기 쉬움.","아킬레스건 파열에서도 능동 저측굴곡이 가능한 경우가 있음.","뼈 압통이나 체중부하 곤란이 있으면 골절을 의심해 의사에게 의뢰.","인대 검사는 반드시 건측과 비교하여 판단함.","경골과 비골 사이의 통증은 높은 염좌를 생각하는 단서."],"case":{"text":"45세 남성. 테니스 중 뒤에서 차인 듯한 충격을 느끼고 손상. 발끝으로 설 수 없다. 엎드린 자세에서 종아리세갈래근을 쥐어도 발목이 저측굴곡하지 않는다.","answer":"톰슨 검사 양성으로 아킬레스건 파열을 의심합니다. 신속하게 의사의 진찰을 의뢰합니다. 능동 저측굴곡이 가능하더라도 파열을 배제하지 않습니다."},"questions":[{"level":"기초","q":"톰슨 검사로 평가하는 조직은?","options":["전거비인대","아킬레스건","종비인대","족저근막"],"answer":1,"exp":"종아리세갈래근을 쥐었을 때 발목이 저측굴곡하는지 보는 검사로, 아킬레스건의 연속성을 평가합니다."},{"level":"기초","q":"내반 염좌에서 가장 손상되기 쉬운 인대는?","options":["후거비인대","삼각인대","종비인대","전거비인대"],"answer":3,"exp":"저측굴곡을 동반한 내반으로 손상되는 경우가 많아 전거비인대가 가장 손상되기 쉽습니다. 중증에서는 종비인대도 손상됩니다."},{"level":"중급","q":"거골 경사 검사가 주로 평가하는 인대는?","options":["종비인대","삼각인대","아킬레스건","후경골근건"],"answer":0,"exp":"종골을 내반 방향으로 기울여 거골의 기울기를 보며 주로 종비인대를 평가합니다."},{"level":"중급","q":"압박 검사(스퀴즈 검사)에서 발목 근위부에 통증이 나타났다. 의심되는 것은?","options":["아킬레스건 파열","족저근막염","원위 경비인대 손상","무지외반증"],"answer":2,"exp":"하퇴 중앙 압박으로 원위 경비관절 부위에 통증이 나타나면 원위 경비인대 손상(높은 발목 염좌)을 의심합니다."},{"level":"임상","q":"22세 남성. 발을 안쪽으로 접질림. 외측 복사 앞쪽에 부종·압통, 뼈 압통은 없다. 전거비인대 평가에 가장 적절한 검사는?","options":["전방 당김 검사(발목관절)","톰슨 검사","라크만 검사","압박 검사(스퀴즈 검사)"],"answer":0,"exp":"전거비인대는 거골의 전방 이동을 제동합니다. 발목관절 전방 당김 검사로 건측과 비교합니다."},{"level":"임상","q":"60세 여성. 넘어지며 발목을 접질렸다. 외측 복사에 뼈 압통이 있고 체중을 실어 걸을 수 없다. 가장 적절한 대응은?","options":["전방 당김 검사를 반복","골절을 의심해 의사에게 의뢰","바로 균형 훈련","테이핑 후 보행 훈련"],"answer":1,"exp":"뼈 압통과 체중부하 곤란은 골절을 의심하는 신호입니다. 스트레스 검사나 운동보다 먼저 의사의 평가를 의뢰합니다."}],"seccion":"부위별 특수검사","grupo":"발목관절·발","icono":"🦶","mapa":"img/mapas/t21.jpg","fichas":[{"nombre":"톰슨 검사","img":"img/fichas/thompson.jpg"}],"secuencias":[{"nombre":"톰슨 검사","rotulo":"평가","texto":"아킬레스건","frames":["img/mov/teste-thompson-1.jpg","img/mov/teste-thompson-2.jpg","img/mov/teste-thompson-3.jpg"]}]},"22":{"id":22,"title":"신경학적 검사·신경역동 검사","lead":"신경역동 검사는 신경을 단계적으로 신장하여 증상의 재현을 보는 평가입니다. 신경근이나 말초신경 유래 통증을 감별하는 단서가 됩니다.","sheet":{"kind":"tests","tests":[{"name":"라세그 징후(하지직거상 검사, SLR)","alias":"하지직거상 검사","steps":"바로 누운 자세에서 무릎을 편 채 하지를 타동적으로 들어 올림. 증상이 나타난 각도를 기록하고 발목 배측굴곡 등으로 증강을 확인함.","positive":"볼기부에서 하지 뒷면으로의 방사통 등 증상이 재현됨.","tissue":"좌골신경, L5·S1 신경근 등","point":"햄스트링 신장감과 구별하려면 발목 배측굴곡이나 목 굴곡의 추가가 유용함."},{"name":"대퇴신경 신장 검사","alias":"FNST","steps":"엎드린 자세에서 무릎을 타동적으로 굴곡함. 필요에 따라 고관절 신전을 추가함.","positive":"대퇴 앞면으로의 방사통.","tissue":"대퇴신경, L2~L4 신경근","point":"넙다리네갈래근 신장감과 구별함. 상위 요추 신경근 병변의 평가에 사용함."},{"name":"슬럼프 검사","alias":"","steps":"앉은 자세에서 체간 굴곡→목 굴곡→무릎 신전→발목 배측굴곡을 차례로 더하고, 목 굴곡을 풀어 변화를 봄.","positive":"증상이 재현되고 목 굴곡을 풀면 경감됨.","tissue":"척추관 내에서 하지까지의 신경계","point":"한 단계씩 더하고 증상이 나타난 시점에서 멈춤. 좌우 차이를 비교함."},{"name":"상지 신경 긴장 검사(정중신경)","alias":"ULNT1","steps":"바로 누운 자세에서 어깨뼈 하강, 어깨 외전, 아래팔 회외, 손목·손가락 신전, 어깨 외회전, 팔꿈치 신전 후 목 측굴로 변화를 봄.","positive":"상지 증상이 재현되고 목 측굴로 변화함.","tissue":"정중신경, 경신경근","point":"건측과 비교하고, 떨어진 부위의 조작으로 증상이 변하면 신경 유래 가능성이 높아짐."}]},"keypoints":["신경 검사는 증상 재현과 좌우 차이로 판단함.","떨어진 부위의 조작으로 증상이 변하면 신경 유래를 고려함.","근육 신장감과 신경 증상을 구별하여 기록함.","증상이 나타난 시점에서 멈추고 강한 통증을 유발하지 않음.","진행하는 마비나 방광·직장 장애는 즉시 의사에게 의뢰함."],"case":{"text":"42세 남성. 무거운 짐을 들어 올린 후 요통과 오른쪽 하지 뒷면 통증이 발생. SLR 검사에서 오른쪽 하지 뒷면에 방사통이 재현되고 발목 배측굴곡으로 증강되었다.","answer":"요추 신경근 유래 증상을 의심하는 소견입니다. 근력·감각·반사로 손상 높이를 평가합니다. 방광·직장 장애나 진행하는 마비가 있으면 즉시 의사에게 의뢰합니다."},"questions":[{"level":"기초","q":"SLR 검사에서 주로 신장되는 신경은?","options":["정중신경","대퇴신경","좌골신경","자신경(척골신경)"],"answer":2,"exp":"무릎을 편 채 하지를 들어 올리면 하지 뒷면을 지나는 좌골신경과 하위 요신경근이 신장됩니다."},{"level":"기초","q":"대퇴신경 신장 검사를 시행하는 자세는?","options":["엎드린 자세","바로 누운 자세","다리 뻗고 앉은 자세","선 자세"],"answer":0,"exp":"엎드린 자세에서 무릎을 굴곡하여 대퇴 앞면을 지나는 대퇴신경을 신장합니다."},{"level":"중급","q":"SLR 검사에서 발목 배측굴곡을 더하자 증상이 증강되었다. 이것이 시사하는 것은?","options":["햄스트링 단축","신경 유래 증상","고관절 구축","발목 염좌"],"answer":1,"exp":"발목 배측굴곡은 근육 길이를 바꾸지 않고 신경 긴장을 높입니다. 증상이 증강되면 신경 유래를 시사합니다."},{"level":"중급","q":"슬럼프 검사에서 목 굴곡을 풀자 하지 증상이 경감되었다. 가장 적절한 해석은?","options":["근육 신장통","관절 불안정성","심인성 통증","신경계 민감성 증가"],"answer":3,"exp":"목의 조작은 하지 근육에 영향을 주지 않으므로, 증상이 변하면 신경계의 관여를 생각할 수 있습니다."},{"level":"임상","q":"50세 여성. 대퇴 앞면~무릎 안쪽 저림. 엎드린 자세에서 무릎을 굴곡하자 대퇴 앞면 통증이 재현되었다. 의심되는 높이는?","options":["L2~L4","L5","S1","C6"],"answer":0,"exp":"대퇴신경 신장 검사 양성과 대퇴 앞면 증상으로 상위 요추(L2~L4) 신경근 병변을 의심합니다."},{"level":"임상","q":"38세 남성. SLR 검사에서 하지 통증 재현. 최근 소변보기가 어렵고 회음부 감각이 둔하다. 가장 적절한 대응은?","options":["SLR 검사를 반복 확인","허리 근력 강화","즉시 의사에게 의뢰","신경 활주 운동을 계속"],"answer":2,"exp":"배뇨 장애나 회음부 감각 저하는 마미 증후군을 의심하는 레드 플래그입니다. 즉시 의사의 평가가 필요합니다."}],"seccion":"부위별 특수검사","grupo":"신경학적 검사","icono":"🧠","mapa":"img/mapas/t22.jpg","fichas":[{"nombre":"라세그 징후(하지직거상 검사, SLR)","img":"img/fichas/lasegue.jpg"}],"secuencias":[{"nombre":"라세그 징후","rotulo":"평가","texto":"좌골신경(L4~S1)","frames":["img/mov/teste-lasegue-1.jpg","img/mov/teste-lasegue-2.jpg","img/mov/teste-lasegue-3.jpg"]}]},"23":{"id":23,"title":"견봉하 충돌증후군·회전근개 파열","lead":"견봉하 충돌증후군은 팔을 올릴 때 회전근개나 견봉하 점액낭이 자극되어 아픈 상태입니다. 회전근개 파열과의 감별과 단계적 운동치료가 중요합니다.","sheet":{"kind":"condition","items":[{"h":"병태","t":"거상 시 회전근개(특히 가시위근 힘줄)나 견봉하 점액낭이 자극되어 아픕니다. 노화·과사용·외상을 배경으로 회전근개 파열에 이를 수 있습니다."},{"h":"주요 증상","t":"거상 시 통증(통증 호), 야간통, 환측을 아래로 하고 자기 어려움. 회전근개 파열에서는 거상·외회전 근력 저하가 나타납니다."},{"h":"평가 포인트","t":"니어·호킨스-케네디 검사로 충돌을, 조브 검사와 외회전 근력으로 회전근개 기능을 봅니다. 견갑골 움직임과 자세도 평가합니다."},{"h":"중재 흐름","t":"통증 관리와 활동 조절→가동범위 개선→회전근개·견갑골 주위근의 단계적 강화→동작 연습과 일·스포츠 복귀."},{"h":"주의사항·금기","t":"통증을 악화시키는 반복 거상은 피합니다. 파열 정도와 의사의 방침에 맞춰 부하를 조절하고 무리한 스트레칭은 하지 않습니다."},{"h":"의사 의뢰 신호","t":"외상 후 갑작스러운 거상 불가, 진행하는 근력 저하, 안정 시 통증 악화, 발열·부종, 저림 등 신경 증상."}]},"keypoints":["통증 호와 야간통은 흔한 호소.","거상·외회전 근력 저하는 회전근개 파열을 의심하는 단서.","견갑골 움직임과 자세도 함께 평가함.","운동은 통증 범위 안에서 단계적으로 부하를 높임.","외상 후 갑작스러운 거상 불가는 의사에게 평가 의뢰."],"case":{"text":"62세 남성. 몇 개월 전부터 어깨 외전 시 통증이 있고 야간통도 있다. 거상 중간 범위에서 통증이 심하고, 조브 검사에서 통증과 근력 저하를 보인다.","answer":"극상근건 병변이나 회전근개 파열을 의심합니다. 의사의 영상 진단과 방침을 확인하고, 통증 범위 안에서 가동범위와 회전근개·견갑골 주위근 운동을 진행합니다. 통증을 악화시키는 반복 거상은 피합니다."},"questions":[{"level":"기초","q":"견봉 아래를 지나 거상 시 자극받기 쉬운 힘줄은?","options":["가시위근(극상근) 힘줄","작은원근(소원근) 힘줄","큰가슴근(대흉근) 힘줄","위팔세갈래근 힘줄"],"answer":0,"exp":"가시위근 힘줄은 견봉 아래를 지나므로 거상 시 견봉하 점액낭과 함께 자극받기 쉽습니다."},{"level":"기초","q":"어깨 거상의 중간 범위에서만 통증이 나타나는 현상은?","options":["어깨-손 증후군","야간통","통증 호","팔 떨어뜨리기 징후"],"answer":2,"exp":"거상 도중 통증이 나타나고 더 올리면 경감되는 현상을 통증 호라고 합니다. 견봉하 병변에서 나타납니다."},{"level":"중급","q":"호킨스-케네디 검사로 주로 평가하는 것은?","options":["어깨관절 전방 불안정성","견봉하 충돌증후군","견봉쇄골관절 탈구","흉곽출구 증후군"],"answer":1,"exp":"어깨 90° 굴곡에서 내회전을 가해 견봉하에서 조직이 끼여 통증이 나는지 보는 충돌 검사입니다."},{"level":"중급","q":"회전근개 파열을 의심하는 소견으로 가장 적절한 것은?","options":["팔꿈치 굴곡 제한","악력 증가","손가락 저림만 있음","거상·외회전 근력 저하"],"answer":3,"exp":"회전근개는 거상과 외회전에 관여합니다. 근력 저하는 파열을 의심하는 단서이며 의사의 영상 진단으로 확인합니다."},{"level":"임상","q":"58세 여성. 넘어진 후 팔을 들 수 없다. 타동으로는 거상되지만 능동으로는 거상되지 않는다. 가장 적절한 것은?","options":["동결견","회전근개 파열","경추증","어깨관절 탈구"],"answer":1,"exp":"타동으로는 움직이지만 능동으로 올라가지 않는 것은 근육·힘줄의 기능 장애를 나타냅니다. 외상 후라면 회전근개 파열을 의심합니다. 동결견은 타동도 제한됩니다."},{"level":"임상","q":"45세 남성. 거상 시 통증이 지속되는 견봉하 충돌증후군. 초기 운동치료로 가장 적절한 것은?","options":["통증을 참는 반복 거상","무거운 아령으로 거상","통증 범위 안의 회전근개 운동","완전한 안정 지속"],"answer":2,"exp":"통증을 악화시키지 않는 범위에서 회전근개·견갑골 주위근 운동부터 시작하여 단계적으로 부하를 높입니다."}],"seccion":"질환·외상과 재활","grupo":"어깨관절","icono":"💪","mapa":"img/mapas/t23.jpg","fichas":[],"secuencias":[]},"24":{"id":24,"title":"동결견(오십견)","lead":"동결견은 어깨 통증과 가동범위 제한이 서서히 진행되는 상태로 중장년에게 많습니다. 병기에 맞춰 중재를 바꾸는 것이 중요합니다.","sheet":{"kind":"condition","items":[{"h":"병태","t":"어깨 관절낭 등의 염증과 섬유화로 통증과 가동범위 제한이 생깁니다. 원인이 뚜렷하지 않은 경우가 많고 당뇨병과의 관련이 지적됩니다."},{"h":"주요 증상","t":"야간통, 머리 빗기·뒷짐 동작의 어려움. 능동·타동 모두 가동범위가 제한되며 특히 외회전이 제한되기 쉽습니다."},{"h":"평가 포인트","t":"능동·타동 ROM을 비교하고 통증 정도, 야간통, ADL의 어려움을 평가합니다. 회전근개 파열 등 다른 질환과의 감별도 중요합니다."},{"h":"단계별 재활","t":"염증기는 통증 관리와 부드러운 운동, 구축기는 통증 범위 안의 스트레칭과 가동범위 운동, 회복기는 가동범위와 근력 회복."},{"h":"주의사항·금기","t":"염증기에 강한 신장을 가하면 통증이 악화될 수 있습니다. 통증을 참게 하는 무리한 타동 운동은 피합니다."},{"h":"의사 의뢰 신호","t":"외상 후 발병, 갑작스러운 근력 저하, 발열·부종, 체중 감소 등 전신 증상, 안정 시 통증의 급격한 악화."}]},"keypoints":["능동·타동 모두 가동범위가 제한되는 것이 특징.","특히 외회전 제한이 두드러지기 쉬움.","염증기에는 통증을 악화시키는 신장을 피함.","병기마다 중재 목표를 전환함.","회전근개 파열 등 다른 질환과 감별함."],"case":{"text":"55세 여성. 특별한 원인 없이 어깨 통증이 생겨 야간통으로 잠을 못 잔다. 몇 개월 사이 머리 빗기·뒷짐이 어려워졌고, 능동·타동 모두 외회전이 크게 제한되어 있다.","answer":"동결견을 의심합니다. 의사의 진단으로 다른 질환을 배제하고 현재 병기를 파악합니다. 통증이 심한 시기에는 강한 신장을 피하고 통증 관리와 부드러운 운동부터 시작합니다."},"questions":[{"level":"기초","q":"동결견에서 특히 제한되기 쉬운 운동은?","options":["팔꿈치 굴곡","손목 배측굴곡","견갑골 거상","어깨관절 외회전"],"answer":3,"exp":"동결견에서는 관절낭 구축으로 어깨의 여러 방향이 제한되며, 특히 외회전이 제한되기 쉽습니다."},{"level":"기초","q":"동결견에서 통증이 줄고 가동범위 제한이 주가 되는 시기는?","options":["염증기","구축기","회복기","급성기"],"answer":1,"exp":"염증기의 심한 통증이 가라앉으면 가동범위 제한이 주가 되는 구축기로 넘어갑니다. 그 후 회복기가 이어집니다."},{"level":"중급","q":"동결견과 회전근개 파열을 감별하는 데 도움이 되는 소견은?","options":["야간통의 유무","타동 가동범위 제한의 유무","나이","통증 부위"],"answer":1,"exp":"동결견은 타동으로도 가동범위가 제한됩니다. 회전근개 파열은 타동으로는 비교적 움직이지만 능동으로 올리기 어려운 경우가 많습니다."},{"level":"중급","q":"동결견 염증기의 중재로 가장 적절한 것은?","options":["통증 관리와 부드러운 운동","강한 타동 스트레칭","고부하 근력 강화","경기 복귀 연습"],"answer":0,"exp":"염증기는 통증이 심하고 강한 신장은 악화시킬 수 있습니다. 통증 관리와 통증을 악화시키지 않는 운동을 중심으로 합니다."},{"level":"임상","q":"52세 여성. 동결견 구축기로 통증은 가볍고 외회전과 뒷짐 동작이 제한되어 있다. 가장 적절한 중재는?","options":["완전한 안정","삼각건으로 고정","통증 범위 안의 가동범위 운동","통증을 참는 강한 신장"],"answer":2,"exp":"구축기는 통증이 줄어든 시기이므로 통증 범위 안에서 스트레칭과 가동범위 운동을 진행합니다."},{"level":"임상","q":"60세 남성. 어깨 통증과 가동범위 제한에 더해 최근 체중 감소와 안정 시 심한 통증이 있다. 가장 적절한 대응은?","options":["의사에게 의뢰","가동범위 운동 강화","온열만 하며 경과 관찰","근력 강화 시작"],"answer":0,"exp":"체중 감소와 안정 시 심한 통증은 중대한 질환의 가능성을 나타내는 레드 플래그입니다. 먼저 의사의 평가를 의뢰합니다."}],"seccion":"질환·외상과 재활","grupo":"어깨관절","icono":"💪","mapa":"img/mapas/t24.jpg","fichas":[],"secuencias":[]},"25":{"id":25,"title":"회전근개 봉합술 후","lead":"회전근개 봉합술 후 재활은 봉합한 힘줄을 보호하면서 가동범위와 근력을 단계적으로 되찾는 과정입니다. 의사가 지시한 시기와 제한을 지키는 것이 전제입니다.","sheet":{"kind":"condition","items":[{"h":"병태","t":"파열된 회전근개를 뼈에 다시 고정하는 수술입니다. 봉합한 힘줄이 뼈에 유합되기까지 시간이 걸리며, 너무 이른 부하는 재파열의 원인이 될 수 있습니다."},{"h":"주요 증상","t":"수술 후 통증·야간통, 가동범위 제한, 근력 저하. 보조기 고정에 따른 어깨 주변·목의 긴장과 팔꿈치·손의 움직임 저하도 나타납니다."},{"h":"평가 포인트","t":"통증, 타동·능동 ROM, 견갑골 움직임, 근력, ADL을 평가합니다. 수술 기록과 의사의 지시(금기 자세·시기)를 확인합니다."},{"h":"단계별 재활","t":"보호기(보조기·타동 운동)→능동 보조 운동·능동 운동→단계적 근력 강화→일상 동작·일·스포츠 복귀."},{"h":"주의사항·금기","t":"지시된 시기 전의 능동 거상이나 저항 운동, 봉합 힘줄을 강하게 신장하는 자세는 피합니다. 팔꿈치·손가락은 고정 중에도 움직입니다."},{"h":"의사 의뢰 신호","t":"갑작스러운 통증 악화나 거상력 저하(재파열 의심), 상처 부위의 발적·부종·열감, 발열, 저림의 출현."}]},"keypoints":["시기와 금기 자세는 의사 지시와 수술 기록으로 확인.","보호기에는 봉합 힘줄을 보호하고 타동 운동 중심으로 시행.","고정 중에도 팔꿈치·손가락·견갑골 운동을 시행함.","저항 운동은 지시된 시기부터 단계적으로 추가함.","갑작스러운 거상력 저하는 재파열을 의심해 의사에게 의뢰."],"case":{"text":"60세 남성. 회전근개 봉합술 후 초기로 보조기를 착용 중. 빨리 일에 복귀하고 싶어 스스로 팔을 들어 올리는 연습을 하고 있었다고 한다.","answer":"보호기에 지시 없는 능동 거상은 봉합 힘줄에 부담이 됩니다. 의사의 지시를 확인하고, 허용된 타동 운동과 팔꿈치·손가락 운동을 중심으로 하며 시기를 지키는 이유를 설명합니다."},"questions":[{"level":"기초","q":"회전근개 봉합술 후 초기에 보조기를 사용하는 주된 목적은?","options":["근력을 강화한다","가동범위를 넓힌다","봉합한 힘줄을 보호한다","부종을 예방한다"],"answer":2,"exp":"보호기에는 봉합한 힘줄이 뼈에 유합될 때까지 부담을 주지 않도록 보조기로 고정하여 힘줄을 보호합니다."},{"level":"기초","q":"회전근개 봉합술 후 재활에서 마지막 단계에 도입되는 것은?","options":["보조기 고정","타동 운동","능동 보조 운동","저항 운동"],"answer":3,"exp":"보호기의 고정·타동 운동에서 능동 보조·능동 운동을 거쳐, 마지막으로 저항 운동에 의한 근력 강화로 진행합니다."},{"level":"중급","q":"회전근개 봉합술 후 보호기에 피해야 할 운동은?","options":["지시 전 어깨 능동 거상","팔꿈치 능동 굴신","손가락 운동","지시된 타동 운동"],"answer":0,"exp":"보호기에 지시 없는 어깨 능동 거상은 봉합 힘줄에 부담을 줍니다. 팔꿈치·손가락 운동은 고정 중에도 시행합니다."},{"level":"중급","q":"수술 후 운동 진행을 결정할 때 먼저 확인해야 할 것은?","options":["환자의 희망만","의사의 지시와 수술 기록","건측의 근력","나이만"],"answer":1,"exp":"파열 크기나 봉합 방법에 따라 시기와 금기 자세가 다르므로 의사의 지시와 수술 기록을 확인합니다."},{"level":"임상","q":"65세 여성. 회전근개 봉합술 후 경과 순조. 물건을 들다 통증이 나고 갑자기 팔이 올라가지 않는다. 가장 적절한 대응은?","options":["저항 운동을 강화","같은 운동을 계속","강한 스트레칭 시행","의사에게 보고·평가 의뢰"],"answer":3,"exp":"갑작스러운 통증과 거상력 저하는 재파열 가능성이 있습니다. 운동을 중지하고 의사에게 보고하여 평가를 의뢰합니다."},{"level":"임상","q":"58세 남성. 회전근개 봉합술 후 보조기 고정 중. 팔꿈치와 손가락이 뻣뻣하다고 호소한다. 가장 적절한 대응은?","options":["팔꿈치·손가락 운동 지도","어깨 능동 거상 시작","아무것도 하지 않고 고정 유지","어깨에 저항 운동 추가"],"answer":0,"exp":"고정 중에도 팔꿈치·손가락 운동을 시행하여 뻣뻣함을 예방합니다. 어깨 능동 거상과 저항 운동은 지시된 시기까지 기다립니다."}],"seccion":"질환·외상과 재활","grupo":"어깨관절","icono":"💪","mapa":"img/mapas/t25.jpg","fichas":[],"secuencias":[]},"26":{"id":26,"title":"건병증","lead":"건병증은 반복되는 부하에 힘줄이 적응하지 못해 통증과 기능 저하가 생기는 상태입니다. 안정만이 아니라 부하 조절과 단계적 부하가 회복의 열쇠입니다.","sheet":{"kind":"condition","items":[{"h":"병태","t":"힘줄에 대한 반복 부하가 회복을 웃돌아 힘줄의 구조나 기능이 변하고 통증이 생깁니다. 갑작스러운 훈련량 증가 등이 유발 요인이 되기 쉽습니다."},{"h":"주요 증상","t":"운동 초반이나 다음 날 아침의 통증·뻣뻣함, 힘줄의 국소 압통. 움직이는 동안 경감되고 운동 후 악화되기도 합니다."},{"h":"평가 포인트","t":"힘줄 압통, 한 발 발꿈치 들기나 한 발 스쿼트 등 부하 시 통증, 훈련량·신발·노면의 변화를 확인합니다."},{"h":"중재 흐름","t":"부하 조절→등척성 운동→등장성(원심성 포함) 근력 강화→점프 등 빠른 동작→경기 복귀."},{"h":"주의사항·금기","t":"완전한 안정은 힘줄의 부하 내성을 떨어뜨릴 수 있습니다. 통증을 크게 악화시키는 부하나 다음 날까지 남는 강한 통증은 피합니다."},{"h":"의사 의뢰 신호","t":"갑작스러운 파열감이나 '뚝' 소리, 뚜렷한 근력 저하, 심한 부종·열감, 개선되지 않는 야간통이나 안정 시 통증."}]},"keypoints":["갑작스러운 훈련량 증가는 건병증의 유발 요인이 되기 쉬움.","완전한 안정보다 통증에 따른 부하 조절을 시행함.","운동 후나 다음 날 통증으로 부하량을 재검토함.","등척성 운동에서 단계적으로 높은 부하로 진행함.","파열감이나 갑작스러운 근력 저하는 의사에게 의뢰."],"case":{"text":"28세 남성 러너. 주행 거리를 갑자기 늘린 후 아침의 아킬레스건 뻣뻣함과 통증이 계속된다. 달리기 시작할 때 아프고 도중에 경감된다. 힘줄 중앙부에 압통이 있다.","answer":"아킬레스 건병증을 의심합니다. 완전한 안정이 아니라 주행량을 조절하고, 통증에 따라 발꿈치 들기 등 단계적 부하를 진행합니다. 파열감이나 근력 저하가 있으면 의사에게 의뢰합니다."},"questions":[{"level":"기초","q":"건병증의 유발 요인으로 대표적인 것은?","options":["장기간의 안정","갑작스러운 훈련량 증가","충분한 수면","유연성 향상"],"answer":1,"exp":"힘줄의 회복을 웃도는 부하, 특히 훈련량의 갑작스러운 증가가 건병증의 대표적인 유발 요인입니다."},{"level":"기초","q":"건병증에서 흔히 보이는 통증의 특징은?","options":["야간에만 심한 통증","안정 시 계속 악화","항상 일정한 강도","운동 초반 통증과 아침 뻣뻣함"],"answer":3,"exp":"운동 초반이나 다음 날 아침에 통증·뻣뻣함이 나타나고 움직이는 동안 경감되는 경우가 많습니다."},{"level":"중급","q":"건병증의 단계적 부하에서 비교적 후반에 도입하는 것은?","options":["등척성 운동","천천히 하는 근력 강화","점프 등 빠른 동작","부하량 조절"],"answer":2,"exp":"통증을 관리하면서 등척성·등장성 운동으로 내성을 높이고, 그 후 점프 등 빠른 동작으로 진행합니다."},{"level":"중급","q":"건병증의 부하량을 재검토하는 기준으로 가장 적절한 것은?","options":["운동 다음 날 통증 변화","체중 변화","기온","훈련 시간대"],"answer":0,"exp":"운동 중뿐 아니라 다음 날의 통증과 뻣뻣함 변화를 보고 부하량을 조절합니다."},{"level":"임상","q":"22세 여성 배구 선수. 점프 후 슬개골 아래 끝이 아프고 슬개건에 압통이 있다. 가장 적절한 것은?","options":["전방십자인대 손상","슬개건병증","반월상연골 손상","슬개골 탈구"],"answer":1,"exp":"점프 동작의 반복과 슬개골 아래 끝·슬개건의 압통은 슬개건병증의 전형적인 소견입니다."},{"level":"임상","q":"40세 남성. 아킬레스 건병증 치료 중 테니스에서 뒤에서 차인 듯한 충격 후 발끝으로 설 수 없다. 가장 적절한 대응은?","options":["원심성 운동을 계속","부하를 더 높임","스트레칭을 강화","파열을 의심해 의사에게 의뢰"],"answer":3,"exp":"갑작스러운 충격감과 발끝 서기 불가는 아킬레스건 파열을 의심하는 소견입니다. 운동을 중지하고 의사의 평가를 의뢰합니다."}],"seccion":"질환·외상과 재활","grupo":"스포츠·힘줄·근육","icono":"🏃","mapa":"img/mapas/t26.jpg","fichas":[],"secuencias":[]},"27":{"id":27,"title":"발목 염좌","lead":"발목 염좌는 흔한 스포츠 외상의 하나로, 저측굴곡을 동반한 내반으로 일어나는 경우가 많습니다. 재발 예방에는 고유수용감각 훈련이 중요합니다.","sheet":{"kind":"condition","items":[{"h":"병태","t":"저측굴곡을 동반한 내반으로 외측 인대가 손상됩니다. 가장 손상되기 쉬운 것은 전거비인대이며, 중증도에 따라 종비인대도 손상됩니다."},{"h":"주요 증상","t":"외측 복사 주위의 통증·부종·피하 출혈, 체중부하 시 통증. 불안정감이나 반복되는 염좌를 호소하기도 합니다."},{"h":"평가 포인트","t":"손상 기전, 압통 부위, 체중부하 가능 여부, 전방 당김 검사·거골 경사 검사. 골절이나 다른 인대 손상을 놓치지 않습니다."},{"h":"단계별 재활","t":"1 보호·냉각·압박·거상→2 가동성과 단계적 체중부하→3 근력 강화와 고유수용감각→4 달리기·점프·경기 복귀."},{"h":"주의사항·금기","t":"급성기에 통증을 악화시키는 운동은 피합니다. 고유수용감각·균형 훈련을 생략하면 재발이나 불안정감이 남기 쉽습니다."},{"h":"의사 의뢰 신호","t":"뼈 압통이나 체중부하 곤란(골절 의심), 심한 부종이나 변형, 저림, 개선되지 않는 통증이나 반복되는 불안정감."}]},"keypoints":["손상 기전은 저측굴곡을 동반한 내반이 많음.","가장 손상되기 쉬운 것은 전거비인대.","뼈 압통이나 체중부하 곤란이 있으면 골절을 의심함.","고유수용감각 훈련으로 재발 위험이 낮아짐.","경기 복귀는 한 발 동작을 확인한 후 단계적으로."],"case":{"text":"19세 남성. 축구 중 발을 안쪽으로 접질려 손상. 다음 날 외측 복사 앞쪽에 부종과 압통이 있으나 뼈 압통은 없고 체중부하는 가능. 전방 당김 검사에서 건측보다 전방 이동이 크다.","answer":"전거비인대 손상을 동반한 내반 염좌를 의심합니다. 보호·냉각·압박·거상과 통증에 따른 체중부하부터 시작하여, 근력과 고유수용감각 훈련을 거쳐 단계적으로 복귀합니다."},"questions":[{"level":"기초","q":"그림에서 발목 염좌의 전형적인 손상 기전은?","options":["배측굴곡을 동반한 외반","저측굴곡을 동반한 내반","배측굴곡을 동반한 내반","저측굴곡을 동반한 외반"],"answer":1,"exp":"발목 염좌는 저측굴곡을 동반한 내반으로 일어나는 경우가 많고, 외측의 전거비인대가 가장 손상되기 쉽습니다."},{"level":"기초","q":"그림에서 3단계의 내용은?","options":["보호·냉각·압박·거상","가동성과 단계적 체중부하","근력 강화와 고유수용감각","달리기·경기 복귀"],"answer":2,"exp":"1단계는 보호·냉각·압박·거상, 2단계는 가동성과 체중부하, 3단계는 근력 강화와 고유수용감각, 4단계는 경기 복귀입니다."},{"level":"중급","q":"단계적 체중부하를 시작하는 것은 몇 단계부터인가?","options":["1단계","2단계","3단계","4단계"],"answer":1,"exp":"1단계의 보호 후, 2단계에서 가동성 개선과 함께 통증에 따라 단계적으로 체중부하를 진행합니다."},{"level":"중급","q":"발목 염좌의 재발 예방에 특히 중요하다고 알려진 훈련은?","options":["장기간 고정","완전한 안정","상지 근력 강화","고유수용감각 훈련"],"answer":3,"exp":"균형판이나 한 발 서기 등 고유수용감각 훈련은 재발 위험을 낮춘다고 알려져 있습니다."},{"level":"임상","q":"24세 여성. 염좌 후 3주로 통증은 거의 없으나 한 발 서기에서 발목이 흔들린다. 우선할 중재로 가장 적절한 것은?","options":["균형·고유수용감각 훈련","냉각과 거상","완전한 안정","바로 전력 질주"],"answer":0,"exp":"통증이 가라앉고 불안정성이 남은 단계입니다. 한 발 서기 등 고유수용감각·근력 훈련을 우선하고 단계적으로 복귀를 진행합니다."},{"level":"임상","q":"20세 남성. 발목 염좌를 여러 번 반복하고 일상생활에서도 발목이 흔들리는 느낌이 있다. 가장 적절한 것은?","options":["아킬레스건 파열","족저근막염","만성 발목 불안정증","무지외반증"],"answer":2,"exp":"반복되는 염좌와 불안정감은 만성 발목 불안정증을 시사합니다. 고유수용감각과 근력 훈련이 중요하며 필요에 따라 의사와 상담합니다."}],"seccion":"질환·외상과 재활","grupo":"스포츠·힘줄·근육","icono":"🏃","mapa":"img/mapas/t27.jpg","fichas":[],"secuencias":[]},"28":{"id":28,"title":"근육 손상","lead":"근육 손상은 근육 파열(근육의 부분 파열)과 근육 타박상으로 크게 나뉘는 스포츠 외상입니다. 재발이 잦아 단계적 부하와 복귀 기준 설정이 중요합니다.","sheet":{"kind":"condition","items":[{"h":"병태","t":"근육 파열은 근육이 수축하면서 늘어나는 원심성 수축 시 잘 생기며 근건 이행부에 많다. 근육 타박상은 외력에 의한 직접 외상으로 넙다리네갈래근(대퇴사두근)에 많다."},{"h":"주요 증상","t":"손상 시 통증이나 파열감, 압통, 부종·피하출혈, 근육 신장 시나 저항 시 통증, 근력 저하. 중증에서는 함몰이 촉지되기도 한다."},{"h":"평가 포인트","t":"손상 기전, 압통 부위, 신장 시 통증(SLR 각도 등의 좌우 차이), 저항 시 통증, 보행 양상. 중증도는 영상 소견을 포함해 의사가 판단한다."},{"h":"단계별 재활","t":"급성기는 보호와 부종 관리. 통증에 따라 등척성→구심성→원심성 수축으로 진행하고 달리기도 단계적으로. 복귀 전 경기 동작을 확인한다."},{"h":"주의사항·금기","t":"급성기의 강한 스트레칭이나 강한 마사지는 피한다. 대퇴부 타박 후 강한 자극은 골화성 근염의 유발 요인으로 알려져 있다. 통증을 참게 하지 않는다."},{"h":"의사에게 의뢰","t":"뚜렷한 함몰이나 파열감, 부종의 급격한 증가, 강한 통증의 지속, 저림이나 피부색 변화(구획증후군 의심)."}]},"keypoints":["근육 파열은 원심성 수축 시 근건 이행부에서 잘 생김","급성기는 보호와 부종 관리, 강한 신장은 피함","부하는 등척성→구심성→원심성 순으로 진행","햄스트링에는 원심성 훈련을 포함함","복귀는 통증·유연성·근력·경기 동작으로 판단"],"case":{"text":"20세 남성, 육상 단거리 선수. 전력 질주 중 대퇴 후면에 통증을 느껴 경기를 중단했다. 다음 날 대퇴이두근에 압통과 피하출혈이 있고, SLR에서 좌우 차이와 신장 시 통증이 있다.","answer":"햄스트링 근육 파열을 생각한다. 급성기는 보호와 부종 관리를 우선하고 강한 스트레칭이나 마사지는 피한다. 통증에 따라 등척성 수축부터 단계적으로 부하를 올린다. 함몰 등 중증 의심 소견은 의사에게 의뢰한다."},"questions":[{"level":"기초","q":"근육 파열이 가장 잘 발생하는 부위는?","options":["근복의 중앙","근건 이행부","골막","힘줄의 뼈 부착부"],"answer":1,"exp":"근육 파열은 근육과 힘줄의 이행부에서 많이 발생합니다. 햄스트링에서는 대퇴이두근 장두에 많습니다."},{"level":"기초","q":"근육 파열이 잘 생기는 근수축 양식은?","options":["등척성 수축","구심성 수축","원심성 수축","등속성 수축"],"answer":2,"exp":"근육이 수축하면서 늘어나는 원심성 수축 시 잘 생기며, 질주 중 유각기 후반이 전형적인 상황입니다."},{"level":"중급","q":"근육 파열 후 근력 훈련의 일반적인 진행 순서로 가장 적절한 것은?","options":["원심성→구심성→등척성","등척성→구심성→원심성","구심성→등척성→원심성","처음부터 전력 원심성"],"answer":1,"exp":"통증에 따라 부하가 작은 등척성 수축부터 시작해 구심성 수축, 원심성 수축으로 단계적으로 진행합니다."},{"level":"중급","q":"대퇴부 타박 후 강한 마사지나 강한 신장을 피하는 이유로 가장 적절한 것은?","options":["골화성 근염의 유발 요인","근위축이 생기지 않게 됨","힘줄이 단축됨","신경이 재생되지 않음"],"answer":0,"exp":"타박 후 초기의 강한 자극은 근육 내 출혈을 늘려 골화성 근염의 유발 요인이 되는 것으로 알려져 있습니다."},{"level":"임상","q":"축구 선수. 킥 동작에서 대퇴 전면 통증이 생겼고 다음 날도 압통과 신장 시 통증이 있다. 급성기 대응으로 가장 적절한 것은?","options":["강한 스트레칭 시행","보호와 부종 관리 시행","전력 스프린트로 확인","강한 마사지 시행"],"answer":1,"exp":"급성기는 보호와 부종 관리를 우선합니다. 강한 신장이나 마사지, 전력 동작 확인은 손상을 악화시킬 우려가 있습니다."},{"level":"임상","q":"대퇴부를 세게 부딪친 고등학생. 부종이 급격히 커지고 강한 통증과 발 저림을 호소한다. 우선해야 할 대응은?","options":["온열치료 시행","스트레칭 지도","신속히 의사에게 의뢰","근력 훈련 시작"],"answer":2,"exp":"부종의 급격한 증가, 강한 통증, 저림은 구획증후군을 의심하는 징후로 신속한 의사의 평가가 필요합니다."}],"seccion":"질환·외상과 재활","grupo":"스포츠·힘줄·근육","icono":"🏃","mapa":"img/mapas/t28.jpg","fichas":[],"secuencias":[]},"29":{"id":29,"title":"전방십자인대·반월상연골 손상","lead":"ACL 손상은 스포츠 중 착지나 방향 전환에서 잘 생기며 반월상연골 손상을 동반하는 경우도 많은 외상입니다. 조기 평가와 동작 재교육이 예후를 좌우합니다.","sheet":{"kind":"condition","items":[{"h":"병태","t":"ACL 손상은 착지나 방향 전환 시 비접촉성이 많고 무릎 외반과 하퇴 회전이 관여한다. 반월상연골 손상은 체중부하 중 회전으로 생기며 ACL 손상에 잘 동반된다."},{"h":"주요 증상","t":"ACL: 손상 시 파열음, 관절혈종에 의한 부종, 무릎 꺾임(giving way). 반월상연골: 관절선 통증, 걸리는 느낌, 잠김(locking), 가동범위 제한."},{"h":"평가 포인트","t":"ACL은 라크만 검사, 전방 당김 검사, 피벗 이동 검사. 반월상연골은 관절선 압통, 맥머레이 검사. 확정 진단은 의사가 한다."},{"h":"중재 흐름","t":"급성기는 부종 관리, 신전 가동범위와 대퇴사두근 수축을 확보. 보존치료와 재건술은 의사가 판단한다. 수술 전부터 근력과 가동범위를 갖춰 둔다."},{"h":"주의사항·금기","t":"무릎 꺾임이 반복되면 반월상연골이나 연골 손상이 진행될 우려가 있다. 잠김 중 무리한 가동범위 훈련은 피한다. 동작 시 무릎 안쪽 무너짐에 주의한다."},{"h":"의사에게 의뢰","t":"잠김으로 신전 불가, 손상 직후 급격한 관절 부종, 무릎 꺾임의 반복, 강한 통증의 지속, 골절 의심 소견."}]},"keypoints":["ACL 손상은 비접촉성이 많고 무릎 안쪽 무너짐이 위험 자세","ACL 평가의 기본은 라크만 검사","반월상연골 손상은 관절선 압통과 걸리는 느낌","잠김으로 신전이 안 되면 의사에게 의뢰","예방으로 착지·방향 전환 동작을 지도"],"case":{"text":"17세 여자 농구 선수. 점프 착지 시 무릎이 안쪽으로 들어가며 파열음과 함께 넘어졌다. 몇 시간 만에 무릎이 붓고, 라크만 검사에서 전방 이동 증가와 끝 저항 소실을 보인다.","answer":"ACL 손상을 의심한다. 급성기는 부종 관리와 신전 가동범위·대퇴사두근 수축 확보를 우선한다. 반월상연골 동반도 고려해 잠김 유무를 확인한다. 보존·재건은 의사가 판단하며 임의로 경기에 복귀시키지 않는다."},"questions":[{"level":"기초","q":"비접촉성 ACL 손상의 전형적인 손상 자세는?","options":["무릎 내반(니아웃)","무릎 외반(니인)","무릎 과굴곡","슬개골에 직접 외력"],"answer":1,"exp":"비접촉성 ACL 손상은 착지나 방향 전환에서 무릎이 안쪽으로 들어가는 니인(무릎 외반) 자세에서 잘 생깁니다."},{"level":"기초","q":"반월상연골 손상에 특징적인 증상은?","options":["잠김(locking)","하수족","슬개건 반사 소실","대퇴 전면 감각 저하"],"answer":0,"exp":"반월상연골의 손상 부위가 관절 내에 끼이면 무릎이 일정 각도에서 움직이지 않는 잠김이 생깁니다."},{"level":"중급","q":"ACL 손상 평가에서 민감도가 가장 높은 도수 검사는?","options":["맥머레이 검사","후방 당김 검사","라크만 검사","외반 스트레스 검사"],"answer":2,"exp":"라크만 검사는 무릎 약간 굴곡 자세에서 경골을 전방으로 당겨 전방 이동량과 끝 저항을 평가합니다. ACL 평가의 기본입니다."},{"level":"중급","q":"맥머레이 검사의 양성 소견은?","options":["경골의 전방 이동 증가","회전하며 신전 시 딸깍음과 통증","슬개골 불안감","내측 관절 간격 벌어짐"],"answer":1,"exp":"무릎 굴곡 자세에서 하퇴를 회전시키며 신전해 관절선에 딸깍음이나 통증이 나타나면 반월상연골 손상을 의심합니다."},{"level":"임상","q":"축구 선수. 방향 전환 중 무릎을 비튼 후 무릎이 걸려 완전히 펴지지 않는다. 가장 가능성이 높은 것은?","options":["슬개건염","장경인대염","반월상연골 손상에 의한 잠김","오스굿-슐라터병"],"answer":2,"exp":"회전 외상 후 신전이 안 되는 상태는 잠김을 시사합니다. 무리한 가동범위 훈련은 피하고 의사의 평가로 연결합니다."},{"level":"임상","q":"ACL 손상 후 2일째로 무릎 부종이 있다. 보존적 관리 초기에 우선할 내용으로 가장 적절한 것은?","options":["점프 연습","부종 관리와 신전 가동범위 확보","전력 방향 전환 연습","깊은 스쿼트 부하"],"answer":1,"exp":"초기에는 부종을 관리하고 신전 가동범위와 대퇴사두근 수축을 확보합니다. 고부하 동작은 무릎 꺾임이나 2차 손상 우려가 있습니다."}],"seccion":"질환·외상과 재활","grupo":"스포츠·힘줄·근육","icono":"🏃","mapa":"img/mapas/t29.jpg","fichas":[],"secuencias":[]},"30":{"id":30,"title":"전방십자인대 재건술 후","lead":"ACL 재건술 후 재활은 이식건을 보호하면서 가동범위·근력·동작을 단계적으로 되찾는 과정입니다. 신전 제한을 남기지 않는 것이 첫 번째 목표입니다.","sheet":{"kind":"condition","items":[{"h":"병태·수술법","t":"자가건(햄스트링건이나 골-슬개건-골 등)으로 인대를 재건하는 수술. 이식건은 수술 후 재형성되며 시간이 지나며 강도를 얻어 간다."},{"h":"수술 후 과제","t":"수술 후 초기에는 부종, 통증, 신전 제한, 대퇴사두근 근출력 저하가 나타나기 쉽다. 채취 부위의 통증이나 근력 저하도 고려한다."},{"h":"평가 포인트","t":"부종, 무릎 신전·굴곡 각도의 좌우 차이, 대퇴사두근 수의적 수축(신전 지연, extension lag), 보행 양상, 근력, 홉 검사 등 기능 검사."},{"h":"단계별 재활","t":"0~2주: 완전 신전과 대퇴사두근. 2~6주: 정상 보행과 굴곡 확대. 6~12주: 근력과 고유수용감각. 3~6개월: 단계적 달리기와 점프. 6개월~: 경기 복귀 검사."},{"h":"주의사항·금기","t":"신전 제한을 남기지 않는다. 이식건에 부담을 주는 운동의 시작 시기는 수술법과 의사의 지시에 따른다. 부종이 늘면 부하를 낮추고 시기만으로 진행하지 않는다."},{"h":"의사에게 의뢰","t":"발열이나 상처 부위의 발적·열감·고름, 급격한 부종 증가, 종아리 통증과 부종(심부정맥혈전증 의심), 무릎 꺾임."}]},"keypoints":["최우선은 완전 신전의 획득","초기부터 대퇴사두근의 수의적 수축을 이끌어 냄","진행은 시기만이 아니라 부종·ROM·근력 기준으로 판단","경기 복귀는 기능 검사와 의사의 판단으로 결정","재손상 예방을 위해 착지·방향 전환 동작을 지도"],"case":{"text":"22세 남성, ACL 재건술 후 2주. 무릎에 경미한 부종이 있고 신전은 −10°. 대퇴사두근 수축이 약하고 신전 지연이 보인다. 본인은 빨리 달리고 싶다고 말한다.","answer":"이 시기의 최우선은 완전 신전과 대퇴사두근 조절의 획득이다. 달리기는 아직 이르다. 신전 제한이 남으면 보행 이상이나 무릎 앞쪽 통증으로 이어진다. 부종을 관리하고 기준을 충족한 뒤 단계적으로 진행한다."},"questions":[{"level":"기초","q":"ACL 재건술 후 재활에서 최우선 목표로 가장 적절한 것은?","options":["조기에 점프 시행","깊은 굴곡을 먼저 획득","완전 신전 회복","수술 직후부터 달리기"],"answer":2,"exp":"신전 제한이 남으면 보행 이상이나 무릎 앞쪽 통증으로 이어지므로 완전 신전을 되찾는 것이 최우선입니다."},{"level":"기초","q":"경기 복귀 검사를 시행하는 단계는?","options":["2단계(2~6주)","3단계(6~12주)","4단계(3~6개월)","5단계(6개월 이후)"],"answer":3,"exp":"경기 복귀 검사는 마지막 단계인 5단계(6개월 이후)에서 근력과 기능 검사 결과를 바탕으로 시행합니다."},{"level":"중급","q":"수술 후 초기에 평가하는 '신전 지연(extension lag)'은 어떤 상태인가?","options":["무릎의 전방 불안정성","능동 신전이 수동 신전에 못 미침","수동 굴곡의 제한","슬개골의 외측 편위"],"answer":1,"exp":"수동으로는 신전되지만 능동으로는 끝까지 펴지 못하는 상태로, 대퇴사두근의 근출력 저하를 나타냅니다."},{"level":"중급","q":"수술 후 재활 단계를 진행하는 판단으로 가장 적절한 것은?","options":["부종·ROM·근력 기준도 확인","수술 후 주수만으로 판단","통증이 늘어도 예정대로","본인 희망을 최우선"],"answer":0,"exp":"시기는 기준일 뿐입니다. 부종, 가동범위, 근력, 동작의 질 등의 기준을 충족했는지 확인하며 단계를 진행합니다."},{"level":"임상","q":"재건술 후 1주. 종아리의 통증과 부종, 열감이 갑자기 나타났다. 가장 적절한 대응은?","options":["마사지로 부종을 뺌","운동량을 늘림","신속히 의사에게 보고","온열치료 시행"],"answer":2,"exp":"심부정맥혈전증 가능성이 있는 징후입니다. 마사지는 피하고 신속히 의사에게 보고합니다."},{"level":"임상","q":"수술 후 4개월. 근력의 좌우 차이가 크고 착지 시 무릎이 안쪽으로 무너진다. 이 시점의 대응으로 가장 적절한 것은?","options":["즉시 시합에 복귀","근력 강화와 착지 동작 교정 지속","재활 종료","보조기만으로 복귀"],"answer":1,"exp":"근력의 좌우 차이와 니인은 재손상의 위험 요인입니다. 근력 강화와 동작 교정을 계속하고 기준을 충족한 뒤 복귀를 검토합니다."}],"seccion":"질환·외상과 재활","grupo":"스포츠·힘줄·근육","icono":"🏃","mapa":"img/mapas/t30.jpg","fichas":[],"secuencias":[]},"31":{"id":31,"title":"골관절염","lead":"골관절염은 관절 연골의 변성을 중심으로 통증과 기능 저하가 서서히 진행되는 질환입니다. 무릎과 고관절에 많으며 운동치료와 환자 교육이 보존치료의 토대입니다.","sheet":{"kind":"condition","items":[{"h":"병태","t":"관절 연골의 변성·마모를 중심으로 골극 형성, 연골하골 경화, 활막염을 동반한다. 무릎은 내측형이 많고, 고관절은 비구 이형성증에 의한 이차성도 많다."},{"h":"주요 증상","t":"동작 시작 시 통증, 일어서기나 계단 오르내리기 시 통증, 뻣뻣함, 관절 삼출, 가동범위 제한. 진행하면 변형(O자 다리 등)이나 보행 장애가 두드러진다."},{"h":"평가 포인트","t":"통증 부위와 유발 요인, ROM(무릎 신전 제한, 고관절 내회전 제한 등), 근력, 보행(외측 동요, 트렌델렌버그 징후), ADL."},{"h":"중재 흐름","t":"환자 교육, 운동치료(대퇴사두근·고관절 외전근 강화, ROM 유지), 유산소 운동, 체중 관리, 지팡이나 깔창 등 보조기구. 보존치료가 어려우면 수술을 검토한다."},{"h":"주의사항·금기","t":"염증이나 삼출이 심한 시기에는 부하를 낮춘다. 다음 날까지 통증이 남는 부하는 과하다고 본다. 지팡이는 원칙적으로 환측의 반대 손으로 잡는다."},{"h":"의사에게 의뢰","t":"갑작스러운 심한 부종과 열감(감염이나 가성통풍 의심), 발열, 야간통 악화, 갑작스러운 보행 곤란, 낙상 후 심한 통증."}]},"keypoints":["무릎 OA는 내측형이 많고 O자 다리 변형을 잘 동반함","고관절 OA는 비구 이형성증에 의한 이차성도 많음","운동치료와 환자 교육이 보존치료의 중심","지팡이는 환측의 반대 손으로 잡음","다음 날까지 통증이 남는 부하는 재검토함"],"case":{"text":"70세 여성. 몇 년 전부터 오른쪽 무릎 통증이 있으며 일어서기 시작할 때와 계단에서 아프다. O자 다리 변형, 무릎 신전 제한, 보행 시 무릎의 외측 동요(lateral thrust)가 보인다.","answer":"내측형 무릎 골관절염을 생각한다. 환자 교육, 대퇴사두근·고관절 주위근 강화, ROM 유지, 체중 관리를 시행하고 필요하면 왼손 지팡이 사용을 검토한다. 갑작스러운 열감이나 부종이 있으면 의사에게 의뢰한다."},"questions":[{"level":"기초","q":"무릎 골관절염에서 가장 흔한 유형은?","options":["외측형(X자 다리)","내측형(O자 다리)","슬개대퇴관절만","경비관절형"],"answer":1,"exp":"무릎 골관절염은 내측형이 많으며 O자 다리(내반) 변형을 잘 동반하는 것이 특징입니다."},{"level":"기초","q":"골관절염의 전형적인 영상 소견은?","options":["관절 간격의 확대","성장판의 확대","골막 반응","골극 형성"],"answer":3,"exp":"관절 간격의 협소화, 골극 형성, 연골하골 경화 등이 골관절염의 전형적인 소견입니다."},{"level":"중급","q":"오른쪽 무릎 골관절염 환자에게 지팡이를 지도한다. 지팡이를 잡는 손으로 가장 적절한 것은?","options":["오른손","왼손","양손","어느 쪽이든 무방"],"answer":1,"exp":"지팡이는 원칙적으로 환측의 반대 손으로 잡고 환측 다리와 동시에 내디뎌 환측의 부담을 줄입니다."},{"level":"중급","q":"고관절 골관절염에서 중둔근 근력 저하가 있을 때 잘 나타나는 소견은?","options":["팔 떨어뜨리기 징후","라세그 징후","트렌델렌버그 징후","호만 징후"],"answer":2,"exp":"중둔근 근력 저하에서는 환측 한발서기 시 반대쪽 골반이 내려가는 트렌델렌버그 징후가 나타납니다."},{"level":"임상","q":"무릎 OA의 65세 남성. 운동치료 다음 날까지 통증과 부종이 심하게 남았다. 가장 적절한 대응은?","options":["부하를 더 올림","운동을 모두 중단","부하량을 낮춰 조정","안정만 지도"],"answer":2,"exp":"다음 날까지 남는 통증이나 부종은 부하 과다의 징후입니다. 중단이 아니라 양이나 강도를 조정해 계속합니다."},{"level":"임상","q":"무릎 OA 환자. 갑자기 무릎이 심하게 붓고 열감이 있으며 발열도 있다. 우선해야 할 대응은?","options":["의사에게 연락","운동치료 강화","온열치료 시행","스트레칭 지도"],"answer":0,"exp":"갑작스러운 부종·열감과 발열은 감염이나 가성통풍 등을 의심하는 징후입니다. 온열이나 운동은 삼가고 의사에게 연락합니다."}],"seccion":"질환·외상과 재활","grupo":"정형외과·외상","icono":"🦴","mapa":"img/mapas/t31.jpg","fichas":[],"secuencias":[]},"32":{"id":32,"title":"인공 고관절·인공 슬관절 치환술","lead":"인공관절 치환술은 손상된 관절면을 인공물로 바꿔 통증 감소와 기능 개선을 꾀하는 수술입니다. 수술법에 맞춘 동작 지도와 조기 이상이 회복의 핵심입니다.","sheet":{"kind":"condition","items":[{"h":"병태·수술법","t":"골관절염 등으로 손상된 관절면을 인공물로 바꿔 통증 감소와 기능 개선을 꾀하는 수술. THA는 접근법에 따라 탈구되기 쉬운 자세가 다르다."},{"h":"수술 후 과제","t":"통증, 부종, 가동범위 제한, 근력 저하, 보행 능력 저하. THA는 탈구 예방, TKA는 무릎 굴곡·신전 가동범위 획득이 주요 과제가 된다."},{"h":"평가 포인트","t":"상처와 부종, ROM, 근력(대퇴사두근·중둔근), 다리 길이 차이 호소, 보행 양상, 균형, ADL 동작. 체중부하 제한과 금기 자세는 의사 지시를 확인한다."},{"h":"중재 흐름","t":"수술 후 초기부터 발목 운동, 등척성 운동, 기립·보행 연습. ROM과 근력 훈련을 진행하고 보행 보조기구를 단계적으로 바꾸며 ADL과 퇴원 후 생활을 지도한다."},{"h":"주의사항·금기","t":"후방 접근 THA는 굴곡·내전·내회전, 전방 접근은 신전·내전·외회전의 복합 자세에 주의한다. TKA 후에는 비골신경 마비 징후에도 주의한다."},{"h":"의사에게 의뢰","t":"탈구 의심 급격한 통증과 다리 단축·회전, 종아리 부종과 통증, 갑작스러운 호흡곤란이나 흉통, 상처 발적·고름, 발열."}]},"keypoints":["THA의 탈구 자세는 접근법에 따라 다름","후방 접근에서는 굴곡·내전·내회전의 복합을 피함","발목 저측·배측굴곡 운동으로 혈전을 예방함","TKA는 굴곡·신전 가동범위의 조기 획득이 중요","체중부하량과 금기 자세는 반드시 의사 지시를 확인"],"case":{"text":"75세 여성. 고관절 골관절염으로 후방 접근 THA를 받은 수술 후 3일째. 보행기로 보행 연습 중 바닥의 물건을 주우려고 몸을 비틀며 깊이 숙이려 했다.","answer":"깊은 굴곡·내전·내회전의 복합은 후방 접근 THA의 탈구 자세이므로 즉시 제지한다. 리처 등 보조도구를 사용한 안전한 동작을 지도한다. 갑작스러운 통증이나 다리 단축·회전이 있으면 의사에게 의뢰한다."},"questions":[{"level":"기초","q":"후방 접근 THA 후 탈구되기 쉬운 자세는?","options":["신전·내전·외회전","굴곡·내전·내회전","굴곡·외전·외회전","신전·외전·내회전"],"answer":1,"exp":"후방 접근 THA에서는 고관절의 굴곡·내전·내회전 복합 자세에서 탈구되기 쉽습니다."},{"level":"기초","q":"인공 슬관절 치환술(TKA)의 주요 목적은?","options":["뼈 성장 촉진","인대 재건","신경 복구","통증 감소와 기능 개선"],"answer":3,"exp":"TKA는 손상된 관절면을 인공물로 바꿔 통증 감소와 보행 등의 기능 개선을 목적으로 시행합니다."},{"level":"중급","q":"수술 후 초기 심부정맥혈전증 예방으로 지도하는 운동은?","options":["목의 회전 운동","손가락 굽힘·폄 운동","발목 저측·배측굴곡 운동","깊은 스쿼트"],"answer":2,"exp":"발목 저측·배측굴곡 운동은 하퇴 근육 펌프 작용으로 정맥 환류를 촉진해 혈전 예방에 도움이 됩니다."},{"level":"중급","q":"TKA 후 주의해야 할 신경 마비는?","options":["비골신경 마비","정중신경 마비","안면신경 마비","요골신경 마비"],"answer":0,"exp":"TKA 후 비골두 부근의 압박 등으로 비골신경 마비가 생길 수 있어 하수족이나 저림에 주의합니다."},{"level":"임상","q":"후방 접근 THA 수술 후 5일째 환자가 낮은 의자에 앉아 다리를 꼬려고 한다. 가장 적절한 대응은?","options":["그대로 지켜봄","높은 의자로 바꾸고 다리 꼬기 피함","다리 꼬기 연습 권유","깊이 숙이는 연습 시행"],"answer":1,"exp":"낮은 의자에서의 깊은 굴곡이나 다리 꼬기(내전·내회전)는 탈구 자세입니다. 좌면이 높은 의자를 쓰고 다리를 꼬지 않도록 지도합니다."},{"level":"임상","q":"TKA 수술 후 2일째 환자가 보행 연습 중 갑작스러운 호흡곤란과 흉통을 호소했다. 가장 우선해야 할 대응은?","options":["보행 연습 계속","호흡 연습 지도","즉시 중단하고 의사에게 보고","쉬게 하고 경과 관찰"],"answer":2,"exp":"폐색전증을 의심하는 징후입니다. 운동을 즉시 중단하고 의사에게 보고합니다."}],"seccion":"질환·외상과 재활","grupo":"정형외과·외상","icono":"🦴","mapa":"img/mapas/t32.jpg","fichas":[],"secuencias":[]},"33":{"id":33,"title":"흔한 골절","lead":"노인에서는 골다공증을 배경으로 낙상에 의한 골절이 많이 발생합니다. 골유합 단계와 의사의 허용 범위를 확인하면서 폐용을 막고 기능을 되찾습니다.","sheet":{"kind":"condition","items":[{"h":"병태","t":"노인은 골다공증을 배경으로 낙상 시 대퇴골 근위부, 요골 원위부, 상완골 근위부, 척추 추체 골절이 잘 생긴다. 젊은 층에서는 고에너지 외상이 많다."},{"h":"주요 증상","t":"손상 부위의 통증, 부종, 변형, 피하출혈, 기능 장애. 대퇴골 근위부 골절은 일어서지 못하고 환측 하지 단축과 외회전, 압박골절은 움직일 때 등 통증."},{"h":"평가 포인트","t":"골절 유형과 고정법, 체중부하·가동범위 허용 범위를 의사에게 확인. 통증, 부종, 인접 관절 ROM, 근력, 신경·순환, 손상 전 ADL과 인지 기능."},{"h":"중재 흐름","t":"고정기에는 고정 외 관절을 움직여 부종과 구축을 예방한다. 골유합과 의사 허락에 따라 ROM·체중부하·근력 훈련을 진행한다. 노인은 조기 이상과 낙상 예방."},{"h":"주의사항·금기","t":"허용 범위를 넘는 체중부하나 ROM은 하지 않는다. 장기 와상에 의한 폐용, 폐렴, 욕창, 섬망에 주의. 요골 원위부 골절 후에는 손가락 뻣뻣함에 주의한다."},{"h":"의사에게 의뢰","t":"고정 내 심한 통증, 저림, 손가락 색 변화(순환 장애나 구획증후군 의심), 갑작스러운 통증 악화나 변형, 종아리 부종, 발열."}]},"keypoints":["노인은 골다공증을 배경으로 한 낙상 골절이 많음","체중부하와 ROM 허용 범위는 반드시 의사에게 확인","고정 중에도 고정 외 관절은 적극적으로 움직임","대퇴골 근위부 골절은 조기 이상으로 폐용을 막음","재골절 예방을 위해 낙상 예방과 골다공증 관리"],"case":{"text":"82세 여성. 집에서 넘어져 오른쪽 고관절 통증으로 일어서지 못하게 되었다. 오른쪽 하지는 단축·외회전 자세. 대퇴골 전자부 골절로 골접합술을 받고 수술 다음 날 재활이 처방되었다.","answer":"의사에게 체중부하 허용 범위를 확인하고 조기 이상과 보행 연습을 진행해 폐용·폐렴·섬망을 예방한다. 손상 전 ADL을 목표의 기준으로 삼고, 퇴원을 앞두고 낙상 예방과 골다공증 관리도 지도한다."},"questions":[{"level":"기초","q":"노인이 손을 짚고 넘어졌을 때 잘 생기는 골절은?","options":["주상골 골절","요골 원위부 골절","주두 골절","중수골 골절"],"answer":1,"exp":"노인이 손을 짚고 넘어지면 요골 원위부 골절이 대표적입니다. 원위 골편이 배측으로 전위된 것을 콜레스 골절이라고 합니다."},{"level":"기초","q":"대퇴골 근위부 골절에서 잘 나타나는 환측 하지의 자세는?","options":["환측 연장·내회전","변화 없음","환측 단축·외회전","환측 연장·외전"],"answer":2,"exp":"대퇴골 근위부 골절에서는 환측 하지의 단축과 외회전이 잘 나타나며 서기나 보행이 어려워집니다."},{"level":"중급","q":"골절 고정기에 시행하는 물리치료로 가장 적절한 것은?","options":["고정 부위의 강한 수동 ROM","허락 전 전체중부하 보행","골절부에 강한 마사지","고정 외 관절의 운동"],"answer":3,"exp":"고정기에는 골절부를 보호하면서 고정 외 관절을 움직여 부종·구축·근력 저하를 예방합니다."},{"level":"중급","q":"대퇴골 근위부 골절 수술 후 노인에게 조기 이상을 시행하는 주된 목적은?","options":["골절 유형 판정","폐용 증후군 예방","수술을 대신함","골유합을 불필요하게 함"],"answer":1,"exp":"노인은 와상이 계속되면 근력 저하, 폐렴, 욕창, 섬망 등 폐용이 진행되기 쉬우므로 조기 이상을 시행합니다."},{"level":"임상","q":"요골 원위부 골절로 석고 고정 중인 70세 여성. 손가락이 심하게 붓고 저림과 색 변화를 호소한다. 가장 적절한 대응은?","options":["손가락 운동 강화","온열치료 시행","신속히 의사에게 보고","다음 방문까지 관찰"],"answer":2,"exp":"고정 내 심한 부종, 저림, 색 변화는 순환 장애나 구획증후군을 의심하는 징후입니다. 신속히 의사에게 보고합니다."},{"level":"임상","q":"85세 여성. 요추 압박골절로 등 통증이 있으며 의사가 이상을 허락했다. 가장 적절한 대응은?","options":["허용 범위에서 이상 진행","와상을 유지하며 관찰","체간의 강한 굴곡 운동","무거운 물건 들기 연습"],"answer":0,"exp":"허용 범위에서 이상을 진행해 폐용을 막습니다. 압박골절에서는 체간의 강한 굴곡이나 무거운 물건 들기는 부담이 되므로 피합니다."}],"seccion":"질환·외상과 재활","grupo":"정형외과·외상","icono":"🦴","mapa":"img/mapas/t33.jpg","fichas":[],"secuencias":[]},"34":{"id":34,"title":"요통·추간판 탈출증","lead":"요통의 대부분은 원인을 특정할 수 없는 비특이적 요통이지만, 신경근 증상이나 중대한 질환을 감별하는 것이 중요합니다. 위험 신호를 배제하고 활동 유지를 지원합니다.","sheet":{"kind":"condition","items":[{"h":"병태","t":"요통의 대부분은 원인을 특정할 수 없는 비특이적 요통. 추간판 탈출증은 수핵이 섬유륜을 뚫고 돌출해 신경근을 압박한다. L4/5, L5/S1에 많다."},{"h":"주요 증상","t":"요통과 한쪽 하지 통증(좌골신경통), 저림, 전굴이나 앉은 자세에서 악화. 손상된 신경근에 따른 감각 저하, 근력 저하, 반사 저하."},{"h":"평가 포인트","t":"SLR 검사(상위 요추는 FNST), 피부분절, MMT(L5: 엄지발가락 배측굴곡, S1: 발목 저측굴곡), 건반사(S1: 아킬레스건 반사)."},{"h":"중재 흐름","t":"환자 교육으로 불안을 줄이고 가능한 범위에서 활동을 유지한다. 증상을 줄이는 자세나 운동을 찾고 체간·하지 운동치료와 단계적인 활동량 증가를 시행한다."},{"h":"주의사항·금기","t":"장기간 안정은 권하지 않는다. 하지 증상이 발끝으로 퍼지는 운동은 중단한다. 공포-회피 등 심리사회적 요인이 만성화에 관여한다."},{"h":"의사에게 의뢰","t":"방광·직장 장애나 안장 마비(마미 증후군), 진행하는 근력 저하, 발열, 원인 불명의 체중 감소, 암 병력, 외상 후 심한 통증."}]},"keypoints":["요통의 대부분은 비특이적 요통","L4/5 탈출증에서는 L5 신경근이 잘 손상됨","SLR 검사는 하위 요추의 신경근 증상을 평가","장기 안정보다 가능한 범위에서 활동 유지","방광·직장 장애·안장 마비는 응급으로 의사에게"],"case":{"text":"35세 남성, 사무직. 무거운 물건을 든 후부터 요통과 왼쪽 하퇴 외측~발등 저림이 생겼다. 왼쪽 SLR에서 하지 통증이 재현되고 왼쪽 엄지발가락 배측굴곡 근력 저하가 있다. 배뇨 장애는 없다.","answer":"L4/5 추간판 탈출증에 의한 L5 신경근병증을 의심한다. 교육과 가능한 범위의 활동 유지, 증상을 악화시키지 않는 운동을 시행하고 근력 저하 추이를 재평가한다. 마비 진행이나 방광·직장 장애가 생기면 즉시 의사에게."},"questions":[{"level":"기초","q":"요추 추간판 탈출증이 가장 많은 고위는?","options":["L1/2","L2/3","L3/4","L4/5"],"answer":3,"exp":"요추 추간판 탈출증은 L4/5에 가장 많고 다음으로 L5/S1에 많습니다."},{"level":"기초","q":"추간판 탈출증에서 주로 돌출되는 조직은?","options":["수핵","황색인대","추궁","극돌기"],"answer":0,"exp":"추간판 중심부의 수핵이 섬유륜의 균열을 통해 돌출해 신경근 등을 압박합니다."},{"level":"중급","q":"L5 신경근병증에서 근력 저하가 잘 나타나는 운동은?","options":["발목 저측굴곡","엄지발가락 배측굴곡","무릎 신전","고관절 굴곡"],"answer":1,"exp":"L5 신경근은 장무지신근을 지배하며 손상되면 엄지발가락 배측굴곡 근력이 저하됩니다. 발목 저측굴곡은 S1입니다."},{"level":"중급","q":"S1 신경근병증에서 잘 저하되는 건반사는?","options":["슬개건 반사","이두근 반사","아킬레스건 반사","상완요골근 반사"],"answer":2,"exp":"아킬레스건 반사는 주로 S1이 관여합니다. 슬개건 반사는 주로 L4 평가에 사용합니다."},{"level":"임상","q":"급성 요통의 40세 여성. 레드 플래그는 없다. 가장 적절한 지도는?","options":["2주간 절대 안정","통증이 없어질 때까지 휴직","모든 운동 금지","가능한 범위에서 활동 유지"],"answer":3,"exp":"레드 플래그가 없는 급성 요통에서는 장기 안정보다 가능한 범위에서 일상 활동을 유지하는 것이 권장됩니다."},{"level":"임상","q":"요통과 양 하지 저림이 있는 환자가 소변이 잘 안 나오고 항문 주위 감각이 둔하다고 호소했다. 가장 적절한 대응은?","options":["운동치료 계속","견인치료 시행","즉시 의사에게 연락","다음 방문까지 관찰"],"answer":2,"exp":"방광·직장 장애와 안장 마비는 마미 증후군을 의심하는 응급 징후입니다. 즉시 의사에게 연락합니다."}],"seccion":"질환·외상과 재활","grupo":"척추","icono":"🧍","mapa":"img/mapas/t34.jpg","fichas":[],"secuencias":[]},"35":{"id":35,"title":"목 통증","lead":"목 통증의 대부분은 비특이적 통증이지만, 신경근병증이나 척수병증을 감별하는 것이 중요합니다. 위험 징후를 확인한 뒤 운동치료와 자세 조정을 시행합니다.","sheet":{"kind":"condition","items":[{"h":"병태","t":"비특이적 목 통증이 많다. 추간판이나 골극으로 신경근이 압박되면 신경근병증, 척수가 압박되면 척수병증이 된다. 외상으로는 편타성 손상(외상성 경부 증후군)이 있다."},{"h":"주요 증상","t":"목 통증, 가동범위 제한, 견갑부 통증. 신경근병증은 한쪽 상지 통증·저림. 척수병증은 양손 저림, 손 미세동작 저하(젓가락·단추), 보행 장애."},{"h":"평가 포인트","t":"경부 ROM, 스펄링 검사, 피부분절, MMT, 건반사(C6: 상완요골근, C7: 삼두근), 호프만 반사, 보행, 자세."},{"h":"중재 흐름","t":"교육과 활동 유지, 경부·견갑대 운동치료(심부 목굴곡근 운동 등), 자세와 작업 환경 조정. 도수치료는 평가에 근거해 신중하게 시행한다."},{"h":"주의사항·금기","t":"척수병증이 의심되면 경부에 대한 강한 수기를 피한다. 어지럼, 복시, 구음장애 등이 나타나는 수기나 운동은 즉시 중단한다."},{"h":"의사에게 의뢰","t":"양손 저림과 미세동작 저하·보행 장애, 진행하는 마비, 외상 후 통증, 발열, 어지럼·구음장애·삼킴장애, 원인 불명의 체중 감소."}]},"keypoints":["목 통증의 대부분은 비특이적 목 통증","스펄링 검사는 신경근병증 평가에 사용","양손 미세동작 저하와 보행 장애는 척수병증 의심","심부 목굴곡근과 견갑대 운동치료를 시행","척수병증 의심 시 경부에 대한 강한 수기를 피함"],"case":{"text":"45세 여성, 사무직. 1개월 전부터 목 통증과 오른쪽 엄지손가락 저림이 있다. 목을 오른쪽으로 신전·측굴하면 오른쪽 상지로 방사통이 나타난다. 오른쪽 상완요골근 반사 저하가 있다.","answer":"오른쪽 C6 신경근병증을 생각한다. 증상을 악화시키지 않는 범위에서 교육, 운동치료, 자세·작업 환경 조정을 시행한다. 근력 저하 진행이나 양손 저림·보행 장애 등 척수병증 징후가 있으면 의사에게 의뢰한다."},"questions":[{"level":"기초","q":"경추성 척수병증을 시사하는 증상은?","options":["한쪽 견갑부 통증만","양손 미세동작 저하","목 근육 뭉침","두통만"],"answer":1,"exp":"척수 압박에서는 양손 저림이나 미세동작 저하(젓가락·단추 조작 곤란), 보행 장애가 나타납니다."},{"level":"기초","q":"심부 목굴곡근 운동으로 대표적인 것은?","options":["목의 강한 신전 운동","목의 빠른 회전","턱을 당기는 두경부 굴곡","어깨 으쓱하기 운동"],"answer":2,"exp":"턱을 가볍게 당기는 두경부 굴곡 운동은 긴목근 등 심부 목굴곡근의 활동을 높이는 대표적인 운동입니다."},{"level":"중급","q":"스펄링 검사의 양성 소견은?","options":["목 신전·측굴 시 상지 방사통","목 굴곡 시 등에 전기 통증","어깨 외전 시 증상 감소","손목 굴곡 시 저림 발생"],"answer":0,"exp":"목을 환측으로 신전·측굴하고 축압을 가해 상지에 방사통이나 저림이 나타나면 신경근병증을 의심합니다."},{"level":"중급","q":"C7 신경근병증에서 잘 저하되는 건반사는?","options":["이두근 반사","상완요골근 반사","삼두근 반사","슬개건 반사"],"answer":2,"exp":"삼두근 반사는 주로 C7, 이두근 반사는 C5, 상완요골근 반사는 C6 평가에 사용합니다."},{"level":"임상","q":"60세 남성. 최근 단추 채우기가 어렵고 보행이 비틀거린다. 호프만 반사 양성. 가장 의심되는 병태는?","options":["비특이적 목 통증","흉곽출구 증후군","수근관 증후군","경추성 척수병증"],"answer":3,"exp":"미세동작 저하, 보행 장애, 병적 반사는 척수병증을 시사합니다. 경부에 대한 강한 수기는 피하고 의사의 평가로 연결합니다."},{"level":"임상","q":"목 통증 환자. 목 회전 운동 중 어지럼과 복시가 나타났다. 가장 적절한 대응은?","options":["운동을 계속해 적응","즉시 중단하고 의사에게","가동범위를 더 넓힘","온열치료로 전환"],"answer":1,"exp":"어지럼이나 복시는 혈관성·신경학적 문제 가능성이 있는 징후입니다. 즉시 중단하고 의사의 평가로 연결합니다."}],"seccion":"질환·외상과 재활","grupo":"척추","icono":"🧍","mapa":"img/mapas/t35.jpg","fichas":[],"secuencias":[]},"36":{"id":36,"title":"척추측만증","lead":"척추측만증은 척추가 옆으로 휘고 추체 회전을 동반하는 3차원적 변형입니다. 성장기에 진행하기 쉬워 조기 발견과 정기적인 경과 관찰이 중요합니다.","sheet":{"kind":"condition","items":[{"h":"병태","t":"척추가 전두면에서 옆으로 휘고 추체 회전을 동반하는 3차원적 변형. 원인 불명의 특발성이 많고 사춘기 여아에 많다. 기능성 측만과는 구별한다."},{"h":"주요 증상","t":"대부분 통증이 적고 어깨 높이, 견갑골, 허리선의 좌우 차이나 전굴 시 늑골 융기·요부 융기로 발견된다. 고도가 되면 호흡 기능에 영향을 준다."},{"h":"평가 포인트","t":"선 자세에서 어깨·골반·허리선의 대칭성, 전방 굴곡 검사, 다리 길이 차이(기능성과 감별), 유연성, 호흡. 만곡 정도는 X선 콥 각으로 의사가 평가한다."},{"h":"중재 흐름","t":"경과 관찰·보조기 치료·수술 방침은 성장 단계와 콥 각을 바탕으로 의사가 정한다. 물리치료는 체간 운동치료, 호흡 연습, 보조기 착용 지속을 지원한다."},{"h":"주의사항·금기","t":"성장기는 진행하기 쉬워 정기적인 경과 관찰이 중요하다. 운동치료만으로 교정된다고 설명하지 않는다. 보조기 착용 시간은 의사의 지시에 따른다."},{"h":"의사에게 의뢰","t":"심한 통증이나 야간통, 저림·근력 저하 등 신경 증상, 급속한 진행, 비전형적인 만곡(좌측 볼록 흉추 만곡 등), 발열."}]},"keypoints":["척추측만증은 추체 회전을 동반하는 3차원적 변형","대표는 사춘기 여아에 많은 특발성 척추측만증","전방 굴곡 검사로 늑골 융기를 확인","성장기는 진행하기 쉬워 정기적 경과 관찰이 중요","통증이나 신경 증상을 동반한 측만은 의사에게 의뢰"],"case":{"text":"13세 여아. 학교 건강검진에서 측만을 지적받았다. 선 자세에서 오른쪽 어깨가 높고 전굴 시 오른쪽 등에 늑골 융기가 보인다. 통증이나 신경 증상은 없다. 정형외과에서 보조기 치료가 처방되었다.","answer":"청소년 특발성 척추측만증을 생각한다. 물리치료에서는 보조기 착용 지속을 지원하고 체간 운동치료와 호흡 연습을 시행한다. 운동만으로 낫는다고 설명하지 않는다. 통증이나 신경 증상, 급격한 진행이 있으면 의사에게."},"questions":[{"level":"기초","q":"척추측만증 선별에서 전방 굴곡 검사 시 관찰하는 소견은?","options":["무릎 과신전","늑골 융기","발의 편평화","경추 전만 증가"],"answer":1,"exp":"전방 굴곡 검사에서는 등을 뒤에서 관찰해 추체 회전에 따른 늑골 융기나 요부 융기 유무를 확인합니다."},{"level":"기초","q":"측만 만곡의 정도를 평가하는 지표는?","options":["Q각","경간각","콥 각","대퇴경골각"],"answer":2,"exp":"측만의 정도는 X선 영상에서 만곡 상하단 추체로부터 각도를 측정하는 콥 각으로 평가합니다."},{"level":"중급","q":"특발성 척추측만증의 특징으로 옳은 것은?","options":["고령 남성에 많음","사춘기 여아에 많음","반드시 심한 통증 동반","전두면만의 변형"],"answer":1,"exp":"특발성 척추측만증은 사춘기 여아에 많고 대부분 통증이 적습니다. 추체 회전을 동반하는 3차원적 변형입니다."},{"level":"중급","q":"기능성 측만의 원인으로 생각할 수 있는 것은?","options":["추체의 선천 기형","신경근육 질환","추체의 회전 변형","다리 길이 차이"],"answer":3,"exp":"다리 길이 차이나 통증 회피 자세 등으로 생기는 기능성 측만은 원인을 없애면 개선되며 구조성 측만과 구별합니다."},{"level":"임상","q":"보조기 치료 중인 14세 여아. 보조기가 꽉 끼어 임의로 착용 시간을 줄이고 있다. 물리치료사의 대응으로 가장 적절한 것은?","options":["보조기 중단, 운동만","착용 지속을 돕고 의사와 상의","착용 시간을 더 줄임","문제없다고 전함"],"answer":1,"exp":"착용 시간은 의사의 지시를 따르는 것이 중요합니다. 불편한 점을 듣고 지속을 지원하며 보조기 적합은 의사나 의지보조기기사와 상의합니다."},{"level":"임상","q":"12세 남아. 측만이 있으며 밤에 심한 등 통증으로 잠에서 깬다. 가장 적절한 대응은?","options":["스트레칭 지도","경과 관찰","운동량 증가","의사의 평가로 연결"],"answer":3,"exp":"심한 통증이나 야간통을 동반한 측만은 종양 등 다른 원인이 숨어 있을 수 있으므로 의사의 평가로 연결합니다."}],"seccion":"질환·외상과 재활","grupo":"척추","icono":"🧍","mapa":"img/mapas/t36.jpg","fichas":[],"secuencias":[]},"37":{"id":37,"title":"뇌졸중","lead":"뇌혈관이 막히거나 터져 신경 증상이 갑자기 나타나는 질환입니다. 조기 거동과 과제 지향적 반복 훈련이 기능 회복의 토대가 됩니다.","sheet":{"kind":"condition","items":[{"h":"병태","t":"뇌경색(죽상혈전성·심인성 색전·열공성), 뇌출혈, 지주막하출혈로 크게 나뉩니다. 병변의 부위와 크기에 따라 증상이 다릅니다."},{"h":"주요 증상","t":"편마비, 감각장애, 경직, 실어증, 편측 무시, 구음장애, 삼킴장애, 주의력 장애 등 고위뇌기능장애가 나타납니다."},{"h":"평가 포인트","t":"브룬스트롬 단계·SIAS·FMA로 마비를, MAS로 경직을, BBS로 균형을, FIM으로 ADL을 평가합니다."},{"h":"단계별 재활","t":"급성기는 위험 관리하의 조기 거동, 회복기는 과제 지향 훈련과 보행 훈련, 만성기는 활동과 참여의 유지를 꾀합니다."},{"h":"주의사항·금기","t":"급성기에는 혈압·의식·신경 증상의 변동에 주의합니다. 마비측 상지를 당기거나 부적절하게 보조하면 어깨 통증을 유발합니다."},{"h":"의사에게 의뢰","t":"의식 저하, 마비나 구음장애의 급격한 악화, 심한 두통, 구토, 혈압 급변이 보이면 즉시 보고합니다."}]},"keypoints":["거동 시작·중지는 의사 지시와 중지 기준에 따름","마비측 어깨는 당기지 말고 자세 잡기로 보호","편측 무시에는 무시측 주의 유도 과제와 환경 조정","과제 지향적 반복 훈련이 기능 회복의 기본","보조기는 보행 능력과 목표에 맞춰 단계적으로 검토"],"case":{"text":"68세 남성, 우측 중대뇌동맥 영역 뇌경색 발병 3주. 좌측 편마비(하지 브룬스트롬 단계 III). 휠체어로 왼쪽 물건에 자주 부딪히고, 식사 때 왼쪽 음식을 남김.","answer":"해설: 좌측 편측 무시가 의심되며 낙상·충돌 위험이 높은 상태입니다. 왼쪽으로 주의를 유도하는 과제와 환경 조정을 하고 감독하에 훈련합니다. 무시가 남아 있는 동안 독립 이동을 허용하지 않습니다."},"questions":[{"level":"기초","q":"중대뇌동맥 영역 뇌경색에서 전형적으로 나타나는 편마비 분포는?","options":["하지 우세 편마비","상지·얼굴 우세 편마비","양하지 대마비","좌우 대칭 사지마비"],"answer":1,"exp":"중대뇌동맥은 대뇌반구 외측면을 관류하며 상지·얼굴 운동영역을 포함하므로 상지·얼굴 우세가 됩니다. 하지 우세는 전대뇌동맥 영역입니다."},{"level":"기초","q":"좌측 편측 무시가 생기기 쉬운 병변 부위는?","options":["좌측 전두엽","소뇌","우측 두정엽","뇌간"],"answer":2,"exp":"좌측 편측 무시는 우측 대뇌반구, 특히 우측 두정엽 병변에서 생기기 쉬운 증상입니다."},{"level":"중급","q":"브룬스트롬 회복 단계에서 공동운동이 수의적으로 충분히 나타나는 단계는?","options":["단계 II","단계 IV","단계 VI","단계 III"],"answer":3,"exp":"단계 III은 공동운동이 수의적으로 충분히 나타나는 단계입니다. II는 연합반응과 공동운동이 나타나기 시작하는 단계, IV는 분리운동이 일부 가능한 단계입니다."},{"level":"중급","q":"뇌졸중 후 경직 평가에 사용하는 척도는?","options":["MAS","FIM","BBS","MMSE"],"answer":0,"exp":"MAS는 수동운동 시 저항으로 근긴장도를 등급화합니다. FIM은 ADL, BBS는 균형, MMSE는 인지기능 평가입니다."},{"level":"임상","q":"뇌졸중 후 마비측 어깨에 아탈구가 있고, 이동 보조 시 어깨 통증을 호소한다. 가장 적절한 대응은?","options":["마비측 팔을 당겨 보조","어깨를 지지하고 팔을 당기지 않음","통증이 없어질 때까지 완전 고정","어깨의 강한 수동 신장을 매일 시행"],"answer":1,"exp":"아탈구된 어깨는 견인하면 통증과 손상을 유발합니다. 보조기와 자세 잡기로 보호하고 통증 없는 범위에서 가동범위를 유지합니다."},{"level":"임상","q":"급성기 뇌경색 환자. 거동 훈련 중 구음장애와 마비가 갑자기 악화되었다. 가장 적절한 대응은?","options":["그대로 보행 훈련을 계속","휴식 후 훈련을 재개","중지하고 즉시 의사에게 보고","다음 날 재평가"],"answer":2,"exp":"신경 증상의 급격한 악화는 병변 확대나 재발 가능성이 있습니다. 훈련을 중지해 안전을 확보하고 즉시 의사에게 보고합니다."}],"seccion":"질환·외상과 재활","grupo":"신경계","icono":"🧠","mapa":"img/mapas/t37.jpg","fichas":[],"secuencias":[]},"38":{"id":38,"title":"파킨슨병","lead":"중뇌 흑질의 도파민 신경세포가 변성되어 운동 증상이 나타나는 진행성 신경퇴행성 질환입니다. 외부 단서를 활용한 운동과 낙상 예방이 중요합니다.","sheet":{"kind":"condition","items":[{"h":"병태","t":"중뇌 흑질의 도파민 신경세포가 변성되어 선조체의 도파민이 부족해지고 운동 조절이 장애됩니다. 증상은 서서히 진행합니다."},{"h":"주요 증상","t":"안정시 떨림, 근강직, 무동·운동완서, 자세반사장애. 동결보행, 종종걸음, 앞굽은 자세와 변비 등 비운동 증상도 나타납니다."},{"h":"평가 포인트","t":"호엔-야 단계, MDS-UPDRS, BBS, TUG, 보행 속도, 동결보행 유무, 낙상력, 약효의 일중 변동을 확인합니다."},{"h":"중재 흐름","t":"초기에는 전신 운동과 체력 유지, 진행에 따라 시각·청각 단서를 이용한 보행 훈련, 균형 훈련, 낙상 예방과 환경 조정을 합니다."},{"h":"주의사항·금기","t":"약효 변동(웨어링 오프, 이상운동증)에 맞춰 훈련 시간을 조정합니다. 기립성 저혈압에도 주의합니다."},{"h":"의사에게 의뢰","t":"증상의 급격한 악화, 약효 시간 단축, 환각, 반복 낙상, 삼킴장애 진행, 고열과 심한 근강직이 보이면 보고합니다."}]},"keypoints":["훈련은 약효가 있는 ‘온’ 시간대에 설정","바닥 선·리듬음 등 외부 단서로 동결보행 경감","크고 천천히 움직이도록 의식하며 반복 훈련","방향 전환과 이중과제 상황은 낙상 위험이 높음","체간 신전·회전 운동으로 앞굽은 자세에 대응"],"case":{"text":"72세 여성, 파킨슨병(호엔-야 III단계). 좁은 출입구나 방향 전환 시 발이 얼어붙어 집에서 낙상을 반복함. 약효가 떨어지는 시간대에 증상이 심함.","answer":"해설: 동결보행과 자세반사장애로 낙상 위험이 높은 상태입니다. 온 시간대에 시각·청각 단서를 이용한 보행과 방향 전환을 훈련하고 주거 환경을 정비합니다. 약 조절은 의사와 상의하며 임의로 바꾸지 않게 합니다."},"questions":[{"level":"기초","q":"파킨슨병에서 주로 변성되는 부위는?","options":["소뇌","중뇌 흑질","척수 전각","대뇌피질 운동영역"],"answer":1,"exp":"중뇌 흑질의 도파민 신경세포가 변성되어 선조체의 도파민이 감소하면서 운동 증상이 나타납니다."},{"level":"기초","q":"파킨슨병 떨림의 특징으로 옳은 것은?","options":["의도 떨림","동작 시 심해짐","안정시 떨림","수면 중에도 지속"],"answer":2,"exp":"안정 시에 나타나고 수의운동을 하면 줄어드는 것이 특징입니다. 의도 떨림은 소뇌 장애에서 나타납니다."},{"level":"중급","q":"호엔-야 단계 III의 특징은?","options":["자세반사장애가 출현","한쪽 증상만 있음","휠체어·와상 상태","양측성이며 자세반사 정상"],"answer":0,"exp":"III단계는 양측성 증상에 자세반사장애가 더해지는 단계입니다. I단계는 편측성, II단계는 양측성이며 자세반사 정상, V단계는 휠체어·와상 상태입니다."},{"level":"중급","q":"동결보행 경감에 사용하는 방법은?","options":["눈을 감고 걷기","보행 속도를 갑자기 높이기","좁은 통로를 반복해 걷기","바닥 선 등 시각 단서"],"answer":3,"exp":"바닥 선이나 메트로놈 소리 같은 외부 단서는 동결보행 경감과 보폭 개선에 사용됩니다."},{"level":"임상","q":"파킨슨병 환자. 아침과 점심에 약을 복용하며, 오후 늦게 동작이 느려져 훈련이 진행되지 않는다. 가장 적절한 대응은?","options":["오후 훈련량을 늘림","훈련을 온 시간대에 맞춤","복용량을 본인이 조절하게 함","물리치료를 중단"],"answer":1,"exp":"약효 변동(웨어링 오프)이 의심됩니다. 훈련은 약효가 있는 시간대에 설정하고 변동은 의사에게 보고합니다. 약 조절은 의사가 합니다."},{"level":"임상","q":"약을 갑자기 중단한 파킨슨병 환자에게 고열, 현저한 근강직, 의식장애가 나타났다. 가장 적절한 대응은?","options":["가벼운 운동으로 경과 관찰","스트레칭을 강화","훈련 중지 후 즉시 의사에게","다음 날 훈련에서 재평가"],"answer":2,"exp":"약 급중단 후의 고열·근강직·의식장애는 악성 증후군이 의심되어 응급 대응이 필요합니다. 즉시 의사에게 보고합니다."}],"seccion":"질환·외상과 재활","grupo":"신경계","icono":"🧠","mapa":"img/mapas/t38.jpg","fichas":[],"secuencias":[]},"39":{"id":39,"title":"다발성 경화증","lead":"중추신경의 수초가 염증으로 손상되며 재발과 관해를 반복하는 경우가 많은 질환입니다. 피로와 체온 상승을 고려해 운동량을 조절하는 것이 핵심입니다.","sheet":{"kind":"condition","items":[{"h":"병태","t":"뇌·척수·시신경에 탈수초 병변이 시간적·공간적으로 다발하는 자가면역 질환입니다. 젊은 성인, 특히 여성에게 많다고 알려져 있습니다."},{"h":"주요 증상","t":"시력장애(시신경염), 근력 저하, 감각장애, 경직, 운동실조, 쉽게 피로함, 방광·직장 장애, 레르미트 징후 등이 나타납니다."},{"h":"평가 포인트","t":"EDSS, MMT, MAS, 균형, 보행 능력, 피로 정도를 평가합니다. 증상의 일중 변동과 체온에 따른 변화도 확인합니다."},{"h":"중재 흐름","t":"재발기에는 안정과 부드러운 가동범위 운동, 관해기에는 유산소 운동·근력 강화·균형 훈련을 피로에 맞춰 단계적으로 시행합니다."},{"h":"주의사항·금기","t":"체온 상승으로 증상이 일시적으로 악화되므로(우토프 현상) 고온 환경과 과부하를 피하고 휴식을 넣어 시행합니다."},{"h":"의사에게 의뢰","t":"새로운 시력 저하, 저림이나 마비의 출현·급격한 악화가 24시간 이상 지속되면 재발 가능성이 있어 의사에게 보고합니다."}]},"keypoints":["운동은 서늘한 환경에서 하고 체온 상승을 피함","피로가 심한 날은 운동량을 줄이고 휴식을 넣음","재발기와 관해기에 따라 운동 내용을 전환","에너지 보존 방법을 ADL 지도에 반영","경직에는 스트레칭과 자세 잡기로 대응"],"case":{"text":"32세 여성, 다발성 경화증(관해기). 실온이 높은 훈련실에서 운동 중 하지 힘 빠짐과 저림이 심해졌으나, 쉬면서 몸을 식히자 30분 정도 후 원래대로 돌아옴.","answer":"해설: 체온 상승에 따른 일시적 증상 악화(우토프 현상)로 생각됩니다. 서늘한 환경에서 휴식을 넣고 운동 강도를 조절합니다. 휴식해도 호전되지 않고 증상이 지속되면 재발을 의심하여 의사에게 보고합니다."},"questions":[{"level":"기초","q":"다발성 경화증에서 주로 손상되는 구조는?","options":["말초신경의 수초","중추신경의 수초","신경근 접합부","골격근 섬유"],"answer":1,"exp":"뇌·척수·시신경 등 중추신경의 수초가 손상됩니다. 말초신경의 탈수초는 길랭-바레 증후군 등에서 나타납니다."},{"level":"기초","q":"체온 상승으로 증상이 일시적으로 악화되는 현상은?","options":["레르미트 징후","롬베르크 징후","바빈스키 반사","우토프 현상"],"answer":3,"exp":"우토프 현상은 체온 상승으로 증상이 일시적으로 악화되는 현상입니다. 레르미트 징후는 목을 앞으로 굽히면 등에서 사지로 전기 같은 통증이 퍼지는 징후입니다."},{"level":"중급","q":"다발성 경화증 재발기의 물리치료로 가장 적절한 것은?","options":["고강도 근력 강화 운동","장시간 유산소 운동","부드러운 관절가동범위 운동","고온 환경에서의 운동"],"answer":2,"exp":"재발기는 염증이 활동적이므로 과부하를 피하고 부드러운 가동범위 운동과 자세 잡기를 중심으로 합니다."},{"level":"중급","q":"목을 앞으로 굽히면 등에서 사지로 전기 같은 통증이 퍼지는 징후는?","options":["레르미트 징후","우토프 현상","호프만 반사","트렌델렌버그 징후"],"answer":0,"exp":"레르미트 징후는 경수 병변에서 생기기 쉬우며 다발성 경화증에서 나타나는 대표적인 징후입니다."},{"level":"임상","q":"다발성 경화증 환자. 저녁이 되면 피로가 심해져 보행이 불안정해진다. 가장 적절한 지도는?","options":["저녁에 운동량을 늘림","활동을 컨디션 좋은 시간에 배분","휴식 없이 계속하게 함","따뜻한 방에서 운동"],"answer":1,"exp":"쉽게 피로함에는 에너지 보존의 관점으로 대응하며, 활동을 컨디션이 좋은 시간대에 배분하고 휴식을 계획적으로 넣습니다."},{"level":"임상","q":"관해기 다발성 경화증 환자. 며칠 전부터 한쪽 눈의 시력 저하와 새로운 하지 저림이 지속된다. 가장 적절한 대응은?","options":["운동 강도를 높임","온열치료를 추가","재발을 의심해 의사에게 보고","1개월 후 재평가"],"answer":2,"exp":"새로운 신경 증상이 지속되면 재발 가능성이 있습니다. 운동 부하를 높이지 말고 신속히 의사에게 보고합니다."}],"seccion":"질환·외상과 재활","grupo":"신경계","icono":"🧠","mapa":"img/mapas/t39.jpg","fichas":[],"secuencias":[]},"40":{"id":40,"title":"척수손상","lead":"척수 손상으로 손상 높이 아래의 운동·감각·자율신경 기능이 장애됩니다. 잔존 기능에 맞춘 목표 설정과 합병증 예방이 중심입니다.","sheet":{"kind":"condition","items":[{"h":"병태","t":"추락·교통사고 등 외상이나 질환으로 척수가 손상되며 완전·불완전 손상으로 나뉩니다. 경수 손상은 사지마비, 흉요수 손상은 대마비가 됩니다."},{"h":"주요 증상","t":"손상 높이 이하의 운동마비와 감각장애, 방광·직장 장애, 자율신경 장애(기립성 저혈압, 체온조절 장애), 경직이 나타납니다."},{"h":"평가 포인트","t":"ASIA 기준으로 신경학적 손상 높이와 AIS를 판정하고 분절별 핵심근 MMT와 감각검사를 합니다. ADL은 FIM이나 SCIM으로 평가합니다."},{"h":"중재 흐름","t":"급성기는 호흡 관리·자세 잡기·가동범위 유지, 회복기는 잔존근 강화와 일어나기·이동·휠체어 구동 등 ADL 훈련을 합니다."},{"h":"주의사항·금기","t":"T6 이상 손상은 자율신경 반사부전에 주의합니다. 욕창 예방을 위한 압력 완화를 지도하고 기립성 저혈압은 단계적 기립으로 대응합니다."},{"h":"의사에게 의뢰","t":"급격한 혈압 상승과 두통·발한·안면 홍조, 신경 증상 악화, 발열, 욕창 악화, 하지 부종(심부정맥혈전증 의심)은 보고합니다."}]},"keypoints":["신경학적 손상 높이는 기능이 정상인 가장 아래 분절","C6 손상은 건고정 작용을 쥐기에 활용","자율신경 반사부전은 앉히고 방광 팽만 등 원인 제거","정기적인 압력 완화 동작으로 욕창 예방","경수 손상은 호흡 기능 평가와 객담 배출 지원"],"case":{"text":"25세 남성, C6 완전 손상(AIS A) 후 2개월. 훈련 중 갑자기 심한 두통, 안면 홍조, 발한이 나타나고 혈압이 현저히 상승함. 도뇨 예정 시각이 지나 있었음.","answer":"해설: 방광 팽만으로 유발된 자율신경 반사부전이 의심됩니다. 훈련을 중지하고 앉은 자세(머리 올림)로 하여 옷을 느슨하게 하고, 원인을 확인·제거하며 즉시 의사·간호사에게 보고합니다. 누운 채 경과를 보지 않습니다."},"questions":[{"level":"기초","q":"C7 분절의 핵심근으로, 푸시업에 의한 이동을 가능하게 하는 근육은?","options":["위팔두갈래근","위팔세갈래근","엉덩허리근","넙다리네갈래근"],"answer":1,"exp":"C7의 핵심근은 위팔세갈래근(팔꿈치 신전)입니다. 위팔두갈래근은 C5, 엉덩허리근은 L2, 넙다리네갈래근은 L3의 핵심근입니다."},{"level":"기초","q":"건고정 작용을 쥐기에 활용하는 대표적인 손상 높이는?","options":["C4","T6","C6","L3"],"answer":2,"exp":"C6 손상에서는 손목 신전이 가능하며, 손목을 신전하면 손가락이 수동적으로 굴곡되는 건고정 작용을 쥐기에 사용합니다."},{"level":"중급","q":"ASIA 장애 척도(AIS) A가 의미하는 것은?","options":["감각만 남은 불완전 손상","운동 기능이 일부 남음","신경학적으로 정상","S4-5의 운동·감각도 없음"],"answer":3,"exp":"AIS A는 최하위 천수(S4-5)의 운동·감각 기능이 남아 있지 않은 완전 손상입니다. B는 감각만 남은 불완전 손상입니다."},{"level":"중급","q":"자율신경 반사부전이 일어나기 쉬운 손상 높이는?","options":["T6 이상","T12 이하","L3 이하","말총"],"answer":0,"exp":"T6 이상 손상에서는 손상 부위 이하의 자극(방광 팽만 등)에 교감신경이 과도하게 반응하여 급격한 혈압 상승이 일어납니다."},{"level":"임상","q":"C6 손상 환자. 기립경사대의 경사를 올리자 어지럼, 안면 창백, 혈압 저하가 나타났다. 가장 적절한 대응은?","options":["경사를 더 올려 적응시킴","즉시 기립경사대를 수평으로","그대로 훈련을 계속","앉은 자세에서 목을 굽히게 함"],"answer":1,"exp":"기립성 저혈압이 의심됩니다. 경사를 되돌리고 증상과 혈압을 확인합니다. 복대나 탄력 스타킹, 단계적 기립으로 예방합니다."},{"level":"임상","q":"흉수 완전 손상의 휠체어 사용자. 천골 부위의 발적이 눌러도 사라지지 않고 지속된다. 가장 적절한 대응은?","options":["발적 부위를 강하게 마사지","앉는 시간을 늘려 적응","압력 완화 방법과 빈도를 재검토","특별한 대응 불필요"],"answer":2,"exp":"지속되는 발적은 욕창의 초기 징후입니다. 압력 완화 동작과 방석을 재검토하고 의료팀에 보고합니다. 발적 부위 마사지는 조직 손상을 악화시킵니다."}],"seccion":"질환·외상과 재활","grupo":"신경계","icono":"🧠","mapa":"img/mapas/t40.jpg","fichas":[],"secuencias":[]},"41":{"id":41,"title":"말초신경손상","lead":"외상이나 압박으로 말초신경이 손상되어 지배 영역의 운동·감각·자율신경 기능이 저하됩니다. 손상 정도와 회복 경과를 파악하는 것이 중요합니다.","sheet":{"kind":"condition","items":[{"h":"병태","t":"세든 분류에 따라 일시적 전도장애(신경무동작증), 축삭단열, 신경단열로 나눕니다."},{"h":"주요 증상","t":"지배근의 이완성 마비와 근위축, 지배 영역의 감각장애, 발한 장애가 나타납니다. 건반사는 저하 또는 소실됩니다."},{"h":"평가 포인트","t":"MMT, 감각검사(촉각·통각·2점 식별각), 티넬 징후 위치의 변화, 근전도·신경전도검사 결과를 확인합니다."},{"h":"중재 흐름","t":"보조기로 마비근의 과신장을 막고 관절가동범위를 유지합니다. 신경 재지배에 맞춰 능동보조운동에서 근력 강화로 단계적으로 진행합니다."},{"h":"주의사항·금기","t":"감각장애 부위는 화상이나 압박에 의한 손상에 주의합니다. 마비근의 과부하와 신경봉합술 후의 과도한 신장은 피합니다."},{"h":"의사에게 의뢰","t":"마비의 급격한 진행, 심한 통증이나 부종, 피부색 변화, 회복 예상 시기가 지나도 호전이 없으면 보고합니다."}]},"keypoints":["티넬 징후가 원위로 이동하면 신경 재생의 지표","손목 처짐·발처짐은 보조기로 구축과 과신장 예방","감각 저하 부위는 눈으로 확인해 보호하도록 지도","회복은 손상부에 가까운 근육부터 먼 근육 순","신경봉합술 후에는 의사가 지시한 고정 기간 준수"],"case":{"text":"45세 남성, 상완골 골간부 골절 후 손목과 손가락 신전이 안 됨. 손등의 엄지와 검지 사이에 감각 저하가 있음. 팔꿈치 신전은 가능.","answer":"해설: 상완골 골간부에서의 요골신경 마비(손목 처짐)가 의심됩니다. 손목 신전 위 보조기로 과신장과 구축을 막고 가동범위를 유지합니다. 회복 경과는 티넬 징후와 MMT로 추적하고, 호전이 없으면 의사에게 보고합니다."},"questions":[{"level":"기초","q":"손목 처짐을 일으키는 신경 마비는?","options":["정중신경","척골신경","요골신경","근피신경"],"answer":2,"exp":"요골신경은 손목과 손가락의 신근군을 지배하며, 마비되면 손목을 신전하지 못하는 손목 처짐이 됩니다."},{"level":"기초","q":"약지·소지가 변형되는 갈퀴손을 일으키는 신경 마비는?","options":["척골신경","요골신경","액와신경","대퇴신경"],"answer":0,"exp":"척골신경 마비에서는 골간근과 약지·소지의 충양근이 마비되어 약지·소지의 갈퀴 변형(갈퀴손)이 생깁니다."},{"level":"중급","q":"세든 분류에서 축삭은 보존되고 전도만 일시적으로 장애된 상태는?","options":["신경단열","신경무동작증","축삭단열","왈러 변성"],"answer":1,"exp":"신경무동작증은 축삭의 연속성이 보존된 일시적 전도장애로, 왈러 변성을 동반하지 않고 비교적 빨리 회복합니다."},{"level":"중급","q":"말초신경 재생의 경과 관찰에 사용하는 소견은?","options":["건반사 항진","바빈스키 반사","근강직","티넬 징후 위치의 이동"],"answer":3,"exp":"재생 중인 축삭 끝부분을 두드리면 퍼지는 저림이 생기며, 그 위치가 원위로 이동하는 것이 재생의 지표가 됩니다."},{"level":"임상","q":"하퇴 석고 고정 후 비골두 부위 압박으로 발목 배측굴곡이 불가능해졌다. 가장 적절한 대응은?","options":["발목을 저측굴곡 위로 유지","단하지 보조기로 발처짐에 대응","마비근에 고부하 저항운동","감각 저하부에 강한 온열"],"answer":1,"exp":"총비골신경 마비에 의한 발처짐에는 단하지 보조기로 보행 시 걸려 넘어짐과 저측굴곡 구축을 막습니다. 감각 저하부의 온열은 화상 위험이 있습니다."},{"level":"임상","q":"손목 손바닥쪽 자상 후 엄지 대립이 안 되고 무지구가 위축되었다. 손상이 의심되는 신경은?","options":["척골신경","요골신경 얕은가지","정중신경","근피신경"],"answer":2,"exp":"정중신경은 무지대립근 등 무지구근을 지배하며, 마비되면 엄지 대립이 어려운 원숭이손이 됩니다."}],"seccion":"질환·외상과 재활","grupo":"신경계","icono":"🧠","mapa":"img/mapas/t41.jpg","fichas":[],"secuencias":[]},"42":{"id":42,"title":"도수치료(메이틀랜드)","lead":"관절의 부속운동을 평가하고 등급화한 진동성 수동운동으로 통증과 가동범위에 작용하는 수기 체계입니다. 평가와 재평가의 반복이 특징입니다.","sheet":{"kind":"method","items":[{"h":"목적","t":"관절의 부속운동을 이용해 통증을 줄이고 관절 가동성을 개선합니다. 환자의 반응에 따라 수기와 강도를 선택합니다."},{"h":"주요 수기","t":"진동성 수동운동(오실레이션)을 등급 I~IV로 시행합니다. 등급 V는 고속·저진폭 추력(도수조작)입니다."},{"h":"적응증","t":"관절 유래 통증이나 관절낭·인대 단축에 의한 가동범위 제한(요통, 경부통, 동결견 등)이 주요 대상입니다."},{"h":"금기·주의","t":"골절, 악성종양, 감염, 염증성 질환 급성기, 고도 골다공증, 진행하는 신경 증상, 경부 혈관 장애 의심 시에는 시행하지 않습니다."},{"h":"시행 포인트","t":"통증 위주면 등급 I·II, 뻣뻣함 위주면 III·IV를 선택합니다. 시행 전후 비교 징후를 확인해 효과를 판정합니다."},{"h":"근거","t":"운동치료와 병행하면 단기적 통증 경감에 유용하다는 보고가 있습니다. 단독의 장기적 효과는 제한적이라고 알려져 있습니다."}]},"keypoints":["통증 위주면 등급 I·II, 뻣뻣함이면 III·IV","시행 전후 비교 징후를 확인해 효과 판정","부속운동은 좌우 차이와 끝느낌으로 평가","레드 플래그를 배제한 후 수기 시행","얻은 가동범위는 자가운동으로 유지"],"case":{"text":"50세 남성, 만성적인 우측 목 뻣뻣함. 안정 시 통증은 거의 없고, 우회전 끝범위에서 저항감과 가벼운 통증이 있음. 레드 플래그는 없음.","answer":"해설: 통증보다 뻣뻣함이 주이므로 저항 안으로 들어가는 등급 III·IV 선택을 고려합니다. 시행 전후 회전 가동범위와 통증을 재평가하고 자가운동으로 연결합니다. 평가 없이 강한 추력을 가하는 것은 피합니다."},"questions":[{"level":"기초","q":"메이틀랜드 등급 IV의 설명으로 옳은 것은?","options":["저항 직전에서 큰 진폭","가동범위 시작에서 작은 진폭","가동범위 끝에서 작은 진폭","저항 안에서 큰 진폭"],"answer":2,"exp":"등급 IV는 저항 안, 가동범위 끝에서 시행하는 작은 진폭의 운동입니다. 가동범위 시작의 작은 진폭은 I, 저항 안의 큰 진폭은 III입니다."},{"level":"기초","q":"주로 통증 경감을 목적으로 선택하는 등급은?","options":["등급 I·II","등급 III·IV","등급 V만","등급 IV만"],"answer":0,"exp":"등급 I·II는 저항에 들어가지 않는 범위에서 시행하며 주로 통증 경감에 사용합니다. III·IV는 뻣뻣함이나 가동범위 제한에 사용합니다."},{"level":"중급","q":"메이틀랜드 등급 V가 나타내는 수기는?","options":["저항 직전의 큰 진폭","고속·저진폭 추력","지속적 견인","연부조직 주무르기"],"answer":1,"exp":"등급 V는 가동범위 끝에서 시행하는 고속·저진폭 추력으로, 도수조작에 해당합니다."},{"level":"중급","q":"수기의 효과 판정을 위해 시행 전후에 비교하는 지표는?","options":["혈액검사 수치","영상 소견 변화","체중 변화","비교 징후(애스터리스크)"],"answer":3,"exp":"시행 전에 재현성 있는 증상이나 가동범위를 비교 징후로 기록하고, 시행 후 그 변화를 확인해 효과를 판정합니다."},{"level":"임상","q":"급성 요통 환자. 움직이면 심한 통증과 방어성 수축이 있다. 처음 선택할 등급으로 가장 적절한 것은?","options":["등급 IV","등급 V","등급 I·II","등급 III"],"answer":2,"exp":"통증이 심하고 반응하기 쉬운 상태에서는 저항에 들어가지 않는 등급 I·II로 통증 경감을 꾀합니다."},{"level":"임상","q":"경부통 환자. 목을 회전하자 어지럼, 복시, 구음장애가 나타났다. 가장 적절한 대응은?","options":["수기를 중지하고 의사에게 보고","등급 IV를 강화","추력으로 개선 시도","시행 횟수를 늘림"],"answer":0,"exp":"어지럼·복시·구음장애는 경부 혈관 장애를 의심하게 하는 신호입니다. 도수치료를 중지하고 의사에게 보고합니다."}],"seccion":"치료와 중재","grupo":"수기와 물리치료 기기","icono":"🤲","mapa":"img/mapas/t42.jpg","fichas":[],"secuencias":[]},"43":{"id":43,"title":"고유수용성 신경근 촉진법(PNF)","lead":"고유수용기 자극을 이용해 신경과 근육의 반응을 촉진하는 치료 수기입니다. 나선·대각선 운동 패턴이 특징이며 근력·협응·가동범위 개선에 사용합니다.","sheet":{"kind":"method","items":[{"h":"목적","t":"고유수용기를 자극해 운동 반응을 촉진하고 근력, 협응, 안정성, 관절가동범위의 개선을 꾀합니다."},{"h":"주요 수기","t":"견갑대·골반대·사지의 대각선 패턴에 율동적 개시, 유지-이완, 율동적 안정화 등을 조합합니다."},{"h":"적응증","t":"중추신경 질환, 정형외과 질환, 스포츠 손상 등에서 근력 저하, 협응 저하, 가동범위 제한, 관절 불안정성이 있을 때 사용합니다."},{"h":"금기·주의","t":"골유합 전의 골절부, 수술 후 저항이 허용되지 않은 부위, 심한 통증에는 시행하지 않습니다. 순환기 위험이 있으면 숨 참기에 주의합니다."},{"h":"시행 포인트","t":"도수 접촉, 언어 지시, 시각, 견인·압박, 신장, 최적 저항, 타이밍을 조합합니다. 저항은 부드럽게 움직일 수 있는 범위로 합니다."},{"h":"근거","t":"가동범위 개선이나 근기능 향상에 유용하다는 보고가 있습니다. 효과는 질환과 목적에 따라 다르며 다른 운동치료와 병행합니다."}]},"keypoints":["통증으로 가동범위가 제한되면 유지-이완","운동 시작이 어려우면 율동적 개시","저항은 부드러운 운동을 방해하지 않는 ‘최적 저항’","정상 타이밍에서 운동은 원위부터 시작","숨 참기를 피하고 호흡을 멈추지 않게 시행"],"case":{"text":"60세 여성, 어깨관절 주위염 후 외전 제한. 운동 시 통증이 심하고, 수동으로 신장하면 방어성 수축이 강해짐.","answer":"해설: 통증을 동반한 가동범위 제한에는 등척성 수축을 이용하는 유지-이완이 적합합니다. 통증이 심해지지 않는 범위에서 시행하고 시행 전후 가동범위를 재평가합니다. 강한 수동 신장을 반복하는 것은 피합니다."},"questions":[{"level":"기초","q":"PNF 운동 패턴의 특징으로 옳은 것은?","options":["단일 평면의 직선 운동","나선·대각선 운동","등속성 운동만","수동운동만"],"answer":1,"exp":"PNF 운동 패턴은 굴곡·신전, 내전·외전, 회전 요소를 조합한 나선·대각선 운동입니다."},{"level":"기초","q":"PNF에서 치료사의 손을 통해 운동 방향을 전달하는 기본 요소는?","options":["한랭 자극","전기 자극","도수 접촉","초음파"],"answer":2,"exp":"도수 접촉은 운동 방향으로의 압력을 손으로 전달해 환자의 근수축과 운동 방향을 이끄는 기본 요소입니다."},{"level":"중급","q":"운동 시작이 어려운 환자에게 사용하는 PNF 기법은?","options":["유지-이완","수축-이완","율동적 안정화","율동적 개시"],"answer":3,"exp":"율동적 개시는 수동→능동보조→능동→저항운동 순으로 진행하여 운동의 시작과 학습을 촉진합니다."},{"level":"중급","q":"등척성 교대 수축으로 관절의 안정성을 높이는 기법은?","options":["율동적 안정화","율동적 개시","수축-이완","반복 신장"],"answer":0,"exp":"율동적 안정화는 움직이지 않고 길항근군을 교대로 등척성 수축시켜 안정성을 높입니다."},{"level":"임상","q":"무릎 굴곡 가동범위가 통증으로 제한된 환자. 가동범위 개선에 가장 적절한 PNF 기법은?","options":["수축-이완","유지-이완","반복 신장","율동적 개시"],"answer":1,"exp":"유지-이완은 제한하는 근육을 등척성으로 수축시킨 뒤 이완시키는 기법으로, 통증을 동반한 가동범위 제한에 사용합니다."},{"level":"임상","q":"PNF 저항운동 중 환자가 숨을 참아 얼굴이 붉어졌다. 가장 적절한 대응은?","options":["저항을 더 강하게 함","반복 횟수를 늘림","호흡을 멈추지 않도록 지도","운동 속도를 높이게 함"],"answer":2,"exp":"숨 참기는 혈압 상승을 초래합니다. 저항을 조정하고 호흡을 계속하며 시행하도록 지도합니다."}],"seccion":"치료와 중재","grupo":"수기와 물리치료 기기","icono":"🤲","mapa":"img/mapas/t43.jpg","fichas":[],"secuencias":[]},"44":{"id":44,"title":"전기치료","lead":"전기 자극을 이용해 통증 경감이나 근수축 유발을 꾀하는 물리치료입니다. 목적에 따라 자극의 종류와 조건을 선택하고 금기를 반드시 확인합니다.","sheet":{"kind":"method","items":[{"h":"목적","t":"통증 경감, 근수축 유발을 통한 근력 유지·강화, 운동 재학습, 부종 경감 등을 목적으로 합니다."},{"h":"주요 종류","t":"TENS(경피적 전기신경자극), NMES(신경근 전기자극), FES(기능적 전기자극), 간섭파 치료, 고전압 맥동전류 치료 등이 있습니다."},{"h":"적응증","t":"급성·만성 통증, 수술 후나 부동에 의한 근력 저하, 뇌졸중 후 마비근 촉진, 발처짐에 대한 보행 시 자극 등에 사용합니다."},{"h":"금기·주의","t":"심장박동기 등 이식형 전자기기, 임신부의 복부·허리, 경동맥동 부위, 악성종양 부위, 피부 손상 부위, 감각장애 부위는 피합니다."},{"h":"시행 포인트","t":"피부 상태와 감각을 확인하고 전극 위치와 크기, 주파수, 펄스 폭, 강도, 통전 시간을 목적에 맞게 설정합니다."},{"h":"근거","t":"수술 후 넙다리네갈래근 근력 저하나 뇌졸중 후 기능 회복에 유용하다는 보고가 있습니다. 통증 효과는 보고에 따라 차이가 있습니다."}]},"keypoints":["통전 전 피부 상태와 감각장애 유무를 확인","이식형 전자기기 유무를 문진으로 반드시 확인","통증에는 TENS, 근수축 유발에는 NMES 선택","종료 후 전극 아래 발적이나 열감이 없는지 관찰","전기 자극은 능동운동 훈련과 병행"],"case":{"text":"65세 남성, 인공슬관절 치환술 후. 넙다리네갈래근 수의 수축이 약하고 SLR에서 무릎이 끝까지 펴지지 않음(신전 지연). 심장박동기는 없고 피부 이상도 없음.","answer":"해설: 넙다리네갈래근의 근력 저하와 수축 부전에 대해 NMES를 능동운동과 병행하는 것을 고려합니다. 수술 상처를 피해 전극을 붙이고 피부와 통증 반응을 확인합니다. 창상 부위나 감각 저하 부위의 통전은 피합니다."},"questions":[{"level":"기초","q":"감각 수준 자극으로 주로 통증 경감을 목적으로 하는 전기치료는?","options":["FES","TENS","NMES","초음파치료"],"answer":1,"exp":"TENS는 경피적으로 감각신경을 자극해 통증 경감을 꾀합니다. NMES는 근수축 유발, FES는 동작 보조가 목적입니다."},{"level":"기초","q":"보행 등 동작에 맞춰 근육을 자극하여 기능을 보완하는 전기치료는?","options":["TENS","초음파치료","FES","핫팩"],"answer":2,"exp":"FES(기능적 전기자극)는 동작 타이밍에 맞춰 근육을 자극하여 발처짐 보행 등의 기능을 보완합니다."},{"level":"중급","q":"전기치료의 금기로 옳은 것은?","options":["만성 요통","수술 후 근력 저하","발처짐","심장박동기 이식"],"answer":3,"exp":"이식형 전자기기는 전기 자극으로 오작동할 우려가 있어 금기입니다. 다른 선택지는 전기치료의 적응증입니다."},{"level":"중급","q":"2개의 중주파 전류를 교차시켜 심부에 저주파 자극을 만드는 방법은?","options":["간섭파 치료","TENS","FES","이온도입법"],"answer":0,"exp":"간섭파 치료는 주파수가 다른 2개의 중주파 전류를 교차시켜 그 차이에 해당하는 저주파 자극을 심부에 만듭니다."},{"level":"임상","q":"인공슬관절 치환술 후 넙다리네갈래근 수의 수축이 약한 환자. 가장 적절한 선택은?","options":["온열치료만 시행","NMES를 능동운동과 병행","창상 위에 전극 부착","근수축이 돌아올 때까지 안정"],"answer":1,"exp":"NMES는 수술 후 넙다리네갈래근 수축 부전에 사용하며 능동운동과 병행합니다. 전극은 수술 상처를 피해 붙입니다."},{"level":"임상","q":"전기 자극 종료 후 전극을 붙였던 부위 피부에 발적과 수포가 보였다. 가장 적절한 대응은?","options":["강도를 올려 계속","같은 위치에 다시 부착","중지하고 피부 확인·보고","따뜻하게 하며 경과 관찰"],"answer":2,"exp":"전극 부위의 발적이나 수포는 피부 손상 가능성이 있습니다. 통전을 중지하고 피부 상태를 기록해 보고합니다."}],"seccion":"치료와 중재","grupo":"수기와 물리치료 기기","icono":"🤲","mapa":"img/mapas/t44.jpg","fichas":[],"secuencias":[]},"45":{"id":45,"title":"초음파·레이저·온열·한랭치료","lead":"열, 음파, 빛, 냉각을 이용해 통증과 조직 상태에 작용하는 물리치료입니다. 시기와 목적에 따라 온열과 한랭 중 무엇을 쓸지 선택하고 금기를 확인합니다.","sheet":{"kind":"method","items":[{"h":"목적","t":"통증 경감, 근긴장 완화, 조직 신장성 향상, 급성 염증에 의한 부종 억제 등을 목적으로 운동치료 전후에 사용합니다."},{"h":"주요 종류","t":"초음파치료(연속·펄스), 저출력 레이저, 표재열(핫팩·파라핀욕), 극초단파, 한랭치료(아이스팩 등)."},{"h":"적응증","t":"온열은 만성기 통증·뻣뻣함·구축, 한랭은 급성 외상 후 통증과 부종, 초음파는 연부조직 신장성 향상 등에 사용합니다."},{"h":"금기·주의","t":"급성 염증·출혈 경향·악성종양 부위의 온열, 눈·임신부 복부·성장기 골단판의 초음파, 레이노 현상 부위의 한랭은 피합니다."},{"h":"시행 포인트","t":"시행 전 피부와 온냉각을 확인하고 시행 중에도 피부를 관찰합니다. 초음파 프로브는 계속 움직이며 한 부위에 머물지 않습니다."},{"h":"근거","t":"운동치료의 보조로 단기적 통증 경감에 사용됩니다. 단독 효과는 제한적이라는 보고가 많으며 중심은 운동치료입니다."}]},"keypoints":["급성기 부종·열감에는 한랭, 만성 뻣뻣함에는 온열","시행 전 온냉각을 확인하고 감각장애 부위는 피함","초음파 프로브는 멈추지 말고 계속 움직임","온열 후 신장이나 운동을 하면 조합하기 쉬움","물리치료는 운동치료의 보조로 자리매김"],"case":{"text":"22세 남성, 축구 중 발목 내번 염좌, 손상 다음 날. 외측 복사뼈 주위에 부종과 열감, 압통이 있고 체중부하 시 통증이 심함. 골절은 의사가 배제함.","answer":"해설: 급성기 염증 소견이 있어 한랭치료와 압박·거상으로 통증과 부종 경감을 꾀합니다. 온열은 부종을 악화시킬 우려가 있어 이 시기에는 피합니다. 동상을 막기 위해 시행 중 피부를 관찰합니다."},"questions":[{"level":"기초","q":"급성기 부종과 통증 경감에 사용하는 물리치료는?","options":["핫팩","파라핀욕","한랭치료","극초단파"],"answer":2,"exp":"한랭치료는 혈관을 수축시켜 급성기 통증과 부종을 억제합니다. 다른 선택지는 온열치료로, 급성 염증에는 피합니다."},{"level":"기초","q":"표재열로 분류되는 것은?","options":["극초단파","핫팩","연속 초음파","저출력 레이저"],"answer":1,"exp":"핫팩이나 파라핀욕은 피부에서 얕은 조직을 데우는 표재열입니다. 극초단파와 연속 초음파는 심부열로 분류됩니다."},{"level":"중급","q":"초음파치료의 금기 부위로 옳은 것은?","options":["넙다리네갈래근","어깨관절 주위","종아리세갈래근","안구"],"answer":3,"exp":"안구는 초음파치료의 금기 부위입니다. 임신부 복부, 성장기 골단판, 악성종양 부위 등도 피합니다."},{"level":"중급","q":"초음파치료의 시행 방법으로 옳은 것은?","options":["프로브를 계속 움직임","같은 부위에 정지시킴","젤 없이 적용","통증이 생겨도 계속"],"answer":0,"exp":"프로브를 한곳에 멈추면 열이 집중되어 조직을 손상할 위험이 있으므로 젤을 사용해 계속 움직입니다."},{"level":"임상","q":"손상 다음 날의 발목 염좌로 부종과 열감이 심하다. 가장 적절한 물리치료는?","options":["핫팩","한랭치료와 압박·거상","파라핀욕","극초단파"],"answer":1,"exp":"급성기 염증 소견에는 한랭치료와 압박·거상으로 통증과 부종을 억제합니다. 온열은 부종을 악화시킬 우려가 있습니다."},{"level":"임상","q":"당뇨병성 신경병증으로 발 감각이 저하된 환자에게 발 핫팩이 검토되고 있다. 가장 적절한 대응은?","options":["온도를 올려 짧게 시행","평소대로 시행","감각 저하부 온열은 피함","취침 중 장시간 적용"],"answer":2,"exp":"감각장애 부위는 뜨거움을 잘 느끼지 못해 화상 위험이 높으므로 온열치료를 피하고 다른 방법을 검토합니다."}],"seccion":"치료와 중재","grupo":"수기와 물리치료 기기","icono":"🤲","mapa":"img/mapas/t45.jpg","fichas":[],"secuencias":[]},"46":{"id":46,"title":"수치료·마사지·도수 림프 배액","lead":"물의 부력·수압·온도를 이용하는 수치료와, 손으로 연부조직에 작용하는 마사지·도수 림프 배액입니다. 적응증과 금기를 가려내는 것이 핵심입니다.","sheet":{"kind":"method","items":[{"h":"목적","t":"수치료는 부력·수압·온열로 운동과 통증 완화를 돕습니다. 마사지는 근긴장 완화, 도수 림프 배액은 림프부종 감소를 목적으로 합니다."},{"h":"주요 기법·종류","t":"와류욕, 허바드 탱크, 수중 운동치료. 마사지는 경찰법·유날법·압박법 등. 림프부종에는 복합적 치료(피부 관리·도수 배액·압박·운동)."},{"h":"적응증","t":"체중부하를 제한해야 하는 관절 질환이나 수술 후, 통증·근긴장 항진, 암 수술 후 등의 이차성 림프부종, 원발성 림프부종."},{"h":"금기·주의","t":"발열, 급성 감염(봉와직염 등), 급성 심부정맥혈전증, 개방창, 비대상성 심부전. 수중에서는 정수압으로 심장 부담이 커지는 점에 주의합니다."},{"h":"실시 포인트","t":"림프 배액은 부종 부위보다 중심 쪽부터 피부를 밀어 움직이는 정도의 가벼운 압으로 합니다. 수중 운동은 수온·시간·컨디션과 입수 전후 활력징후를 확인합니다."},{"h":"근거","t":"림프부종에서는 압박치료를 포함한 복합적 치료로 시행하는 것이 권장됩니다. 마사지 단독의 효과는 제한적이며 운동치료와 병행합니다."}]},"keypoints":["부력은 체중부하를 줄이며 수심에 따라 부담이 달라짐","정수압은 정맥 환류를 돕지만 심장 부담도 커짐","림프 배액은 중심 쪽부터 가벼운 압으로 시작","발적·열감·발열은 감염을 의심하고 중단","림프부종은 압박치료를 포함한 복합적 치료로"],"case":{"text":"65세 여성. 유방암 수술 후 이차성 림프부종으로 환측 상지 둘레가 건측보다 큼. 피부 발적·열감이나 발열은 없고, 심부정맥혈전증 진단도 없음.","answer":"감염이나 혈전 징후가 없어 복합적 치료의 적응으로 판단함. 피부 관리, 중심 쪽부터 가벼운 압의 도수 배액, 압박치료, 압박 상태의 운동을 병행함. 발적이나 발열이 생기면 중단하고 의사에게 의뢰함."},"questions":[{"level":"기초","q":"수중에서 관절에 가해지는 체중 부담을 줄여 주는 물의 성질은?","options":["부력","점성","비열","표면장력"],"answer":0,"exp":"부력은 체중을 상쇄하는 방향으로 작용하여 체중부하를 줄입니다. 점성은 움직임에 대한 저항, 비열은 온열 효과와 관련됩니다."},{"level":"기초","q":"도수 림프 배액에서 가장 먼저 시행하는 부위로 가장 적절한 것은?","options":["부종이 가장 심한 원위부","부종 부위보다 중심 쪽 부위","손가락·발가락 끝","통증이 심한 부위만"],"answer":1,"exp":"먼저 중심 쪽(림프절이나 몸통 쪽)을 배액하여 흐름의 길을 만든 뒤 원위부로 진행합니다."},{"level":"중급","q":"도수 림프 배액의 금기로 가장 적절한 것은?","options":["만성 이차성 림프부종","유지기의 상지 림프부종","급성 심부정맥혈전증","경도의 피부 건조"],"answer":2,"exp":"급성 심부정맥혈전증은 혈전이 이동할 우려가 있어 금기입니다. 만성 림프부종은 적응증이며, 피부 건조는 피부 관리로 대응합니다."},{"level":"중급","q":"림프부종의 복합적 치료에 포함되지 않는 것은?","options":["피부 관리","도수 림프 배액","압박치료","환측 사지의 장기간 안정 고정"],"answer":3,"exp":"복합적 치료는 피부 관리·도수 배액·압박치료·압박 상태의 운동치료로 구성됩니다. 장기간 안정 고정은 포함되지 않습니다."},{"level":"임상","q":"60대 여성. 유방암 수술 후 상지 부종 배액 중 환측에 갑작스런 발적·열감과 발열이 나타났다. 대응으로 가장 적절한 것은?","options":["배액 압을 강하게 한다","시술을 중단하고 의사에게 보고","온열치료를 추가한다","압박을 강하게 하여 계속한다"],"answer":1,"exp":"봉와직염 등 급성 감염을 의심하는 소견입니다. 배액·압박·온열은 중단하고 신속히 의사에게 의뢰합니다."},{"level":"임상","q":"70대 남성. 심부전이 있으며 안정 시에도 숨이 차다. 수중 운동치료를 검토할 때 판단으로 가장 적절한 것은?","options":["심장 부담 증가로 의사와 적응 확인","부력이 있으므로 제한 없이 시행","깊은 수심에서 장시간 시행","수온을 높게 하여 시행"],"answer":0,"exp":"수중에서는 정수압으로 정맥 환류가 늘어 심장 부담이 커집니다. 증상이 안정되지 않은 심부전에서는 의사와 적응을 확인합니다."}],"seccion":"치료와 중재","grupo":"수기와 물리치료 기기","icono":"🤲","mapa":"img/mapas/t46.jpg","fichas":[],"secuencias":[]},"47":{"id":47,"title":"키네시오 테이핑","lead":"신축성 테이프를 피부에 붙여 감각 입력이나 관절 운동 보조를 노리는 방법입니다. 부착의 기본과 피부 트러블 예방을 익히고 운동치료의 보조로 사용합니다.","sheet":{"kind":"method","items":[{"h":"목적","t":"피부 감각 입력을 통한 근활동 보조, 관절 운동 유도, 자세 인식, 부종이나 피하출혈 감소 보조를 목표로 합니다. 강한 고정은 목적이 아닙니다."},{"h":"주요 기법·종류","t":"I자·Y자·X자·부채꼴(림프용) 등의 형태. 근육용, 관절 보조용, 부종용 부착법이 있습니다. 고정에는 비신축성 테이프를 사용합니다."},{"h":"적응증","t":"스포츠 손상 후 통증이나 종창 감소 보조, 근육 사용법의 재학습, 자세·정렬의 인식, 운동치료와 병행한 사용."},{"h":"금기·주의","t":"피부 손상·감염·습진, 테이프 피부염 병력, 심부정맥혈전증 의심, 피부가 약한 고령자. 감각장애 부위는 피부 트러블을 알아차리기 어려워 주의합니다."},{"h":"실시 포인트","t":"피부를 깨끗하고 건조하게 하고 모서리를 둥글게 자릅니다. 양 끝은 장력 없이 붙입니다. 처음엔 작게 시험하고 가려움·발적이 생기면 바로 떼도록 지도합니다."},{"h":"근거","t":"통증 등에 대한 효과는 단기적·제한적이라는 보고가 많아, 단독 치료가 아닌 운동치료의 보조로 자리매김하는 것이 타당합니다."}]},"keypoints":["신축성 테이프는 고정이 아닌 보조가 목적","양 끝은 장력 없이 피부에 얹듯이 부착","피부를 깨끗하고 건조하게, 모서리는 둥글게","가려움·발적이 생기면 바로 뗌","효과는 제한적이므로 운동치료와 병행"],"case":{"text":"22세 남성. 발목 내번 염좌 수상 3일 후로, 바깥 복사뼈 주위에 종창과 피하출혈이 있음. 체중부하 시 통증은 경도. 테이핑 경험은 없고 피부질환 병력도 없음.","answer":"먼저 피부 상태를 확인하고 작게 시험 부착함. 종창 부위에는 부채꼴을 장력을 적게 하여 붙이고 운동치료와 병행함. 테이프로 낫는다고 설명하지 않으며, 가려움이나 발적이 생기면 떼도록 안내함."},"questions":[{"level":"기초","q":"신축성 테이프의 양 끝을 붙일 때 장력으로 가장 적절한 것은?","options":["최대로 늘려서 붙인다","끝만 강하게 늘린다","장력 없이 붙인다","피부를 집어서 붙인다"],"answer":2,"exp":"양 끝(앵커)은 장력 없이 피부에 얹듯이 붙입니다. 끝에 장력이 있으면 피부가 당겨져 떨어지거나 피부염의 원인이 됩니다."},{"level":"기초","q":"테이프를 두 갈래로 잘라 근복을 감싸듯 붙이는 형태는?","options":["I자","X자","부채꼴","Y자"],"answer":3,"exp":"Y자는 밑동을 한 곳에 붙이고 두 갈래로 나뉜 부분으로 근복을 감쌉니다. 부채꼴은 가늘게 나눠 부종 부위에 펼치는 형태입니다."},{"level":"중급","q":"테이핑 후 즉시 떼도록 지도해야 하는 소견은?","options":["부착 부위의 가려움이나 발적","운동 후 가벼운 근육 뭉침","자세를 의식하기 쉬워짐","움직이기 편하다고 느낌"],"answer":0,"exp":"가려움이나 발적은 테이프 피부염 등 피부 트러블의 징후입니다. 악화를 막기 위해 바로 떼도록 지도합니다."},{"level":"중급","q":"관절 움직임을 강하게 제한하여 고정하고 싶을 때 적합한 것은?","options":["신축성 테이프 I자","비신축성 테이프","신축성 테이프 부채꼴","장력 없는 Y자"],"answer":1,"exp":"강한 고정에는 비신축성 테이프를 사용합니다. 신축성 테이프는 관절 움직임을 잘 방해하지 않으며 보조나 감각 입력이 목적입니다."},{"level":"임상","q":"20대 남성. 발목 염좌 후 종창에 테이핑을 예정하고 있다. 부착 전에 확인할 것으로 가장 중요한 것은?","options":["보행 속도","안정 시 심박수","피부 상태와 피부염 병력","주로 쓰는 발"],"answer":2,"exp":"부착 전에는 피부 손상·습진이나 테이프 피부염 병력을 확인합니다. 피부 트러블이 있으면 부착을 보류합니다."},{"level":"임상","q":"30대 여성. 어깨 테이핑 후 ‘통증이 줄었다’고 말한다. 설명으로 가장 적절한 것은?","options":["조직이 회복되어 나았다","효과는 대개 일시적, 운동치료 병행","계속 붙이고 있어야 한다","근력이 곧바로 강해졌다"],"answer":1,"exp":"테이핑 효과는 단기적이고 제한적이라고 알려져 있습니다. 과도한 기대를 주지 않고 운동치료의 보조임을 설명합니다."}],"seccion":"치료와 중재","grupo":"수기와 물리치료 기기","icono":"🤲","mapa":"img/mapas/t47.jpg","fichas":[],"secuencias":[]},"48":{"id":48,"title":"운동치료","lead":"운동을 처방하여 근력·유연성·지구력·균형을 개선하고 ADL 향상을 목표로 하는 물리치료의 핵심입니다. 부하의 원칙과 중단 기준을 이해하고 안전하게 진행합니다.","sheet":{"kind":"method","items":[{"h":"목적","t":"관절가동범위, 근력, 근지구력, 전신지구력, 유연성, 균형·협응을 개선하여 기본 동작과 ADL, 생활 참여를 높이는 것입니다."},{"h":"주요 기법·종류","t":"관절가동운동(수동·능동 보조·능동), 근력강화운동(등척성·등장성〈구심성·원심성〉·등속성), 스트레칭, 유산소 운동, 균형·협응 훈련."},{"h":"적응증","t":"근골격계 질환, 수술 후, 신경계 질환, 심장·호흡 등 내부 장애, 폐용증후군, 고령자의 기능 저하 등 폭넓은 대상에 사용합니다."},{"h":"금기·주의","t":"불안정한 심질환, 조절되지 않는 고혈압, 급성 염증, 고정되지 않은 골절 부위 등은 주의·금기입니다. 앤더슨 기준 등 운동 중단 기준을 확인합니다."},{"h":"실시 포인트","t":"과부하·특이성·가역성 원칙으로 부하를 정하고 자각적 운동강도와 활력징후를 확인합니다. 보상운동을 놓치지 말고, 숨을 참지 않고 호흡하게 합니다."},{"h":"근거","t":"많은 근골격계 질환과 만성 질환에서 운동치료는 치료의 핵심으로 권장됩니다. 지속할 수 있는 내용으로 구성하는 것이 효과와 직결됩니다."}]},"keypoints":["과부하·특이성·가역성 원칙으로 부하를 구성","수술 후 초기엔 관절을 움직이지 않는 등척성 운동부터","숨 참기(힘주기)를 피하고 호흡을 계속함","보상운동을 놓치지 않고 바른 동작으로 시행","흉통·식은땀·심한 호흡곤란은 즉시 중단 후 보고"],"case":{"text":"72세 여성. 인공 슬관절 치환술 후 3주. 넙다리네갈래근 MMT는 3으로, 능동운동으로 전 가동범위를 움직일 수 있으나 저항은 견디지 못함. 활력징후는 안정적임.","answer":"중력에 저항하는 능동운동부터 시작하여 가벼운 저항을 단계적으로 추가함. 보상운동과 통증을 확인하고 숨 참기를 피함. 첫날부터 최대 부하 운동은 시행하지 않음."},"questions":[{"level":"기초","q":"근육이 장력을 발휘하면서 늘어나는 수축 양식은?","options":["구심성 수축","원심성 수축","등척성 수축","등속성 수축"],"answer":1,"exp":"원심성 수축은 근육이 늘어나면서 힘을 발휘하는 수축입니다. 구심성은 짧아지면서, 등척성은 근 길이 변화 없이 힘을 발휘합니다."},{"level":"기초","q":"근력을 높이기 위해 일상보다 큰 부하를 주어야 한다는 원칙은?","options":["특이성의 원칙","가역성의 원칙","과부하의 원칙","개별성의 원칙"],"answer":2,"exp":"과부하의 원칙은 일상적인 부하를 넘는 자극을 주어야 적응이 일어난다는 개념입니다."},{"level":"중급","q":"관절 운동 없이 근력을 높일 수 있어 수술 후 초기에 사용하기 쉬운 운동은?","options":["등척성 운동","등속성 운동","점프 운동","고부하 원심성 운동"],"answer":0,"exp":"등척성 운동은 관절을 움직이지 않고 근육을 수축시키므로 관절이나 수술 부위의 부담을 줄여 초기부터 시행할 수 있습니다."},{"level":"중급","q":"근력강화운동 시행 중 피해야 할 것은?","options":["호흡을 계속한다","보상운동을 확인한다","준비운동을 한다","숨을 참는다"],"answer":3,"exp":"숨 참기(힘주기)는 혈압을 급상승시킵니다. 특히 고령자나 심질환이 있는 사람은 호흡을 멈추지 않고 시행합니다."},{"level":"임상","q":"70대 남성. 넙다리네갈래근 MMT는 3이다. 근력강화운동의 시작으로 가장 적절한 것은?","options":["최대 저항 등속성 운동","항중력 능동운동부터 단계적 부하","수동운동만 시행","고강도 점프 운동"],"answer":1,"exp":"MMT 3은 중력에 저항하여 전 가동범위를 움직일 수 있는 단계입니다. 능동운동부터 시작해 가벼운 저항을 단계적으로 추가합니다."},{"level":"임상","q":"60대 남성. 자전거 에르고미터 운동 중 흉통과 식은땀이 나타났다. 대응으로 가장 적절한 것은?","options":["중단, 활력징후 확인 후 의사에게 보고","부하를 낮춰 계속한다","휴식 후 같은 부하로 재개한다","스트레칭으로 바꾼다"],"answer":0,"exp":"흉통과 식은땀은 운동 중단 기준에 해당하며 심질환 가능성이 있습니다. 즉시 중단하고 활력징후를 확인해 의사에게 보고합니다."}],"seccion":"치료와 중재","grupo":"운동치료와 전문 분야","icono":"🩺","mapa":"img/mapas/t48.jpg","fichas":[],"secuencias":[{"nombre":"브리지","rotulo":"단련 부위","texto":"볼기근·햄스트링","frames":["img/mov/ponte-1.jpg","img/mov/ponte-2.jpg","img/mov/ponte-3.jpg"]},{"nombre":"하지 직거상 운동","rotulo":"단련 부위","texto":"넙다리네갈래근","frames":["img/mov/elevacao-1.jpg","img/mov/elevacao-2.jpg","img/mov/elevacao-3.jpg"]},{"nombre":"스쿼트","rotulo":"단련 부위","texto":"넙다리네갈래근·볼기근","frames":["img/mov/agachamento-1.jpg","img/mov/agachamento-2.jpg","img/mov/agachamento-3.jpg"]}]},"49":{"id":49,"title":"호흡 물리치료","lead":"호흡법 지도, 객담 배출 보조, 운동치료로 환기와 호흡곤란을 개선하는 물리치료입니다. COPD나 수술 후 폐합병증 예방에서 중심적인 역할을 합니다.","sheet":{"kind":"method","items":[{"h":"목적","t":"환기 개선, 기도 청결 촉진, 호흡곤란 감소, 운동 내성과 ADL 향상, 수술 후 폐합병증 예방을 목표로 합니다."},{"h":"주요 기법·종류","t":"입술 오므리기 호흡, 횡격막 호흡, 체위배액법, 허핑·기침 지도, 호흡 보조, 호흡근 훈련, 전신지구력 운동·근력강화운동."},{"h":"적응증","t":"COPD 등 만성 호흡기 질환, 폐렴, 흉부·복부 수술 전후, 신경근 질환에 의한 환기 장애, 가래가 많은 기관지확장증 등."},{"h":"금기·주의","t":"머리를 낮춘 체위배액은 두개내압 상승·불안정한 순환·객혈 등에서 피합니다. 처치 안 된 기흉, 심한 부정맥에도 주의하며 SpO2와 증상을 확인합니다."},{"h":"실시 포인트","t":"청진이나 영상 소견으로 가래 위치를 확인해 체위를 고릅니다. SpO2·호흡수·맥박·수정 보그 척도를 확인하고 동작은 호흡에 맞춰 속도를 조절합니다."},{"h":"근거","t":"COPD에서는 운동치료를 중심으로 한 호흡재활이 호흡곤란과 운동 내성 개선에 권장됩니다."}]},"keypoints":["입술 오므리기 호흡은 날숨 시 기도 허탈을 방지","체위배액은 가래가 있는 폐구역을 위로 함","허핑은 성문을 연 채 강하고 빠르게 내쉼","머리 낮춘 자세는 두개내압 상승·객혈 시 피함","COPD 호흡재활은 운동치료가 중심"],"case":{"text":"74세 남성. COPD로 가정 산소요법은 하지 않음. 보행이나 옷 갈아입기에서 숨참이 심하고, 서둘러 움직인 뒤 SpO2가 저하됨. 가래는 적고 안정 시 상태는 안정적임.","answer":"입술 오므리기 호흡과 동작 속도 조절을 지도하고, SpO2와 호흡곤란을 보면서 지구력 운동과 하지 근력강화를 진행함. 숨을 참고 서둘러 움직이는 것은 피하도록 안내함."},"questions":[{"level":"기초","q":"COPD에서 날숨 시 기도 허탈을 막기 위해 지도하는 호흡법은?","options":["빠르고 얕은 흉식 호흡","숨 참기","입술 오므리기 호흡","과환기"],"answer":2,"exp":"입술 오므리기 호흡은 날숨에 저항을 주어 기도 내압을 유지하고, 기도 허탈을 막아 호기를 돕습니다."},{"level":"기초","q":"가래가 있는 폐구역을 위로 한 자세를 취해 중력으로 가래 이동을 촉진하는 방법은?","options":["허핑","체위배액법","호흡근 훈련","입술 오므리기 호흡"],"answer":1,"exp":"체위배액법은 가래가 고인 폐구역을 위로 하여 중력을 이용해 중심 기도로 이동시킵니다."},{"level":"중급","q":"성문을 연 채 강하고 빠르게 내쉬어 가래를 이동시키는 기법은?","options":["기침 억제","횡격막 호흡","발살바법","허핑"],"answer":3,"exp":"허핑은 성문을 연 채 강제로 내쉬는 기법으로, 기침보다 흉강 내압 상승이 적으면서 가래를 이동시킵니다."},{"level":"중급","q":"머리를 낮춘 체위배액법을 피해야 하는 상태는?","options":["두개내압 상승","만성 기관지확장증","가래가 많은 폐렴","하엽 무기폐"],"answer":0,"exp":"머리를 낮춘 자세는 두개내압을 높이므로 두개내압 상승 시 피합니다. 다른 보기는 체위배액의 적응이 될 수 있는 상태입니다."},{"level":"임상","q":"70대 남성, COPD. 보행 중 숨참이 심해지고 SpO2가 저하된다. 지도로 가장 적절한 것은?","options":["빨리 걸어 일찍 끝낸다","입술 오므리기 호흡과 속도 조절","숨을 참고 동작한다","보행을 완전히 중단한다"],"answer":1,"exp":"호흡에 맞춰 동작 속도를 조절하고 입술 오므리기 호흡을 병행합니다. 활동을 완전히 중단하면 폐용이 진행됩니다."},{"level":"임상","q":"복부 수술 다음 날의 환자. 수술 후 폐합병증 예방으로 가장 적절한 것은?","options":["며칠간 침상 안정","통증이 있어 호흡 연습은 삼간다","조기 거동과 심호흡·기침 지도","머리 낮춘 자세를 장시간 유지"],"answer":2,"exp":"조기 거동과 심호흡·기침(창상 부위를 누르고 하는 기침) 지도는 무기폐와 폐렴 예방에 중요합니다."}],"seccion":"치료와 중재","grupo":"운동치료와 전문 분야","icono":"🩺","mapa":"img/mapas/t49.jpg","fichas":[],"secuencias":[]},"50":{"id":50,"title":"심장재활","lead":"운동치료·환자 교육·생활 지도를 결합한 포괄적 프로그램입니다. 운동 내성과 삶의 질(QOL)을 높이고 재발 예방을 목표로 합니다. 안전 관리가 최우선입니다.","sheet":{"kind":"method","items":[{"h":"목적","t":"운동 내성과 삶의 질 향상, 관상동맥 위험인자 교정, 재발·재입원 예방, 심리적 불안 감소, 사회 복귀 지원을 목표로 합니다."},{"h":"주요 기법·종류","t":"유산소 운동(걷기·자전거 에르고미터), 저항 운동, 환자 교육, 복약·식사·금연 등 생활 지도. 급성기·회복기·유지기의 세 시기로 진행합니다."},{"h":"적응증","t":"급성 심근경색 후, 협심증, 심장 수술 후, 만성 심부전, 대혈관 질환, 말초동맥질환 등. 병세가 안정적인 것이 전제입니다."},{"h":"금기·주의","t":"불안정형 협심증, 조절되지 않는 부정맥, 비대상성 심부전, 증상이 있는 중증 대동맥판 협착증, 급성 심근염 등은 운동치료의 금기입니다."},{"h":"실시 포인트","t":"강도는 심폐운동부하검사의 무산소성 역치(AT)나 자각적 운동강도로 정합니다. 베타차단제 복용 중엔 심박수가 잘 오르지 않아 증상·혈압·심전도도 봅니다."},{"h":"근거","t":"관상동맥질환과 만성 심부전에서는 운동치료를 포함한 포괄적 심장재활이 가이드라인에서 권장됩니다."}]},"keypoints":["운동·교육·생활 지도를 결합하여 시행","강도는 AT나 자각적 운동강도로 설정","베타차단제 복용 시 심박수만으로 강도를 정하지 않음","흉통·ST 변화·부정맥 출현 시 중단","급격한 체중 증가·부종은 심부전 악화를 의심"],"case":{"text":"63세 남성. 급성 심근경색 치료 후 회복기에 외래에서 운동치료 중. 베타차단제를 복용함. 자전거 에르고미터 중 흉부 증상은 없으나 심박수가 잘 오르지 않음.","answer":"베타차단제로 심박수 반응이 둔하므로 심박수만으로 부하를 올리지 않고 자각적 운동강도·혈압·심전도로 판단함. 흉통이나 ST 변화가 나타나면 중단하고 의사에게 보고함."},"questions":[{"level":"기초","q":"심장재활의 구성 요소에 포함되지 않는 것은?","options":["운동치료","환자 교육","관상동맥 위험인자 교정","장기간의 침상 안정"],"answer":3,"exp":"심장재활은 운동치료·환자 교육·생활 지도·상담을 포함하는 포괄적 프로그램입니다. 장기간의 침상 안정은 폐용을 초래합니다."},{"level":"기초","q":"심폐운동부하검사에서 얻어 운동강도 설정에 사용하는 지표는?","options":["도수근력검사","무산소성 역치(AT)","관절가동범위","악력"],"answer":1,"exp":"무산소성 역치(AT)는 유산소 운동의 강도 설정에 자주 쓰이는 지표로, 심폐운동부하검사로 구합니다."},{"level":"중급","q":"운동치료의 금기로 가장 적절한 것은?","options":["안정된 만성 심부전","관상동맥우회술 후 회복기","불안정형 협심증","심근경색 후 안정기"],"answer":2,"exp":"불안정형 협심증은 운동치료의 금기입니다. 병세가 안정된 만성 심부전이나 수술 후·경색 후 회복기는 적응증입니다."},{"level":"중급","q":"베타차단제를 복용하는 환자에서 운동강도 기준으로 유용한 것은?","options":["자각적 운동강도(보그 척도)","심박수만","체중","체온"],"answer":0,"exp":"베타차단제는 심박수 상승을 억제하므로 심박수만으로는 강도를 과대 설정할 우려가 있습니다. 자각적 운동강도를 병용합니다."},{"level":"임상","q":"60대 남성. 심근경색 후 회복기. 보행 연습 중 흉통과 심전도 ST 하강이 나타났다. 대응으로 가장 적절한 것은?","options":["보행 속도를 높인다","그대로 계속하며 지켜본다","수분 보충 후 같은 부하로 재개","운동을 중단하고 의사에게 보고"],"answer":3,"exp":"흉통과 ST 하강은 심근 허혈을 나타내는 중단 소견입니다. 즉시 운동을 중단하고 의사에게 보고합니다."},{"level":"임상","q":"70대 여성, 만성 심부전. 며칠 사이 체중이 급격히 늘고 하퇴 부종과 숨참이 악화되었다. 대응으로 가장 적절한 것은?","options":["운동강도를 높인다","심부전 악화 의심, 의사에게 보고","평소대로 시행한다","근력 훈련만 추가한다"],"answer":1,"exp":"단기간의 체중 증가·부종·숨참 악화는 심부전 악화의 신호입니다. 운동치료를 보류하고 의사에게 보고합니다."}],"seccion":"치료와 중재","grupo":"운동치료와 전문 분야","icono":"🩺","mapa":"img/mapas/t50.jpg","fichas":[],"secuencias":[]},"51":{"id":51,"title":"골반저·여성 건강","lead":"골반저근 기능장애로 인한 요실금이나 골반장기탈출증, 임신·출산 후 신체 변화 등을 다루는 영역입니다. 올바른 수축 지도와 레드 플래그 확인이 기본입니다.","sheet":{"kind":"method","items":[{"h":"목적","t":"골반저근의 근력·지구력·협응을 개선해 요실금이나 골반장기탈출증 증상을 줄입니다. 임신·출산 후 요골반 통증이나 체간 기능 회복도 지원합니다."},{"h":"주요 기법·종류","t":"골반저근 훈련, 바이오피드백, 복압과 호흡 조절 지도, 자세·동작 지도, 생활 지도(배뇨 습관·체중 관리 등)."},{"h":"적응증","t":"복압성 요실금, 혼합성 요실금, 경도의 골반장기탈출증, 출산 후 골반저 기능 저하, 복직근 이개, 전립선 전절제술 후 남성의 요실금."},{"h":"금기·주의","t":"내진 평가는 전문 연수와 충분한 설명·동의가 전제입니다. 임신 후기 긴 바로 누운 자세는 앙와위 저혈압 증후군에 주의. 혈뇨·발열·회음부 저림은 의사에게."},{"h":"실시 포인트","t":"조이고 끌어올리는 수축을 확인하고 복근·볼기근·모음근의 힘주기나 숨 참기를 피합니다. 빠른 수축과 지속 수축을 연습하고 일상에서 지속하게 합니다."},{"h":"근거","t":"복압성 요실금에 대해 골반저근 훈련은 보존치료의 첫 번째 선택으로 권장됩니다. 지속할 수 있는지가 효과를 좌우합니다."}]},"keypoints":["골반저근은 ‘조이고 끌어올리기’로 지도","숨 참기나 볼기근 힘주기는 보상으로 피함","기침·재채기 시 새는 것은 복압성 요실금","임신 후기 긴 바로 누운 자세는 저혈압에 주의","갑작스러운 배뇨장애·회음부 저림은 의사에게"],"case":{"text":"38세 여성. 출산 후 1년. 기침이나 재채기 시 소변이 샘. 상체를 일으키면 복부 정중선이 불룩 솟음. 혈뇨·발열·회음부 감각 이상은 없음.","answer":"복압성 요실금과 복직근 이개를 고려함. 올바른 골반저근 수축과 숨 참기를 피한 복압 조절을 지도함. 갑자기 강한 윗몸일으키기를 반복하는 운동은 피함."},"questions":[{"level":"기초","q":"골반저를 구성하는 주요 근육은?","options":["엉덩허리근(장요근)","큰볼기근(대둔근)","항문올림근(항문거근)","넙다리곧은근(대퇴직근)"],"answer":2,"exp":"항문올림근은 꼬리근과 함께 골반가로막을 이루는 골반저의 주요 근육입니다. 나머지는 고관절 주위 근육입니다."},{"level":"기초","q":"기침이나 재채기 등으로 복압이 높아질 때 소변이 새는 요실금은?","options":["절박성 요실금","복압성 요실금","일류성 요실금","기능성 요실금"],"answer":1,"exp":"복압성 요실금은 복압 상승 시 요도 폐쇄가 불충분하여 발생합니다. 절박성은 강한 요의를 동반하는 요실금입니다."},{"level":"중급","q":"골반저근 훈련의 수축 지도로 가장 적절한 것은?","options":["숨을 참고 배에 힘을 준다","볼기근을 강하게 조인다","배를 앞으로 내민다","요도·질·항문을 조여 끌어올린다"],"answer":3,"exp":"골반저근은 조이며 끌어올리듯 수축시킵니다. 숨 참기·볼기근 힘주기·배를 내미는 움직임은 보상입니다."},{"level":"중급","q":"임신 후기에 장시간 바로 누운 자세를 취할 때 주의해야 할 것은?","options":["앙와위 저혈압 증후군","복직근 이개의 개선","골반저근의 비대","요실금의 소실"],"answer":0,"exp":"임신 후기 바로 누운 자세에서는 자궁이 하대정맥을 압박해 혈압이 떨어질 수 있습니다. 옆으로 누운 자세 등으로 바꿉니다."},{"level":"임상","q":"38세 여성. 출산 후 1년, 기침 시 소변이 새고 상체를 일으키면 복부 정중선이 불룩 솟는다. 중재로 가장 적절한 것은?","options":["강한 윗몸일으키기를 매일 많이","골반저근 훈련과 복압 조절 지도","수분 섭취를 극단적으로 줄인다","안정만 권한다"],"answer":1,"exp":"복압성 요실금과 복직근 이개가 의심됩니다. 올바른 골반저근 수축과 복압 조절부터 시작합니다."},{"level":"임상","q":"50대 여성. 요통으로 통원 중 갑작스러운 배뇨 곤란과 회음부 저림을 호소했다. 대응으로 가장 적절한 것은?","options":["골반저근 훈련을 강화한다","다음 방문까지 지켜본다","즉시 의사에게 연락한다","허리 스트레칭을 한다"],"answer":2,"exp":"갑작스러운 배뇨장애와 회음부 감각장애는 마미증후군을 의심하는 레드 플래그입니다. 즉시 의사에게 의뢰합니다."}],"seccion":"치료와 중재","grupo":"운동치료와 전문 분야","icono":"🩺","mapa":"img/mapas/t51.jpg","fichas":[],"secuencias":[]},"52":{"id":52,"title":"소아 물리치료","lead":"발달 중인 아동을 대상으로 운동 발달과 활동·참여를 지원하는 물리치료입니다. 정상 발달 지식을 토대로 놀이와 가족과의 협력으로 진행합니다.","sheet":{"kind":"method","items":[{"h":"목적","t":"운동 발달 촉진, 기본 동작과 이동 능력 획득, 구축·변형 등 이차 장애 예방, 가정·어린이집·학교에서의 활동과 참여 확대, 가족 지원입니다."},{"h":"주요 기법·종류","t":"신경발달학적 접근, 과제지향 훈련, 놀이를 활용한 운동, 자세 관리, 보조기·자세 유지 의자·보행기 활용, 가족 지도."},{"h":"적응증","t":"뇌성마비, 발달 지연, 다운증후군, 이분척추, 뒤센형 근이영양증, 저체중 출생아, 정형외과 질환 등."},{"h":"금기·주의","t":"경직형 뇌성마비는 고관절 아탈구·탈구 확인이 중요합니다. 근이영양증은 피로가 남는 고부하 운동을 피합니다. 뇌전증 발작이나 피로에 주의합니다."},{"h":"실시 포인트","t":"평가에는 GMFM, GMFCS, 원시반사·자세반응을 사용합니다. 아이가 즐기는 놀이 속에서 연습하고, 가족과 생활 목표를 공유해 가정에서도 지속하게 합니다."},{"h":"근거","t":"목표가 명확한 과제지향 훈련이나 가족과 협력한 중재가 지지되는 경향이 있습니다. 기법 단독보다 생활 속 실천을 중시합니다."}]},"keypoints":["목 가누기는 생후 3~4개월경이 기준","GMFCS는 뇌성마비 대동작을 5단계로 분류","경직형 뇌성마비는 고관절 탈구를 정기적으로 확인","근이영양증은 피로가 남는 고부하를 피함","목표는 가족과 공유하고 놀이 속에서 연습"],"case":{"text":"5세 남아. 경직형 양측마비. 보행기로 실내를 이동하나 발끝 접지가 두드러짐. 가족은 ‘어린이집에서 친구들과 함께 이동하고 싶다’고 희망함.","answer":"가족의 희망을 생활 장면의 목표로 삼아 보행기 이동 연습을 놀이나 어린이집 활동과 연결함. 하퇴삼두근 단축 예방, 보조기 검토, 고관절 확인도 시행함. 정상 발달 순서에만 얽매이지 않음."},"questions":[{"level":"기초","q":"목 가누기 획득 시기의 기준은?","options":["생후 1개월","생후 3~4개월","생후 7~8개월","생후 12개월"],"answer":1,"exp":"목 가누기는 생후 3~4개월경이 기준입니다. 이후 뒤집기·앉기·잡고 서기·독립 보행 순으로 진행합니다."},{"level":"기초","q":"뇌성마비 아동의 대동작 기능을 5단계로 분류하는 척도는?","options":["GMFM","MMT","FIM","GMFCS"],"answer":3,"exp":"GMFCS는 대동작 기능을 5단계로 분류합니다. GMFM은 대동작 기능을 점수로 측정하는 평가 척도입니다."},{"level":"중급","q":"뒤센형 근이영양증에서 피해야 할 운동은?","options":["피로가 남는 고부하 운동","관절가동운동","호흡 연습","놀이를 활용한 운동"],"answer":0,"exp":"근섬유가 손상되기 쉬우므로 피로를 강하게 남기는 고부하 운동은 피합니다. 구축 예방과 호흡 연습은 중요합니다."},{"level":"중급","q":"경직형 뇌성마비 아동에서 정기적인 확인이 중요한 합병증은?","options":["전방십자인대 파열","회전근개 파열","고관절 아탈구·탈구","발목 염좌"],"answer":2,"exp":"고관절 주위근의 경직과 근 불균형으로 고관절 아탈구·탈구가 일어나기 쉬워 정기적인 확인이 필요합니다."},{"level":"임상","q":"4세 아동. 경직형 양측마비. 보행 목표를 설정하는 방법으로 가장 적절한 것은?","options":["치료사 혼자 정한다","가족과 공유해 생활 목표 설정","정상 발달 순서만 엄수한다","놀이 없이 반복 연습만 한다"],"answer":1,"exp":"목표는 가족과 공유하고 가정이나 어린이집에서의 구체적 활동과 연결합니다. 놀이를 활용하면 연습을 지속하기 쉬워집니다."},{"level":"임상","q":"7세 남아, 뒤센형 근이영양증. 계단 오르내리기가 어려워지고 있다. 운동 방침으로 가장 적절한 것은?","options":["피로 없는 범위로 활동 유지·구축 예방","고부하 원심성 운동으로 근력 강화","운동을 모두 금지한다","매일 한계까지 걷게 한다"],"answer":0,"exp":"과도한 부하는 근손상을 진행시킬 우려가 있습니다. 피로가 남지 않는 범위에서 활동량을 유지하고 구축 예방을 계속합니다."}],"seccion":"치료와 중재","grupo":"운동치료와 전문 분야","icono":"🩺","mapa":"img/mapas/t52.jpg","fichas":[],"secuencias":[]},"53":{"id":53,"title":"노인 물리치료","lead":"노화에 따른 기능 저하, 노쇠, 근감소증, 낙상에 대한 대응이 중심입니다. 생활 기능과 참여를 지키기 위해 평가에 근거하여 안전하게 운동을 지속하도록 지원합니다.","sheet":{"kind":"method","items":[{"h":"목적","t":"ADL과 생활 기능·참여의 유지·향상, 낙상 예방, 노쇠·근감소증 예방과 개선, 폐용증후군 예방, 돌봄 제공자의 부담 경감입니다."},{"h":"주요 기법·종류","t":"하지·체간 근력강화운동, 균형 훈련, 보행 훈련, 이중과제 훈련, 일어나기·옮겨 앉기 동작 훈련, 보조기기 선정, 주거 환경 조정."},{"h":"적응증","t":"노쇠, 근감소증, 낙상 경험자, 골절이나 수술 후, 만성 질환으로 인한 활동 저하, 입원으로 인한 폐용, 치매가 있는 사람의 활동 지원."},{"h":"금기·주의","t":"기립성 저혈압, 골다공증성 척추체 골절, 다약제 복용 부작용, 탈수, 피부 취약성, 인지 기능 저하에 주의합니다. 갑작스러운 통증·증상 변화는 의사에게."},{"h":"실시 포인트","t":"TUG, 한발 서기, 의자에서 일어서기, 보행 속도, 악력 등으로 평가해 개별 목표를 세웁니다. 부하는 단계적으로 올리고 영양과 함께 지속을 돕습니다."},{"h":"근거","t":"균형과 근력 요소를 포함한 운동 중재는 지역사회 노인의 낙상 예방에 효과적이라고 알려져 있습니다. 지속할 수 있는 내용이 중요합니다."}]},"keypoints":["프리드 노쇠 기준에는 보행 속도 저하가 있음","근감소증은 근육량과 근력·신체 기능의 저하","낙상 예방은 균형과 근력을 함께 훈련","장기 와상 후 거동 시 기립성 저혈압에 주의","골다공증의 급성 등 통증은 척추체 골절을 의심"],"case":{"text":"82세 여성. 최근 1년간 2회 낙상. TUG가 연장되었고 의자에서 일어설 때 손 짚기가 필요함. 골다공증 치료 중이며 등 통증은 없음. 혼자 살며 외출을 자제하고 있음.","answer":"낙상 위험이 높은 상태임. 균형 훈련과 하지 근력강화를 단계적으로 병행하고, 주거 환경 조정과 외출 기회 마련도 함께함. 안정을 권하거나 첫날부터 고부하 운동을 하는 것은 피함."},"questions":[{"level":"기초","q":"프리드의 노쇠 기준에 포함되는 항목은?","options":["시력 저하","혈압 상승","보행 속도 저하","키 증가"],"answer":2,"exp":"프리드 기준은 체중 감소·피로감·활동량 저하·보행 속도 저하·근력(악력) 저하의 5항목입니다."},{"level":"기초","q":"노화 등으로 근육량이 줄고 근력이나 신체 기능이 저하된 상태는?","options":["근감소증","골다공증","골관절염","기립성 저혈압"],"answer":0,"exp":"근감소증은 근육량 감소에 근력 또는 신체 기능 저하가 동반된 상태입니다. 골다공증은 골량의 감소입니다."},{"level":"중급","q":"일어나 걸어가기 검사(TUG)로 평가하는 내용으로 가장 적절한 것은?","options":["악력","일어서기·보행·방향 전환 동작","인지 기능만","호흡 기능"],"answer":1,"exp":"TUG는 의자에서 일어나 걷고 방향을 바꿔 돌아와 앉기까지의 시간을 재어 이동 능력과 낙상 위험을 평가합니다."},{"level":"중급","q":"장기 와상 후 노인이 처음 앉거나 설 때 특히 주의해야 할 것은?","options":["회전근개 파열","저체온","손가락 구축","기립성 저혈압"],"answer":3,"exp":"와상이 계속되면 혈압 조절 기능이 떨어져 일어나거나 설 때 혈압이 내려가기 쉽습니다. 증상과 혈압을 확인합니다."},{"level":"임상","q":"80대 여성. 낙상 경험이 있고 TUG가 연장되었으며 하지 근력이 저하되어 있다. 중재로 가장 적절한 것은?","options":["균형 훈련과 하지 근력강화 병행","스트레칭만 시행","안정을 권한다","첫날부터 최대 부하 근력 훈련"],"answer":0,"exp":"낙상 예방에는 균형과 근력 요소를 결합한 운동이 효과적입니다. 부하는 단계적으로 올립니다."},{"level":"임상","q":"85세 여성, 골다공증. 가볍게 엉덩방아를 찧은 뒤 갑자기 심한 등 통증이 생겼다. 대응으로 가장 적절한 것은?","options":["체간 굴곡 운동을 강화한다","온열로 경과를 본다","의사에게 보고해 영상 평가 의뢰","등 근육 스트레칭을 한다"],"answer":2,"exp":"골다공증이 있는 노인의 경미한 외상 후 급성 등 통증은 척추체 압박골절을 의심합니다. 운동을 진행하지 않고 의사에게 의뢰합니다."}],"seccion":"치료와 중재","grupo":"운동치료와 전문 분야","icono":"🩺","mapa":"img/mapas/t53.jpg","fichas":[],"secuencias":[]},"54":{"id":54,"title":"임상 증례","lead":"임상 추론은 문진에서 가설을 세우고, 평가로 검증하며, 통합과 해석을 거쳐 목표와 중재를 정하는 흐름입니다. 재평가로 가설을 계속 수정하는 것이 중요합니다.","sheet":{"kind":"basics","items":[{"h":"문진","t":"주호소, 발병 경과, 통증 부위와 양상, 악화·완화 요인, 과거력, 복약, 생활 배경, 본인의 희망을 듣습니다. 레드 플래그도 여기서 확인합니다."},{"h":"가설 수립","t":"문진에서 생각할 수 있는 원인이나 병태를 여러 개 나열하고 확인할 평가 항목을 정합니다. 처음부터 하나로 단정하지 않는 것이 중요합니다."},{"h":"평가","t":"시진·촉진, 관절가동범위, MMT, 특수검사, 신경학적 검사, 동작 분석 등으로 가설을 검증합니다. 좌우 차이와 재현성을 확인합니다."},{"h":"통합과 해석","t":"평가 결과를 ICF 틀(신체 기능·활동·참여·환경)로 정리하고, 문제점 간의 관련성과 우선순위를 생각합니다."},{"h":"목표 설정","t":"본인·가족과 공유하며 구체적이고 측정 가능하며 기한이 있는 단기·장기 목표를 세웁니다. 생활 장면의 목표를 중시합니다."},{"h":"중재와 재평가","t":"목표에 따라 중재를 선택하고 같은 지표로 변화를 재평가합니다. 개선되지 않으면 가설과 평가로 돌아가 재검토합니다."}]},"keypoints":["문진 단계에서 레드 플래그를 반드시 확인","가설은 여러 개 세우고 평가로 하나씩 검증","문제점은 ICF 틀로 정리","목표는 본인과 공유하고 측정 가능·기한 설정","개선되지 않으면 가설과 평가부터 재검토"],"case":{"text":"68세 남성. 양측 무릎 골관절염. 보행 시 오른쪽 무릎 통증이 있고, 오른쪽 넙다리네갈래근 근력 저하와 무릎 신전 제한이 있음. 희망은 ‘손주와 근처 공원까지 걷고 싶다’.","answer":"통증·근력 저하·가동범위 제한과 보행 제한을 정리하고, 공원까지의 보행을 목표로 기한을 정함. 근력강화와 관절가동운동을 시행하고 통증과 보행 거리로 재평가함. 영상 소견만으로 중재를 결정하지 않음."},"questions":[{"level":"기초","q":"임상 추론의 흐름에서 문진 다음에 하는 것으로 가장 적절한 것은?","options":["중재를 시작한다","가설을 세운다","목표를 최종 결정한다","퇴원 지도를 한다"],"answer":1,"exp":"문진에서 얻은 정보로 원인이나 병태의 가설을 세우고, 이를 검증할 평가 항목을 고릅니다."},{"level":"기초","q":"목표 설정 방법으로 가장 적절한 것은?","options":["치료사 혼자 정한다","추상적인 표현에 그친다","기한을 두지 않는다","측정 가능하고 기한이 있는 목표"],"answer":3,"exp":"목표는 본인·가족과 공유하고 구체적이며 측정 가능하고 기한이 있게 합니다. 이를 통해 재평가에서 변화를 판단할 수 있습니다."},{"level":"중급","q":"ICF에서 ‘계단을 오르내릴 수 없다’가 분류되는 영역은?","options":["활동","참여","신체 기능·신체 구조","환경 요인"],"answer":0,"exp":"계단 오르내리기 등 개인이 수행하는 동작은 ‘활동’에 분류됩니다. 사회적 역할에 관여하는 것은 ‘참여’입니다."},{"level":"중급","q":"중재 후 재평가에서 개선이 보이지 않을 때 대응으로 가장 적절한 것은?","options":["같은 중재를 계속한다","평가를 생략한다","가설과 평가를 재검토한다","환자의 노력 부족으로 판단"],"answer":2,"exp":"개선되지 않으면 가설이나 평가가 적절했는지 되돌아가 병태 파악과 중재를 재검토합니다."},{"level":"임상","q":"50대 남성. 거상 도중 어깨 외측 통증, 호킨스-케네디 검사 양성, 수동 가동범위는 정상. 가장 의심되는 것은?","options":["동결견","견봉하 충돌증후군","경추증성 신경근병증","흉곽출구증후군"],"answer":1,"exp":"거상 도중의 통증호와 호킨스-케네디 검사 양성은 견봉하 충돌증후군을 시사합니다. 동결견에서는 수동 가동범위도 제한됩니다."},{"level":"임상","q":"60대 여성. 요통이 있고 암 병력이 있으며 야간통과 원인 불명의 체중 감소가 있다. 대응으로 가장 적절한 것은?","options":["허리 운동치료를 시작한다","도수 교정을 시행한다","온열로 경과를 본다","의사에게 정보 제공·평가 의뢰"],"answer":3,"exp":"암 병력·야간통·체중 감소는 중대한 질환을 의심하는 레드 플래그입니다. 중재 전에 의사에게 의뢰합니다."}],"seccion":"치료와 중재","grupo":"임상 증례","icono":"🧩","mapa":"img/mapas/t54.jpg","fichas":[],"secuencias":[]}}};
